window.__D("text/torat-shmuel/c010",{"p":[[2000510211,"כסא הכבוד<sup data-n=\"521\">43</sup> כו'. וזהו דודי שלח ידו מן החור שהוא בחי' שפע רצה\"ע הנק' כתר שלמעלה מן החכ' שבא שלא כסדר ההשתל' (ושם בבחי' הכתר הנק' עתיקא נא' לית שמאלא בהאי עתיקא סתימאה דכולא ימינא, ולכן נא' ב\"פ ימין ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב, כי הגבו' דשם הם ג\"כ בחי' חסדים ונק' ימין, ומהם נמשך להיות תרעץ אויב כו' וד\"ל). ועי\"ז ומעי המו עליו שנתעוררו המלאכים הנק' מעיים דכנס\"י ברחמים רבים על נפשם, ועי\"ז ממילא נתעוררו מן השינה גם שפשטתי את כותנתי כו' וד\"ל.",[["521","43","<b>שחתר לו חתירה מתחת כסה\"כ כי הנה ארז\"ל גדולה תשובה שמגעת עד כסה\"כ</b>: בד\"ה דודי שלח ידו בפלח הרמון שם נוספה כאן הגהת הר\"ה מפאריטש, וז\"ל: כן הי' לשון אדמו\"ר [הצ\"צ] שליט\"א, ויש שפירשו דבריו שכסה\"כ הוא מדריגה גבוה מאד שאין שם מקום למלאכים ולזה נתקבלה תשובת מנשה. ולפי דעתי הי' הכוונה שבתשו' שמגעת עד כסה\"כ יש מקום להימין ולהשמאל, אך הקב\"ה חתר לו חתירה מתחת כסה\"כ וע\"ד ומתחת זרועות עולם שהוא בחי' סוכ\"ע ולכן נתקבלה תשובתו כי ע\"פ השתל' לא הי' באפשרי שתתקבל מצד תגבורת הדין על החסד כו' אך מצד הסוכ\"ע נתקבלה התשו' כו'.\nבסיום המאמר בפלח הרמון שם מביא הר\"ה מפאריטש ששאל את כ\"ק אדמו\"ר הצ\"צ אודות ב' הפירושים בדבריו, וז\"ל: שאלתי ממנו ענין חתר חתירה. והשיב: שב' הפי' הנ\"ל שניהם אמת. ופי' הראשון קבלתי שתשובת מנשה הי' מבחי' כסה\"כ יתפרש ענין כסה\"כ הוא בחי' התגלות עתיק בבינה ומשם נתקבלה התשו', ופי' זה הוא פי' הפשוט. ופי' הב' הוא מכי\"ק אדמו\"ר הזקן נ\"ע [ראה גם לקו\"ת האזינו עד, סע\"ד. דרושים לשמע\"צ צב, סע\"א. וראה תו\"א משפטים עז, א. סידור עם דא\"ח צח, ג]. שבחי' כסה\"כ הוא בבחי' בריאה והוא בחי' כיסוי והסתר כו', ולכן הי' צ\"ל חתירה מתחת כסה\"כ כנ\"ל. — וראה כפי' הא' באוה\"ת שה\"ש (כרך ב) שם ע' תקכט: כסא הכבוד הוא בינה הנק' קדה\"ק ושם התגלות עתיק ע\"כ זהו והחמישית לפרעה דלית שמאלא כו' ולכן חתר לו חתירה מתחת כסא הכבוד. אוה\"ת תולדות קלז, ב ואילך. וראה גם ד\"ה בלילה ההוא בסה\"מ תש\"כ שם ס\"ע 96."]]],[2000510212,"<h3>ויאמר כו' ראה נתתיך כו'</h3>\n<b>בס\"ד.</b>\n<b></b>מלך הכבוד כו' משה מאצי' כו' מותר להתגרות\nוארא\n<b>ויאמר</b> ה' אל משה ראה נתתיך<sup data-n=\"522\">1</sup> אלקי' לפרעה ואהרן אחיך יהי' נביאך, וארז\"ל במד\"ר בתחלת רות אמר הקב\"ה למשה אע\"פ שקראתי אותך אלקי' לפרעה, אלקיך אנכי, אני על גבך, וזהו שאה\"כ (תילי' נו\"ן) אלקי' אלקיך אנכי, ולכאו' יפלא מהו צריך לומר אלקיך אנכי, אני על גבך, והאיך יעלה על הדעת באופן אחר, עד שצ\"ל אמר הקב\"ה למשה כו'.\n<b>והענין</b> דהנה ברבות במקומו ארז\"ל ע\"פ זה למה קרא להקב\"ה מלך הכבוד שהוא חולק כבוד ליראיו, כיצד מלך בשר ודם אין רוכבין על סוסו ואין יושבין על כסאו, והקב\"ה הושיב לשלמה על כסאו שנא' וישב שלמה על כסא ה' למלך (דה\"א ך\"ט), והרכיב לאליהו על סוסו, ומהו סוסו של הקב\"ה סופה וסערה שנא' ה' בסופה ובסערה (בפסוק כתי' ובשערה בשין שמאלית) דרכו (נחום א') וכתי' ויעל אלי' בסערה השמימה (מ\"ב ב'), מלך בשר ודם אין קוראין בשמו קיסר אגוסטא ואם נקראי' בשמו ממיתין אותו, והקב\"ה קרא למשה בשמו שנא' ראה",[["522","1","<b>ויאמר ה'. . ראה נתתיך</b>: מאמר זה מיוסד על ד\"ה ראה נתתיך באוה\"ת וארא ס\"ע רל ואילך. וראה גם סד\"ה הוא אהרן ומשה באוה\"ת וארא שם רכט-ל. וד\"ה ברבות כו' ע\"פ ביום השמיני באוה\"ת וארא ע' ב'תקצג ואילך. אוה\"ת ויחי (כרך ו) תתסו, ב (עיי\"ש). תתסז, א ואילך.\nחלק גדול מהמאמר נמצא בשינוי ההתחלה וסיום ובהוספות בד\"ה להבין כו' שורש ענין נשמות דאצי' בסה\"מ תרל\"ב ח\"א ע' מב ואילך. ובד\"ה ואם זרוע כאל שם ע' רד ואילך. והובא ונתבאר בד\"ה ראה נתתיך: בסה\"מ עזר\"ת ע' קכט ואילך. תשט\"ו ע' 225 ואילך. ובד\"ה החודש הזה לכם בסה\"מ תשכ\"ב ע' קצ ואילך. וראה עוד לעניני המאמר: יהל אור ע' שסו. לקו\"ש חט\"ז ע' 74 ואילך. שיחת ש\"פ וארא תשט\"ו. התוועדויות תשמ\"ב ח\"ב ע' 740. ס' המלך במסיבו ח\"ב ע' קיט. וע' קכה. פלח הרמון שמות ע' סד. וראה גם אוה\"ת ויחי (כרך ז) תתתסז, א ואילך.\nחלק מהמאמר הוא מד\"ה להבין מ\"ש כו' ואם זרוע כאל בס' מאמרי אדה\"ז תקס\"ו ע' קפט ואילך [הובא באוה\"ת וארא שם], וכאן הוא בשינויים והוספות. מאמר אדה\"ז נמצא בארוכה ובתוס' הגהות בד\"ה איתא במדרש משל בהמן רשיעא באוה\"ת מג\"א (הוצאת תש\"נ) ס\"ע רסד ואילך. ובד\"ה ויבז בעיניו תשכ\"ו."]]],[2000510213,"נתתיך אלקי' לפרעה אמר הקב\"ה למשה פרעה הרשע עשה עצמו אלקה שנא' לי יאורי ואני עשיתיני (יחזקאל ך\"ט) לפיכך יראה אותך ויאמר שזה אלקה, פי' על כרחו יודה לומר עליך זה אלקה, וזהו שחלק מכבודו ליראיו. ומסיים כי גבוה מעל גבוה שומר וגבוהי' עליהם (קהלת ה'), והיינו הגם כי חלק מכבודו ליראיו שז\"ע שקראו אלקי' לפרעה, מ\"מ אלקיך אנכי שאני על גבך.\n<b>והענין</b> הוא דהנה משה הי' מאצי', ונודע שאצי' הוא אלקות, כי לשון אצי' הוא מלשון ויאצל<sup data-n=\"523\">2</sup> מן הרוח, שהאציל מן הרוח אשר על משה, ונתן על ע' איש הזקנים, ועם כי זהו כמדליק נר מנר<sup data-n=\"524\">3</sup> זה נהנה וזה לא חסר כלום, מ\"מ ה\"ה נחשב להפרשת הארה שענין ההארה הוא ג\"כ שלא חסר כלום מן המאור ע\"י הארתו כו', א\"כ אצי' הוא בחי' גילוי הארה מאלקותו ית', שלכן נק' אצי' בשם אלקות כו'. וגם ענין אצי' נת' במ\"א שז\"ע גילוי ההעלם<sup data-n=\"525\">4</sup> מאלקות, שאלקות לרוב העלמו אינו מושג כלל וכלל, ולכן גם הכתר שהוא ממוצע בין המאציל לנאצלי' ה\"ה ג\"כ נעלם ונק' ישת חושך סתרו ע\"ש העלמו, ומה שנתגלה להיות נק' בשם חכים הגם שג\"ז עדיין חכים ולא בחכ' ידיעא, מ\"מ להיותו נק' בשם חכים ומבין נק' בשם אצי' שהוא בחי' גילוי ההעלם מאלקותו ית', משא\"כ בי\"ע הם נבראי' בע\"ג ונפרדי', ובחי' המל' דאצי' מהוה בי\"ע בדרך יש מאין אשר לכן נק' אצי' אלקות נגד בי\"ע, וכנודע ממארז\"ל אלמלא מתכנשין כל באי עולם אינם יכולי' לברוא אפי' כנף יתוש א', כי יכולת הבריאה לברוא יש מאין הוא לאלקות לבדו. וא\"כ יובן שפיר מה שאצי' נק' אלקות, שמל' דאצי' מהוה כל ג' עולמות בי\"ע כו', וכמ\"ש באגה\"ק<sup data-n=\"526\">5</sup> שאפי' בכלי' דאצי' מתייחד בהון לברוא ע\"י יש מאין כו'. ואי לזאת יובן שמשה נק' אלקי' לפרעה להיותו נשמה מבחי' האצי' והרי האצי' נק' אלקות נגד בי\"ע, וכ\"ש לפרעה, ולכן אמר לו ראה נתתיך אלקי' לפרעה [וכן נק' איש האלקים]<sup data-n=\"527\">6</sup> להיותו נשמה דאצי' כו'.\n<b>ומ\"מ</b> אמר לו אע\"פ שקראתי אותך אלקי' לפרעה מ\"מ אלקיך אנכי אני על גבך, שבאמת לגבי אוא\"ס אצי' ועשי' שוין וכמ\"ש כולם בחכמה עשית שגם החכמה נחשבת כעשי' גשמי'<sup data-n=\"528\">7</sup> לפניו ית', שהרי א\"ק שגבוה הרבה מבחי' האצי', שאצי' נחשב בכלליות העולמות רק בחי' אדם דעשי' וא\"ק נק' אדם דבריאה<sup data-n=\"529\">8</sup>, ומ\"מ",[["523","2","<b>ונודע שאצי' הוא אלקות. . מלשון ויאצל</b>: ראה בארוכה תו\"א בראשית ג, א. וירא יד, א. מאמרי אדה\"ז תקס\"ג ע' רצב ואילך. אוה\"ת ואתחנן ע' קפו ואילך. לקמן ע' שכח. ועוד."],["524","3","<b>ואם כי זהו כמדליק נר מנר</b>: ראה בארוכה לקו\"ש ח\"ח ע' 75 ואילך. וש\"נ."],["525","4","<b>ענין אצי' נת' במ\"א שז\"ע גילוי ההעלם</b>: תו\"א משפטים עו, ב. (וראה גם שם עה, ד). ובארוכה מאמרי אדה\"ז תקס\"ג שם. ואוה\"ת ואתחנן שם. אוה\"ת בלק ע' תתקפד ואילך. ענינים ס\"ע רא ואילך. ס\"ע רסז-ח. וראה גם שם ע' צב. ובארוכה המשך תרס\"ו ע' קס ואילך. תער\"ב ח\"א ע' יא ואילך. ח\"ב ע' תרלט ואילך. ועוד."],["526","5","<b>וכמ\"ש באגה\"ק</b>: ס\"כ (קל, ב)."],["527","6","<b>[וכן. . האלקים]</b>: תיבות אלו נוספו בגוכי\"ק בשנת תרל\"ב."],["528","7","<b>כולם בחכ' עשית. . כעשי' גשמי'</b>: ראה שעהיוה\"א פ\"ט (פו, א)."],["529","8","<b>א\"ק בכלליות העולמות. . אדם דבריאה</b>: ראה בכ\"ז בארוכה לקו\"ת מסעי צה, א ואילך. סה\"מ תרמ\"ד (הוצאת תשס\"ב) ע' שמג ואילך. וש\"נ."]]],[2000510214,"א\"ק הוא ג\"כ רק אדם דבריאה, ולכן הגם כי משה הי' נשמה דאצי' שלכן הי' אלקי' לפרעה, מ\"מ אני על גבך, שהרי גם א\"ק הוא רק אדם דבריאה אשר לגבי א\"ק נחשב האצי' רק בחי' אדם דעשי' לבד. ולכאו' עדיין צ\"ל הלא א\"ק בכלליות העולמות נחשב בחי' אדם דבריאה שזהו כמו עולם הבריאה בפרטיות העולמות, וא\"כ כמו שאצי' מהוה בי\"ע כמו\"כ אצי' דכלליות מהוה בחי' בי\"ע דכלליות, וא\"כ משה שהי' נשמה דאצי' בפרטיות העולמות אשר לכן נק' אלקי' לפרעה, וכמו\"כ כאשר נדבר בכלליות העולמות בהכרח לומר ששורש משה הוא מבחי' אצי' דכלליות, וא\"כ צ\"ל מה\"ע אני על גבך כו'. אך הענין יובן ע\"פ מ\"ש בזהר\"ק דט\"ו ע\"א שיש כדוגמת עתיק לעילא מן גלגלתא דא\"ק, שבחי' זו נק' אצי' דכלליות, וא\"כ אמר בחי' הא\"ס דסובב הכללי (המקיף ד' עולמות אבי\"ע דכלליות בשוה והוא בחי' העיגול שלפני הקו) למשה שהי' מבחי' האצי' אם כי קראתיך אלקי' לפרעה להיותך מבחי' האצי' שנק' אלקי' לגבי בי\"ע וכ\"ש לגבי פרעה, מ\"מ אלקיך אנכי אני על גבך, שהרי בחי' העיגול סובב אצי' דכלליות ג\"כ<sup data-n=\"530\">9</sup> בשוה עם העשי' דכלליות. וזהו הגם כי חלק מכבודו ליריאיו פי' שקאי על נשמות דאצי' שנק' אלקות, ואמר לשון שחלק מכבודו, כי כבוד הוא גימ' ל\"ב, והיינו בחי' ל\"ב נתיבות חכ', ונודע ממ\"ש בת\"ז שבאצי' מאיר בחי' חכמה, ולכן נשמה דאצי' להיות כי בכל עולם האצי' מאיר חכ' לכן על נשמה דאצי' שייך לומר שחלק מכבודו היינו מבחי' ל\"ב נתיבות חכ' שנק' כבוד כו'. ומ\"מ אלקיך אנכי אני על גבך, שהרי העיגול מקיף את כולם בשוה כנ\"ל. וזהו שאה\"כ הודו לאלקי האלקי'<sup data-n=\"531\">10</sup>, פי' הגם כי משה נק' אלקי' לפרעה [וגם עוד איש האלקים]<sup data-n=\"532\">11</sup>, מ\"מ אלקיך אנכי, וזהו הודו להקב\"ה שהוא אלקי האלקי' היינו הגם שקרא למשה אלקה כמ\"ש ראה נתתיך אלקי' לפרעה מ\"מ אלקיך אנכי אני על גבך כו', וזהו הודו לאלקי האלקי' כו'.\n<b>ועוי\"ל</b> ענין ראה נתתיך אלקי' לפרעה, דהנה כתי' ואם זרוע כאל<sup data-n=\"533\">12</sup> לך ובקול כמוהו תרעם עדה נא גאון וגובה כו' (איוב מ' ט' יו\"ד), פי' שבאה המענה מאת ה' לאיוב מן הסערה אם זרוע כאל לך כו' עדה נא גאון וגובה, דמשמע דזהו דבר שא\"א בלתי לה' לבדו, ואין לאדם כח בזה גם לצדיקי' מופלגי', וכענין שנכנע יעקב לפני עשו<sup data-n=\"534\">13</sup>, והלא אנו רואי' שצדיקי' יפילו לרשעי' ע\"י תפילתם. אך הענין",[["530","9","<b>מ\"מ אלקיך אנכי אני על גבך שהרי בחי' העיגול סובב אצי' דכלליות ג\"כ</b>: בסה\"מ עזר\"ת שם מוסיף: ולפמ\"ש בלקו\"ת בהביאור דמוצאיהם דאצי' דכללות הוא בחי' אוא\"ס שלפני הצמצום כו' הרי זהו בחי' התפשטות האור אבל עצם האור הוא למעלה גם מבחי' אצי' דכללות כו'."],["531","10","<b>וזהו שאה\"כ הודו לאלקי האלקי'</b>: ראה סידור עם דא\"ח קמב, ג. וראה גם שם נז, ב. [הובא באוה\"ת וארא שם]. ובארוכה אוה\"ת נ\"ך ע' תפח. סה\"מ תרכ\"ז ע' תמ."],["532","11","<b>[וגם. . האלקי']</b>: תיבות אלו נוספו בגוכי\"ק בשנת תרל\"ב."],["533","12","<b>ועוי\"ל. . דהנה כתי' ואם זרוע כאל</b>: בהבא לקמן [עד פיסקא: וענין מה שנת' לעיל] ראה מאמרי אדה\"ז תקס\"ו שם ע' קפט ואילך. אוה\"ת מג\"א שם ס\"ע רסד ואילך."],["534","13","<b>וכענין שנכנע יעקב לפני עשו</b>: ראה סה\"מ תרל\"ג ח\"א ע' סב. וס\"ע סו-ז."]]],[2000510215,"הוא משום דשורש הצדיקי' הוא משם מ\"ה דתיקון<sup data-n=\"535\">14</sup> כידוע, ושורש הנפשות של הרשעי' המה מבחי' התהו שנפלו בשבה\"כ, כמ\"ש הנפילי' היו בארץ כו' המה הגבורי' אשר מעולם אנשי השם פי' מעולם הוא מעולם התהו<sup data-n=\"536\">15</sup> שלפני בחי' התיקון וכמ\"ש ואלה המלכי' אשר מלכו כו' לפני מלך מלך לבנ\"י, והן הן תתקע\"ד דורות שקדמו עד שלא הי' בחי' התיקון, והמה העזי פנים ששתלן בכל דור ודור להתברר ע\"י ש' מ\"ה דתיקון והוא ע\"י הצדיקי' כו', ומאחר שבחי' התהו גבוה הרבה מבחי' התיקון איך יהי' ביכולת הצדיקי' להשפילם, וזהו שאמר ה' לאיוב עדה נא גאון וגובה, אחר שהם למעלה ממך.\n<b>אך</b> הנה יש להבין בזה דהרי לצדיקי' כבר ניתן כח ועוז להפוך רע לטוב ע\"י ש' מ\"ה המברר ב\"ן, וא\"כ הגם שרשעי' הם מבחי' התהו הרי ניתן בחי' תהו להתברר ע\"י ש' מ\"ה דתיקון כו', ולמה לא יהי' ביכולת הצדיקי' להשפילם והדרא קושי' לדוכתי'. אך עיקר הענין הוא דהנה יש הפרש בזה, דכאשר הרשעי' המה בשלימותם בלתי בירור עדיין לגמרי אז לא יש ביכולת הצדיקי' להשפילם ולהכניעם, אבל כשהרשעי' מתבררין ויוצא מהם חלק הטוב אזי יש ביכולת הצדיקי' להכניעם ולהאבידם כו'. וטעם הדברים כי כאשר המה בשלימותם הרי המה אנשי השם אשר מעולם התהו ממש, והם גבוהי' מבחי' התיקון ולא יכלו להם אותם אשר למטה מהם במדריגה. אך כשמתבררי' ע\"י ש' מ\"ה ויוצא מהם חלק הטוב ולא נשאר רק חלק הרע שהוא בא בשבירה הנשאר בהיכלות החיצוני' שלמטה מטה, אזי בנקל מאד שיפלו ויאבדו לגמרי וכמ\"ש כהמס דונג מפני אש כן יאבדו כו', כי רק מצד הטוב שבהם גבוהים המה מבחי' התיקון, אבל לאחר שהוציאו מהם הטוב ונכלל בקדושה ולא נשאר רק חלק הרע אותו יוכלו בקל להאבידו כו', והיינו ענין הבירור שניתן לתהו להתברר ע\"י ש' מ\"ה דתיקון דהיינו רק ע\"י בירור דוקא כנ\"ל, ולא כמו שהם בשלימותם כו'. ודוגמא לדבר בלעם הרשע שהי' מבחי' התהו כו' ולא יכלו לו בני ישראל, אך כאשר הוציא משה ממנו חלק הטוב, והוא במה שהשים ה' דבר בפיו כו' ונעשה תורה הרבה ע\"י שנשא משלו ויאמר כו' שהוא כל פ' בלק שניתנה למשה וישראל, והפרשיות הללו מדברי בלעם הם ונעשה תורה לישראל, ואז לא נשאר רק חלק הרע שבו, ולכן אמר אחר שגמר כל דבריו הנני הולך לעמי כו' ואז יכלו לו והרגוהו<sup data-n=\"537\">16</sup> כו', ועד\"ז בכולם אשר שרשם מתהו כו'. וע\"ד דוגמא במה שאמרו דילמא יפוק מיני' ברא מעלי', וכשהולידו אזי יוכלו לו כו' וכיוצא בזה. וזהו שא' עדה נא גאון וגובה פי' כמו שהם בשלימותם כו'. אך הנה הגם שאין זה ביכולת הצדיקי' אבל הוא ית' כל יכול,",[["535","14","<b>דשורש הצדיקי' הוא משם מ\"ה דתיקון</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ב ח\"ב ע' תקלו. תקמג. מאמרי אדהאמ\"צ קונטרסים ע' רפח. ביאוה\"ז להצ\"צ ח\"ב ע' תתרמח. ועוד."],["536","15","<b>כמ\"ש הנפילים. . אשר מעולם. . פי' מעולם הוא מעולם התהו</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' רכח. [ובקונ' הוספות לשם ע' רפ]. אוה\"ת בראשית (כרך ג) תקצה, א. ובכ\"מ."],["537","16","<b>כאשר הוציא. . חלק הטוב. . אמר. . הנני הולך לעמי. . יכלו לו והרגוהו</b>: ראה פירש\"י עה\"פ (כד, יד): הולך לעמי, מעתה הריני כשאר עמי שנסתלק הקב\"ה מעלי."]]],[2000510216,"מאחר שממנו הי' ענין השבירה והתיקון ביכולתו לעשות מתהו תיקון<sup data-n=\"538\">17</sup> כו', וזהו שא' ואם זרוע כאל לך כו'.\n<b>וענין</b> מה שנת' לעיל שכאשר הם בשלימותם אזי לא יש יכולת להפילם, היינו קודם שנתמלא סאתם עדיין<sup data-n=\"539\">18</sup> אז א\"א לברר אותם, וכאשר נתמלא סאתם אז מ\"ה מברר ב\"ן כו'.\n<b>וזהו</b> שאמר הקב\"ה למשה ראה נתתיך אלקי' לפרעה שנתן לו ממשלה זרוע כאל ממש על פרעה, עם היות פרעה יונק מעורף דא\"א, שז\"ע פרעה אותיות הערף בחי' עורף דא\"א שמשם נמשך להאריך אף גם לרשעים, ושורשו מבחי' התהו כו', עכ\"ז יהי' למשה דתיקון ממשלה על בחי' זו כמו אלקי' ממש הכל יכול, והיינו לפי שמשה הי' משם מ\"ה דא\"ק כמ\"ש בביאור ע\"פ משה ידבר (שלא נדפס<sup data-n=\"540\">19</sup>) שהוא למעלה מבחי' תהו ותיקון כו' רק שנשפל בבחי' התיקון כו'. ופרעה עם כי ישראל בררו הניצוצות שנבלעו בו וכמ\"ש וגם ערב ר\"ב עלה אתם שבררו משם ר\"ב ניצוצות, מ\"מ נשאר עדיין גם מה שלא נתברר עד שא\"א לבררו, כ\"א ע\"י שאמר ה' למשה נתתיך אלקי' לפרעה שהוא בחי' ואם זרוע כאל שביכולתן לעשות מתהו תיקון הנה עי\"ז ע\"י האותות והמופתי' והביזוז שאח\"כ עשו אותם כמצולה שאין בה דגים כלל כו' כי בררו הכל להיות נכלל בבחי' התיקון כו'.\n<b>ועוי\"ל</b> שזהו ע\"י אור מבחי' עקודי' שלמעלה מהשבירה ותיקון שהם בחי' נקודי' וברודים, וכמו ענין המן שירד בזכות משה שהי' ג\"כ מבחי' זו. ועפ\"ז יובן דברי רשב\"י בפ\"ק דברכות ד\"ז ב' דאמר מותר להתגרות ברשעים<sup data-n=\"541\">20</sup> בעוה\"ז, והיינו כי הי' הארה ממדריגת משה<sup data-n=\"542\">21</sup> שהי' אלקי' לפרעה שהוא בחי' זרוע כאל, הוא יכול לעדות כל גאון וגובה, וע\"ד כי גאה גאה גיאה על גוותניא<sup data-n=\"543\">22</sup> כו' שמתגאה על כל הגאים כו'<sup data-n=\"544\">23</sup>.",[["538","17","<b>ביכולתו לעשות מתהו תיקון</b>: במאמרי אדה\"ז תקס\"ו שם נוסף: וכמ\"ש במ\"א ע\"פ מי שם פה [תו\"א שמות נב סע\"ב-ג]."],["539","18","<b>קודם שנתמלא סאתם עדיין</b>: ראה אוה\"ת מג\"א שם: כשהרשע עדיין לא נתמלא סאתו והיינו שלא נתרוקן ממנו עדיין הניצוצי' דתהו."],["540","19","<b>בביאור ע\"פ משה ידבר (שלא נדפס)</b>: מאמרי אדה\"ז תקס\"ו ע' רכ."],["541","20","<b>ועפ\"ז יובן דברי רשב\"י. . מותר להתגרות ברשעים</b>: ראה אוה\"ת וארא שם ע' רלא: וצ\"ע בגמ' פ\"ק דברכות גבי רשב\"י דאמר מותר להתגרות כו'. ושם בסיום הענין: ואפשר דרשב\"י דפ\"ק דברכות הי' ג\"כ מבחי' זו כו'. וראה לקו\"ש חט\"ז שם ע' 75 הע' 55."],["542","21","<b>כי הי' הארה ממדרגת משה</b>: ראה גם סידור עם דא\"ח שז, ב: ניצוץ רשב\"י ע\"ה הי' מבחי' מדרי' דמשה כו'. עיי\"ש."],["543","22","<b>כי גאה גאה גיאה על גוותניא</b>: ראה בכ\"ז תו\"א בשלח סב, ג. סב, סע\"ד. סה, ג. ועוד."],["544","23","<b>שמתגאה על כל הגאים כו'</b>: בסה\"מ תרל\"ב שם נוסף כאן: ולכן הי' יכול לאמר על עצמו אנא סימנא בעלמא שזהו מצד רוממות נשמתו שהוא אלקות ממש להיותה מבחי' אצי' הוא בחי' גילוי ההעלם מא\"ס, ואם כי הנשמות כבר נפרדו מהקו, אמנם חוזרי' ומתקרבים ע\"י התלבשותם בגוף ועוסקי' בתומ\"צ ובדביקות אלקות, וכענין שא' רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיטא כו'."]]],[2000510217,"<b>ומ\"מ</b> אע\"פ שקראתי אותך אלקי' לפרעה, מ\"מ אלקיך אנכי אני על גבך, והיינו כנ\"ל שא\"ק ועקודי' הם רק בחי' אדם דבריאה לבד, וגם אם נא' ששורש משה הוא מאצי' דכלליות, מ\"מ הרי נת' שהמדבר למשה הוא מבחי' העיגול שלפני הקו שסובב ומקיף בחי' אצי' דכלליות בשוה עם העשי' כו'.\n<b>ואהרן</b> אחיך יהי' נביאך, פי' המבאר דברי משה כמ\"ש הרמב\"ן, והיינו כי בכל המשכה צ\"ל צמצום ואח\"כ התפשטות, וכענין יו\"ד ה\"א דשם הוי'<sup data-n=\"545\">24</sup>, היו\"ד הוא צמצום בחי' חכמה, בחי' נקודה כמו המעין שהוא קטן, והה\"א הוא בחי' בינה רחובות הנהר, וצמצום היו\"ד הוא סיבת הרחבת הנהר, וכמו המעיין שהוא הוא המוציא כל הרחבת ושטף רחובות הנהר, וכמו\"כ יובן שהיו\"ד הוא סיבת הרחבת הה\"א, וכנודע שכתיבת ה\"א של שם הוי' עושי' יו\"ד תחלה<sup data-n=\"546\">25</sup> ואח\"כ מתפשט עד שעושה תמונת ה\"א. וביאור הענין יובן ממה שארז\"ל צמצם שכינתו בין שני בדי הארון<sup data-n=\"547\">26</sup>, ולכאו' צ\"ל הלא עיקר הגילוי שהי' בבהמק\"ד הי' בין שני בדי הארון. אך הענין הוא דבכדי שיהי' הגילוי א\"א כ\"א ע\"י צמצום דוקא, ולכן בבהמק\"ד שהאיר שם גילוי אלקותו ית' זהו ע\"י צמצום דוקא. וכמו\"כ יובן בענין היו\"ד דשם הוי', שבכדי להיות גילוי זהו ע\"י צמצום דיו\"ד דוקא, ואח\"כ הה\"א הוא בחי' ההתפשטות אורך ורוחב, והיו\"ד הוא בחי' נקודה בהיכלא, כמ\"ש בלק\"ת בד\"ה ראה אנכי<sup data-n=\"548\">27</sup> נותן כו'. וזהו ואהרן אחיך יהי' נביאך היינו המבאר דברי משה, כי משה הוא בחי' חכ' יסוד אבא שהוא בחי' ברק המבריק שעדיין אינו מושג כלל, לכן אהרן אחיך יהי' נביאך המבאר דברי משה כו'.",[["545","24","<b>צמצום ואח\"כ התפשטות וכענין יו\"ד ה\"א דשם הוי'</b>: ראה בכ\"ז לקו\"ת דרושים לשמע\"צ צב, ד. תו\"ח שמות (כת\"י הר\"ש סופר) רט, א ואילך. סה\"מ תרכ\"ט ע' קכו. תרנ\"ו ע' תרנ-נא. המשך תרס\"ו ע' רז ואילך. ועוד."],["546","25","<b>וכנודע שכתיבת ה\"א. . עושי' יו\"ד תחלה</b>: ראה תו\"א תצוה פג, ב. תו\"ח שמות (כת\"י הר\"ש סופר) תקכו, ב. ובארוכה שם תקמג, א ואילך. [בהוצאת תשס\"ד ח\"ב שנו, סע\"ג-ד. שסז, ב ואילך]. סה\"מ תרכ\"ט ע' קכו."],["547","26","<b>שארז\"ל צמצם שכינתו בין שני בדי הארון</b>: בהבא לקמן ראה לקו\"ת אמור לד, ב (בשם הה\"מ ממעזריטש). אוה\"ת חנוכה (כרך ה) תתקכה, א. סה\"מ תרל\"ב ח\"א ע' מח. וע' רי. לעיל ע' מ. ועוד."],["548","27","<b>כמ\"ש בלק\"ת בד\"ה ראה אנכי</b>: פ' ראה יח, ב. וראה גם ד\"ה זה בסה\"מ תרל\"ג ח\"ב ע' תמו. וש\"נ. וע' תנז."]]],[2000510218,"<h3>גדולה מילה</h3>\n<b>בס\"ד.</b>\n<b>גדולה</b> מילה<sup data-n=\"549\">1</sup> שנכרתו עלי' י\"ג בריתות<sup data-n=\"550\">2</sup>, ולכאו' צ\"ל הלא על כל התורה לא נכרתו רק ג' בריתות, ואיך על מצוה אחת מדברי תורה יכרתו עלי' י\"ג בריתות. הנה כתי' מי יעלה לנו השמימה ר\"ת מילה וס\"ת הוי', שלכאו' יפלא איך מילה בר\"ת והוי' בס\"ת.\n<b>אך</b> הענין דשם הוי' רומז על עשר ספירות יו\"ד בחכ'<sup data-n=\"551\">3</sup> ה\"א בינה וא\"ו ה\"א זו\"נ. והנה בע\"ס יש מקיפי' ופנימי', ז\"א מקיף למל' ע\"ד השמי' שמקיפי' לארץ, וכמו באדם כשמאיר המדה בתוקף אינו יכול לדבר<sup data-n=\"552\">4</sup>, והיינו כי כל המדה אינה יכולה לבוא בגילוי בבחי' אור פנימי כ\"א נשארת בבחי' מקיף<sup data-n=\"553\">5</sup>, שענין המקיף הוא מה שא\"א לבוא בבחי' אור פנימי נשאר בבחי' אור מקיף, והגם כי הדבור מגלה העלם המדה, זהו כשמתצמצם המדה, אבל כמו שהיא היא רק מקפת, ואמנם ענין ההיקף מובן שכשמתצמצם המדה ומתגלה בדבור מ\"מ במידה שבלב מוקף כל ענין הדיבור, ומתחכם בחכ' שבמידה איך להטעים הדבר לזולתו כו'.\n<b>וזהו</b> ענין שמים וארץ שהם אור מקיף ואור פנימי<sup data-n=\"554\">6</sup> שהארץ היא בחי' אור פנימי והשמים ארז\"ל למה נק' שמים שהם מאש ומים הם בחי' חו\"ג מדות עליונות, שנגד הדבור הם נשארי' בבחי' מקיף, כ\"א הארת המדה לבד מאיר בדיבור. אמנם הנה נודע כי ישעי' אמר שמעו שמים והאזיני ארץ, ומשה אמר האזינו השמים ותשמע הארץ<sup data-n=\"555\">7</sup> בה\"א הידיעה, והיינו שיש ב' בחי' שמים וארץ, הא' הוא בחי' זו\"נ כנ\"ל, [והב' הוא בחי' חו\"ב], וכשם שז\"א מקיף למל' כן בחי' החכ' הוא בחי' מקיף על הבינה, שהבינה נק' ארץ בחי' אור פנימי נגד בחי' החכ' שנק'",[["549","1","<b>גדולה מילה</b>: מאמר זה מיוסד על ד\"ה זה להצ\"צ בכת\"י 2111 טו, א ואילך. ובשינויים והוספות בד\"ה זה בסה\"מ תרכ\"ו ע' כג ואילך. מאמר הצ\"צ מיוסד על ביאור לד\"ה בעצם היום הזה במאמרי אדה\"ז תקס\"ג ח\"א ע' יב ואילך. ובתוס' הגהות באוה\"ת לך לך (כרך ד) תשכה, א ואילך. [מאמר אדה\"ז הנ\"ל הוא ביאור לד\"ה בעצם היום הזה בתו\"א לך לך יג, סע\"ב ואילך. ונו\"א במאמרי אדה\"ז תקס\"ג שם ע' י. תו\"ח לך לך צג, ב ואילך. מאמרי אדהאמ\"צ הנחות תקע\"ז ע' רפ-פא]. וראה גם פלח הרמון בראשית מב, א ואילך [ד\"ה בעצם היום הזה].\nוראה עניני המאמר בשינויים ד\"ה לא תירא לביתה משלג בסה\"מ תרל\"ג ח\"ב ע' שצט ואילך. ד\"ה מי יעלה לנו השמימה בסה\"מ תרל\"ח ע' שפג-ד."],["550","2","<b>שנכרתו עלי' י\"ג בריתות</b>: ראה עוד על מאחז\"ל זה [נוסף להנסמן לעיל] בלקו\"ש חכ\"ה ע' 54 ואילך."],["551","3","<b>דשם הוי' רומז על עשר ספירות יו\"ד בחכ'</b>: ראה ג\"כ לקו\"ת ראה יח, א ואילך. תצא לח, ג ואילך. לט, ב ואילך. אוה\"ת ראה ע' תרמט. ביאוה\"ז להצ\"צ ח\"א ע' שסג ואילך. סה\"מ תרל\"ג ח\"ב ע' תמד ואילך. [ובהנסמן שם בתחילת המאמר]. ובכ\"מ."],["552","4","<b>באדם כשמאיר המדה בתוקף אינו יכול לדבר</b>: ראה בארוכה מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' רלד ואילך. וראה גם שם ח\"ב ע' תסב ואילך."],["553","5","<b>כל המדה אינה יכולה לבוא. . בבחי' אור פנימי. . כ\"א. . מקיף</b>: ראה סידור עם דא\"ח רס, א."],["554","6","<b>וזהו ענין שמים וארץ שהם אור מקיף ואור פנימי</b>: ראה לקו\"ת נשא כא, ג. דרושים לר\"ה נט, ג. אוה\"ת לך לך (כרך ד) שם תשכה, א ואילך. לקו\"ש חי\"ד ע' 147. ובכ\"מ."],["555","7","<b>ישעי' אמר שמעו שמים והאזיני ארץ ומשה אמר האזינו השמים ותשמע הארץ</b>: נת' באוה\"ת דרושים לחג השבועות ע' קצח. האזינו ס\"ע א'תרלז. ובלקו\"ש ח\"ב ע' 415 ואילך. ח\"ט ע' 204 ואילך. חי\"ד שם ע' 143 ואילך."]]],[2000510219,"בשם אור מקיף<sup data-n=\"556\">8</sup>. אמנם חלוקי' הם בטעמם, שהחכ' היא בחי' מקיף להיותה בבחי' ברק המבריק עדיין, ומה שהמדות הם מקיפי' לדבור זהו מחמת תקפם כו', איך שיהי' שניהם הם מקיפי'. וענין שמשה אמר האזינו להשמי' בחי' חכ', וישעי' אמר האזיני ארץ בחי' מל' כי אבא יסד ברתא. והנה יש עוד בחי' מקיף והוא הנק' שמי השמים בחי' כתר, והיא בחי' החופה שעל כל כבוד, אפי' על בחי' כבוד נאצל דחכ'<sup data-n=\"557\">9</sup>. ומ\"ש במילה מי יעלה לנו השמימה ר\"ת מילה כולל כל בחי' המקיפי' הנק' שמים אפי' בחי' שמי השמים כו', ולכן מילה בר\"ת והוי' בס\"ת, כי שם הוי' הוא יו\"ד בחכ' ה\"א בינה וא\"ו ה\"א זו\"נ זהו בחי' אצי', אבל ע\"י מילה מגיע לבחי' שמי השמים בחי' כתר, ולכן היא בר\"ת. והגם כי קוצו של יו\"ד רומז ג\"כ לכתר, מ\"מ זהו רק רמיזה ואינו בחי' אות מאותיות דשם הוי'.\n<b>ועפ\"ז</b> יובן מה שעל המילה נכרתו י\"ג בריתות משא\"כ על כל התורה לא נכרתו רק ג' בריתות, דהנה בפרדס בסופו הביא ברייתא משמעון הצדיק<sup data-n=\"558\">10</sup> בענין י\"ג מדה\"ר שהם ע\"ס וג' עולמות בי\"ע, ובשער י\"א הוא שער הצחצחות הביא תשו' רב האי גאון ששאלו לו ע\"ס ידענו י\"ג לא ידענו, והשיב להם שהם ע\"ס וג' ראשי ראשים שהם אור צח ואור מצוחצח ואור קדמון, ויש לחבר ב' הדיעות שג' עולמות בי\"ע שרשם הוא מג' ראשי ראשים וכנז' בת\"א בד\"ה משה ידבר<sup data-n=\"559\">11</sup>. והענין הוא דהנה ארז\"ל באיזהו זכות הי' נכנס אהרן לבית קדה\"ק זכות המילה<sup data-n=\"560\">12</sup> היתה נכנסת עמו, והיינו כי ענין המילה הוא העברת הערלה וקריעת עור הפריעה<sup data-n=\"561\">13</sup> הוא בחי' הפרסא שבין קדש לחול ובין טמא לטהור שהיא המעלמת ומסתרת על אור האלקי לגמרי עד שיוכל להיות מציאות הרע, ועור הפריעה היא המבדלת בין הקדושה לק\"נ שהוא בחי' ההבדל שבין קדש לחול, ולכן עור הערלה צריכי' להעבירה לגמרי, ועור הפריעה אין צריך לכורתה כ\"א לקורעה ולכפותה על הצדדי' להורות שהק\"נ באפשר להתברר ולהתכלל בקדושה, אמנם הערלה צריכה כריתה לגמרי כי כלי חרס שבירתם זהו תקנתם שאין להם תקנה כ\"א להעבירם מן העולם, וכענין מצות לא תעשה<sup data-n=\"e53\">א</sup>.",[["556","8","<b>שהבינה נק' ארץ. . החכ' שנק' בשם אור מקיף</b>: ראה בארוכה אוה\"ת לך לך (כרך ד) שם תשכה, ב ואילך."],["557","9","<b>בחי' החופה שעל כל כבוד. . כבוד נאצל דחכ'</b>: ראה בארוכה לקו\"ת שה\"ש מז, ב ואילך. סידור עם דא\"ח קכח, ד ואילך."],["558","10","<b>בפרדס. . ברייתא דשמעון הצדיק. . תשו' רב האי גאון</b>: ראה בכ\"ז בארוכה אוה\"ת שה\"ש (כרך ב) ע' תקנו-ז. סה\"מ תרכ\"ו שם ע' כד ואילך. תרל\"ב ח\"א ע' קפט. ח\"ב ע' תח ואילך. תרס\"ד (הוצאת תשנ\"ד) ס\"ע קכב ואילך. תרע\"ח ס\"ע עו ואילך. תרצ\"ט ע' 108 ואילך."],["559","11","<b>בת\"א בד\"ה משה ידבר</b>: פ' יתרו סח, ד."],["560","12","<b>באיזהו זכות הי' נכנס. . זכות המילה</b>: ראה בארוכה סה\"מ תר\"ל ע' קכא ואילך. תרל\"ב ח\"א ע' קלח ואילך. וראה גם אוה\"ת אחרי ס\"ע רפו ואילך. סה\"מ תרל\"ג ח\"ב ע' תקיט, ועוד."],["561","13","<b>המילה. . העברת הערלה וקריעת עור הפריעה</b>: ראה לקו\"ת תזריע כא, א. דרך מצותיך ד, ב ואילך. אוה\"ת יתרו ע' תתי ואילך. ועוד.\n\n<b>א</b>  <b>וכענין מצות לא תעשה</b>: בגוכי\"ק ממשיך כאן עוד קטע: והנה כמו שיש פרסא בין טמא לטהור כמ\"ש והבדלתם בין הבהמה כו' לטהור. [ולא נגמר ההמשך בגוכי\"ק. וראה בדרושים שנסמנו לעיל בתחילת המאמר]."]]],[2000510220,"<h3>ולקחתם אגודת אזוב</h3>\n<b>בס\"ד.</b>\n<b>ולקחתם</b> אגודת אזוב<sup data-n=\"562\">1</sup> וטבלתם מן הדם אשר בסף והגעתם אל המשקוף כו'. הנה איתא במדרש שה\"ש בפסוק כתפוח בעצי היער משל ע\"ז לאדם שלקה ברגליו חזר על כל הרופאים כו' בא אחד ואמר לו בדבר קל אתה מתרפא כו', כך אמר להם משה אם אתם רוצים ליגאל ולקחתם לכם אגודת אזוב כו'. והנה להבין המשל הזה מהו שלקה ברגליו, י\"ל מקודם מ\"ש (עמוס ט' ו') הבונה בשמים מעלותיו ואגודתו על ארץ יסדה, ופי' בזח\"ג פ' צו דל\"ה א' ר' יצחק אמר ואגודתו כד\"א ולקחתם אגודת אזוב, שמשוה בחי' אגודתו לבחי' ולקחתם אגודת אזוב. והנה ע\"י ואגודתו נמשך הבונה בשמים מעלותיו, וצ\"ל מהו לשון הבונה בשמים עליות מהו שייך למעלה בנין עליות כו'. והענין הוא דהנה כתיב ואשים דברי בפיך ובצל ידי כסיתיך לנטוע שמים כו', ואשים דברי הוא בחי' תורה, ובצל ידי כו' הוא בחי' מצות בצל החכ' בצל הכסף, לנטוע שמים כו' הוא בחי' קרבנות תפלה כו'. ולכאורה אינו מובן מה שייך לומר לנטוע שמים שהלא שמים כבר נברא כו'.\n<b>הנה</b> כתיב (ישעי' מ' י\"ב) מי מדד בשעלו מים ושמים בזרת תכן, ולמדו מזה בגמ' עירובין דכ\"א ע\"א שהשמים היא רק א' משלשת אלפים ומאתים בתורה, וכמו שפרש\"י<sup data-n=\"563\">2</sup> שם שהזרת הוא חצי אמה ע\"ש. ולהבין כ\"ז הענין הוא דהנה הבריאה נק' יש מאין, כי אני הוי' לא שניתי לא כמו שהנשמה מחיה את הגוף שמתלבשת ומתפעלת כו', כי מלכותך כו' יהללו את שם הוי' כי הוא צוה ונבראו. ומעתה יש להבין כיון שהבריאה נעשה רק מזיו והארה<sup data-n=\"564\">3</sup> שאינו נוגע אל עצמותו, א\"כ אינו מובן מהו ענין השבת, כי שבת הוא בחי' שביתה כי בו שבת, ומה שייך שביתה כיון שלא הי' עבודה כלל, וכמ\"ש רז\"ל במדרש לא בעמל ולא ביגיעה ברא כו' כ\"א במאמר פיו, ומהו ענין השבת שהוא בחי' שביתה ממלאכה. והענין הוא דהנה איתא בזהר שעשרה מאמרות נק' מילין דהדיוטא ולאו אורחא דמלכא כו', וגם זה לכאורה אינו מובן איך נק' העשרה מאמרות מילין דהדיוטא.",[["562","1","<b>ולקחתם אגודת אזוב</b>: המאמר מיוסד והגהות על ד\"ה זה להצ\"צ משנת תרט\"ז באוה\"ת בא (כרך ז) ע' ב'תרכג ואילך [ההגהות להמאמר כפי שנרשמו בגוכי\"ק חלקם נכנסו בפנים המאמר, וחלקם באו בין חצאי ריבוע]. ונמצא בשינויים קלים בד\"ה זה בסה\"מ תרכ\"ז ע' רטו ואילך. — מאמר האוה\"ת הוא הנחת הרה\"ח ר' בערל קאליסקער בכת\"י 1063 רכט, א ואילך. ונעתק בכת\"י 1029 ז, א ואילך [הכולל הנחות בגוכי\"ק אדמו\"ר מהר\"ש (ועוד) ממאמרי הצ\"צ משנת תרט\"ז. ובמפתח נרשם ע\"ז: ”של רב\"ק\" של ר' בערל קאליסקער]. פ\"א נמצא בתוס' הגהות בסה\"מ תרל\"ה ח\"א ע' קיז-ח. תרמ\"ג ע' קא-ב.\nתוכן עניני המאמר נמצא בד\"ה זה באוה\"ת בא שם ע' ב'תרכז ואילך. ובד\"ה וידבר גו' לאמר באוה\"ת יתרו ע' תתעו ואילך. ובאוה\"ת דרושים לחה\"ש (הוצאת תשנ\"ה) ע' 58 ואילך (בהוספות). ובאוה\"ת יתרו (כרך ח) ע' ב'תתקפה ואילך. ובד\"ה הבונה בשמים מעלותיו באוה\"ת בא שם ע' ב'תרכט ואילך. נ\"ך (כרך ב) ע' תתצה ואילך. וראה גם ד\"ה ולקחתם אגודת אזוב באוה\"ת בא ע' שיא ואילך. וע' שכא ואילך."],["563","2","<b>ושמים בזרת תכן. . שפרש\"י</b>: ראה גם אוה\"ת נ\"ך (כרך ג) ע' א'ריח."],["564","3","<b>דהנה הבריאה נק' יש מאין. . מזיו והארה</b>: ראה בכ\"ז סה\"מ תרכ\"ז ע' שסו. וש\"נ."]]],[2000510221,"<b>אך</b> שרש ענין הדיוט נמצא בתרגום אונקלס ע\"פ אין זה כ\"א בית אלקים, ומתרגם לית דין אתר הדיוט, ויש להבין מהו ענין הדיוט.\n<b>והענין</b> הוא דהנה כתיב נער הייתי גם זקנתי וארז\"ל שרו של עולם אמרו, שמט\"ט נק' נער<sup data-n=\"565\">4</sup>, והיינו לפי שכדי שיומשך ההשפעה מעולם האצי' למטה שיהי' עולם שהוא בחי' גבול וכמארז\"ל מהארץ לרקיע מהלך ת\"ק שנה, וגם שנעשה העולם בבחי' יש ודבר שנראה נפרד לגמרי, וגם שיש שם בחי' עה\"ד טו\"ר, הוצרך להתצמצם השפעה זו בעולם היצי' בבחי' מט\"ט, וע' בלק\"ת בשה\"ש בד\"ה מה יפו<sup data-n=\"566\">5</sup> פעמיך בנעלים. וזהו שנק' נער אנפי זוטרי קטנות וצמצום, וע\"כ נק' הדיוט וכמ\"ש בזהר שמט\"ט נק' הדיוט לגבי מארי' (וזהו משארז\"ל אל תהי ברכת הדיוט קלה בעיניך), וזהו כמו כהן הדיוט לגבי כה\"ג שלגבי כה\"ג נק' הדיוט. ועד\"ז ענין שעשרה מאמרות נק' מילין דהדיוטא שאע\"פ שעשרה מאמרות הם גבוהים מאד למעלה, אך מ\"מ כיון שע\"י נעשה מקור לעולמות שהם בחי' גבול ויש כו', וגם שנעשה מקור לעה\"ד טו\"ר שייך לאמר לשון מילי דהדיוטא. ויובן זה ממה שאנו רואים שע\"י שיש באדם חצר הכבד המפסיק<sup data-n=\"567\">6</sup> שהוא בחי' הקרומא דפסיק במעי דבר נש, שעי\"ז נעשה ההבדל בין אברי הנשימה שהם בתכלית הדקות לאברי המזון כמו המעיים שהם מבררים את המאכל עד שיצא הפרש לחוץ, וכך עד\"מ זה יובן שע\"י מאמר יהי רקיע המבדיל בין מים למים נעשה הבדלה עד שמים תחתונים נעשים מקור לתענוגי' גשמיים בחי' עה\"ד טו\"ר, והרי זה נעשה ע\"י המאמר יהי רקיע שע\"י המאמר נעשה ההבדלה כו', וע\"כ נק' מילין דהדיוטא. וזהו מה שתרגם אונקלס לית דין אתר הדיוט, כי אתר הדיוט הוא בחי' השייך לעולמות, והיינו בחי' עשרה מאמרות כו', משא\"כ בבהמ\"ק הי' מאיר למעלה מבחי' עולמות שהי' מאיר בו גילוי שם הוי', וכמ\"ש אכן יש הוי' במקום כו' ע\"כ אינו אתר הדיוט.\n<b>וזהו</b> ג\"כ ענין השבת שהוא בחי' שביתה, שאע\"פ שאינו שביתה ממלאכה, מ\"מ הוא בחי' שביתה מהירידה<sup data-n=\"568\">7</sup> לפי שהעשרה מאמרות הם בחי' ירידה והשפלה נגדו, וכמו למשל חכם גדול כשמדבר דברים פשוטים בעלמא הוא ירידה גדולה אצלו וכששבת מהדבורים אזי היא בחי' שביתה אצלו, וכך שבת הוא בחי' שביתה עליות העולמות למעלה מבחי' עשרה מאמרות כי בו שבת מבחי' מאמר דעשרה מאמרות כו'.",[["565","4","<b>דהנה כתיב נער הייתי. . שמט\"ט נק' נער</b>: בהבא לקמן ראה גם אוה\"ת חנוכה (כרך ה) תתקלב, ב. סה\"מ תרל\"ג ח\"א ס\"ע מ ואילך. ועוד."],["566","5","<b>בלק\"ת בשה\"ש בד\"ה מה יפו</b>: דף מג, ג-ד. וראה גם סה\"מ תרכ\"ז ע' צו. תרל\"ג ח\"א שם ע' ז-ח."],["567","6","<b>ויובן זה. . חצר הכבד המפסיק</b>: בהבא לקמן ראה בארוכה מאמרי אדה\"ז אתהלך לאזניא ע' רנט. תקס\"ב ח\"א ע' פט. תקס\"ה ח\"א ע' ה ואילך. הקצרים ע' קט. מאמרי אדהאמ\"צ דברים ח\"א ע' קנה ואילך. אוה\"ת ואתחנן ע' קמו ואילך."],["568","7","<b>וזהו ג\"כ ענין השבת. . שביתה מהירידה</b>: בהבא לקמן בפיסקא זו ראה גם סה\"מ תרל\"ג ח\"ב ע' שלט [ובהנסמן שם]."]]],[2000510222,"ב) <b>ועפ\"ז</b> יובן מ\"ש (איוב ד' י\"ח) הן בעבדיו לא יאמין<sup data-n=\"569\">8</sup> ובמלאכיו ישים תהלה, והיינו לפי ששרש המלאכים הוא מבחי' ל' כלים דז\"א, ויש להם נשמה וגוף וע\"כ הגוף שלהם מסתיר<sup data-n=\"570\">9</sup> ג\"כ, ואף שאין שייך שם בחי' חטא ועון, אעפ\"כ הביטול אינו כדבעי<sup data-n=\"571\">10</sup> מפני שהגוף מסתיר, וכן כתיב (איוב ט\"ו ט\"ו) הן בקדושיו לא יאמין ושמים לא זכו בעיניו, ג\"כ מהאי טעמא שהביטול אינו כדבעי, לפי ששרש השמים הוא מבחי' עשרה מאמרות מילין דהדיוטא. ובזהר ויגש דר\"ז ע\"א מפרש הן שמים לא זכו בעיניו למעליותא שמפני חביבותן ע\"כ לא זכו בעיניו, כמו למשל אדם כשיש לו כלי נאה או בנין נאה שכל מה שהכלי חביב עליו יותר הוא מתקנה יותר ודומה לו שעדיין לא ניתקנה היטב וצריכה תיקון עדיין, וכך שמים לא זכו בעיניו.\n<b>וזהו</b> לנטוע שמים כו' שצריך לנטוע ולתקן את השמים, כי כל מה שנברא בששת ימי בראשית צריכין תיקון ואפילו שמים, והמכוון מזה הי' כדי שיהי' עבודה כו'. וע\"י מה עושין הנטיעה והתיקון זהו ע\"י תפלה, כי תפלה נק' סולם מוצב ארצה<sup data-n=\"572\">11</sup> וראשו מגיע השמימה, לפי שהתפלה מתחלת מדברים תחתונים פסוד\"ז הללו את ה' מן הארץ כו', ואח\"כ יוצר אור התבוננות מהמלאכים, ואח\"כ ק\"ש שמע ישראל עלו במחשבה, וכשיתבונן בכל זה ששרש הכל היא מבחי' עשרה מאמרות מילין דהדיוטא עי\"ז נעשה ואהבת את הוי' אלקיך אהבה ורצון לעצמותו ומהותו ית', ואח\"כ הוא בחי' שמו\"ע ברוך אתה הוי' המשכה למטה, כי בסולם עולים ויורדים כו', [וע\"י העלי' בק\"ש לבחי' אליו ולא למדותיו בבחי' מס\"נ אחד ואהבת, נמשך אח\"כ בשמ\"ע בחי' שם הוי' שזהו ענין הירידה וההמשכה בסולם דתפלה (וע' בד\"ה דרשו ה' בהמצאו בס' טו\"ב<sup data-n=\"573\">12</sup> שיש כמה פי' בפי' אליו ולא למדותיו)], ועי\"ז נעשה לנטוע שמים שממשיכים ומתקנים את השמים, וכמ\"ש היושבי בשמים שהיו\"ד שבתיבת היושבי הוא מיותר, אלא שלכן נאמר היושבי היושב יו\"ד שממשיכים בחי' י' דשם הוי' בהשמים שהוא בחי' המשכת החכמה, [ע' בזח\"א ויחי דרך\"ט ע\"א], והשמים כסאי שהשמים נעשה כסא ומכון לשבתו ית'. וזהו ג\"כ מ\"ש כונן שמים בתבונה, שממשיכים בשמים מבחי' תבונה, כי שמים הוא אש ומים בחי' מדות, משא\"כ תבונה הוא למעלה מבחי' מדות<sup data-n=\"574\">13</sup> וכמ\"ש ולתבונתו אין מספר, כי",[["569","8","<b>ועפ\"ז יובן מ\"ש. . הן בעבדיו לא יאמין</b>: בהבא לקמן בפיסקא זו ושלאחרי' ראה בארוכה אוה\"ת יתרו שם ע' תתעו ואילך [הובא באוה\"ת בא שם]. שם (כרך ח) ע' ב'תתקפו ואילך. נ\"ך (כרך א) ע' תרס ואילך."],["570","9","<b>המלאכים. . ויש להם נשמה וגוף וע\"כ הגוף שלהם מסתיר</b>: ראה בכ\"ז בארוכה בסידור עם דא\"ח עג, ד ואילך."],["571","10","<b>המלאכים. . שאין שייך שם בחי' חטא ועון אעפ\"כ הביטול אינו כדבעי</b>: ראה סה\"מ תרל\"ג ח\"ב ע' תמ (בשוה\"ג). וש\"נ."],["572","11","<b>תפלה נק' סולם מוצב ארצה</b>: בהבא לקמן ראה לקו\"ת שה\"ש טז, סע\"ד ואילך. סה\"מ תרכ\"ז ע' י. יד. ועוד."],["573","12","<b>בד\"ה דרשו ה' בהמצאו בס' טו\"ב</b>: הכוונה לד\"ה זה בבוך תרטו\"ב [הכולל דרושי הצ\"צ משנת תרי\"ז] נדפס באוה\"ת דרושים לשבת שובה ע' א'תסג ואילך."],["574","13","<b>תבונה הוא למעלה מבחי' מדות</b>: ראה לקו\"ת במדבר, ז, סע\"ג. שה\"ש כז, א. שער היחוד לאדהאמ\"צ ג, א ואילך. ועוד."]]],[2000510223,"מתחלה כתיב גדול אדונינו ורב כח שהוא בחי' שיעור קומה של יוצר בראשית<sup data-n=\"575\">14</sup> ששרשו מבחי' מדות דאצי' שהיא מקור בחי' גבול, משא\"כ לתבונתו אין מספר, וזהו כי אמרתי עולם חסד יבנה, יבנה הוא בחי' בינה<sup data-n=\"576\">15</sup> שממשיכים בעולם מבחי' בינה, וזהו ע\"י בחי' תפלה בחי' התבוננות, ועי\"ז נמשך ההמשכה אח\"כ מבחי' בינה.\n<b>והנה</b> כמו\"כ ע\"י התורה ממשיכים בהשמים ואשים דברי בפיך, דהנה ושמים בזרת תכן חצי אמה<sup data-n=\"577\">16</sup>, והנה חצי אמה הוא בחי' ה' תתאה ג' קוין שנעשה מקור לעולמות בי\"ע, והאמה הוא בחי' ה' עילאה, וזהו שהשמים הוא רק א' משלשת אלפים ומאתים מהתורה, דהנה אורייתא מחכ\"ע נפקת, והנה בחכמה יש ל\"ב נתיבות חכמה שהוא כנגד ך\"ב אותיות וע\"ס, והנה יו\"ד כלול מיו\"ד<sup data-n=\"578\">17</sup> ויו\"ד מיו\"ד, וזהו שלשת אלפים ומאתים, וכמו שיש ל\"ב נתיבות חכ' כמו\"כ יש ל\"ב פעמים אלקים שבמע\"ב שהוא ל\"ב נתיבות חכ' תתאה, וזהו חצי אמה ה' תתאה שהוא רק חלק א' משלשת אלפים ומאתים, וזהו שע\"י התורה ממשיכים בהשמים שהיא רק בזרת תכן חכ' תתאה, [ונק' חלק א' י\"ל לפי שיחידות במל'], משא\"כ אורייתא הוא חכ' עילאה כו'. [ובצל ידי גמ\"ח, כמארז\"ל בירושלמי דתענית ללמדך שכל מי שעוסק בתורה ובגמ\"ח זוכה לישב בצלו של הקב\"ה, וזהו בצל החכ' בצל הכסף, והיינו כי גמ\"ח טוב לשמים וטוב לבריות, ועי\"ז ממשיך בשמים מבחי' על השמים כו', ע' בד\"ה ציון במשפט בס' פ'<sup data-n=\"579\">18</sup>, וע' בד\"ה פדה בשלום נפשי<sup data-n=\"580\">19</sup>]. וזהו הבונה בשמים מעלותיו שממשיכים בהשמים מבחי' מעלותיו שהוא בחי' על סוכ\"ע וכמ\"ש בחנה ותתפלל חנה על הוי'<sup data-n=\"581\">20</sup> למעלה משם הוי' כי גדול מעל שמים חסדך כו'. וע' מענין על הוי' בד\"ה ויהי אומן את הדסה<sup data-n=\"582\">21</sup> מענין הוקם על, עולה של תורה, ועולה של תשובה.\nג) <b>אך</b> הנה כ\"ז כשואגודתו על ארץ יסדה שיש בחי' אגודה אחת, כי הנה אגודה הוא כשיש התכללות דוקא והיינו ע\"י שיש להם בחי' ביטול, וכמ\"ש ביעקב ע' נפש יוצאי ירך יעקב ובעשו נאמר נפשות<sup data-n=\"583\">22</sup> לשון רבים, והיינו לפי שע' נפש הם יוצאי ירך יעקב שנמשך היו\"ד בבחי' עקביים ויש להם ביטול כו', ע\"כ יכולים הם",[["575","14","<b>גדול אדוננו ורב כח. . שיעור קומה של יוצר בראשית</b>: ראה בהנסמן בס' מאמרי אדהאמ\"צ במדבר ח\"א ע' דש. ובסה\"מ תרל\"ח ע' ז."],["576","15","<b>וזהו כי אמרתי עולם חסד יבנה. . בחי' בינה</b>: ראה גם לקו\"ת שה\"ש יב, רע\"א."],["577","16","<b>דהנה ושמים בזרת תכן חצי אמה</b>: ראה פי' רש\"י עירובין כא, סע\"א: ושמים בזרת תכן כו' חצי אמה על חצי אמה. בהבא לקמן ראה אוה\"ת נ\"ך (כרך ג) ע' א'ריח שם."],["578","17","<b>והנה יו\"ד כלול מיו\"ד</b>: באוה\"ת בא שם ע' ב'תרכז: וכל נתיב כלול מיו\"ד."],["579","18","<b>ע' בד\"ה ציון במשפט בס' פ'</b>: כנראה הכוונה לד\"ה זה שבבוך 1120 ריד, א ואילך [משנת תרכ\"ב — בוך זה נזכר גם לקמן פ\"ג]. ונדפס באוה\"ת דברים ע' לו ואילך. וראה שם ע' לח-ט. אוה\"ת ויצא ריג, ב ואילך. וראה שם רטו, א-ב. וראה גם אוה\"ת דברים (כרך ו) ע' ב'תר. נ\"ך (כרך ג) ע' א'קצא."],["580","19","<b>וע' בד\"ה פדה בשלום נפשי</b>: רשימות הצ\"צ לתהלים (יהל אור) ס\"ע רו."],["581","20","<b>וכמ\"ש בחנה ותתפלל על הוי'</b>: ראה תו\"א משפטים עט, סע\"א-ב."],["582","21","<b>בד\"ה ויהי אומן את הדסה</b>: סה\"מ תרכ\"ז ע' קצה."],["583","22","<b>וכמ\"ש ביעקב ע' נפש. . ובעשו נאמר נפשות</b>: ראה סה\"מ תרל\"ג ח\"ב ע' תקלד-ה (בשם הה\"מ). וש\"נ."]]],[2000510224,"להתכלל, משא\"כ כשהם בבחי' יש אינם יכולים להתאחד ולהתכלל. והנה כשיש בחי' אגודה בחי' התכללות אז יכולים להמשיך מבחי' מעלותיו, וכמו במ\"ת נאמר ויחן ישראל שנתאחדו אז ניתן להם התורה, ברכנו אבינו כולנו כאחד באור פניך, כאחד דוקא. וזהו שקדושה אין אומרים כ\"א בעשרה דוקא, אבל א' אעפ\"י שהוא אדם גדול מאד אינו יכול לומר קדושה, וכן ברכת הזימון הוא דוקא בשלשה, בשלשה אומר נברך שעושין בריכה<sup data-n=\"584\">23</sup>, משא\"כ א' כו', אבל עשרה או ג' אע\"פ שהם פחותי ערך יכולים לומר קדושה או ברכו כו'<sup data-n=\"585\">24</sup>. וזהו ואגודתו על ארץ יסדה אז הבונה בשמים מעלותיו, אליך נשאתי את עיני כו' בבחי' ביטול והתכללות אז היושבי בשמים כו', וזהו ולקחתם אגודת אזוב, אגודה דוקא.\n<b>ולהבין</b> למה אזוב דוקא<sup data-n=\"586\">25</sup>, הענין הוא דהנה אזוב הוא בחי' ביטול וכמ\"ש (מלכים א' ה' י\"ג) מן הארז אשר בלבנון ועד האזוב אשר יצא בקיר, שהוא בחי' ביטול ושפלות, וע\"י בחי' הביטול ושפלות עי\"ז יכול להתכלל עם זולתו, דמאחר שאינו תופס מקום כ\"כ בעיני עצמו יוכל להתכלל עם חבירו, וזהו אגודת אזוב דבכדי להיות בבחי' אגודה זהו ע\"י אזוב בחי' ביטול ושפלות. ועוי\"ל בפי' אזוב דהנה בספר פ\"י<sup data-n=\"587\">26</sup> פי' אזוב וסף הוא בגימט' יוסף, והענין הוא דהנה כתיב אלה תולדות יעקב יוסף<sup data-n=\"588\">27</sup>, ולהבין למה יוסף דוקא, הענין הוא דהנה ידוע שיעקב הי' בחיר שבאבות בריח התיכון המבריח מן הקצה אל הקצה [וזהו בחי' ארז וא\"ו רברבא], אך הנה כ\"ז הוא רק למעלה מקצה השמים דלעילא עד קצה השמים דלתתא, אבל למטה אינו נמשך בגילוי, וכדי שיהי' תולדות יעקב שיהי' נמשך למטה זהו ע\"י יוסף שהוא בחי' יסוד כי כל בשמים ובארץ דאחיד בשמיא בחי' ת\"ת וארעא בחי' מל', ואפ\"ל זהו ההשפעה שצ\"ל ע\"י לצמצם א\"ע כו', וידוע שכדי להיות השפעה זו נמשך כח זה מלמעלה כענין והנורא אל עליון כו' וקונה הכל כו' ומביא גואל, וע\"כ האזוב חשוב כמו הארז אשר בלבנון כו' במד\"ר פ' בא, וזהו שיוסף הי' השליט במצרים, וע\"כ ע\"י יוסף ירדו למצרים ועל ידו עלו כו' [ע' בזהר ויחי דרך\"ו ע\"א], וזהו אגודת אזוב דוקא שעי\"ז יומשך למטה ג\"כ.\n<b>ובזה</b> יובן המשל של המדרש משל לא' שלקה ברגליו, דהנה נש\"י נקראו בחי' רגל<sup data-n=\"589\">28</sup> כמ\"ש בנים אתם כו' ברא כרעא דאבוה, דכמו שהרגל בטל לגבי הראש",[["584","23","<b>ברכת הזימון הוא דוקא בשלשה. . שעושין בריכה</b>: ראה בארוכה סידור עם דא\"ח קב, א ואילך."],["585","24","<b>אבל עשרה או ג'. . יכולים לומר קדושה או ברכו כו'</b>: מש\"כ: ”או ג'\", קאי על ברכת הזימון הנזכר לעיל."],["586","25","<b>ולהבין למה אזוב דוקא</b>: בהבא לקמן בפיסקא זו ראה גם אוה\"ת בא שם ע' שכא (ס\"ד)."],["587","26","<b>בספר פ\"י</b>: בספר פנים יפות להרה\"ק ר' פנחס הורביץ בעמח\"ס ההפלאה. — הובא באוה\"ת בא שם ע' שטז. וע' שכה."],["588","27","<b>דהנה כתי' אלה תולדות יעקב יוסף</b>: בהבא לקמן ראה בארוכה ד\"ה בן פורת יוסף בס' מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרעז ואלך. שם ע' תרפב ואילך. אוה\"ת ויחי שפה, ב ואילך. שפח, א ואילך. שצה, א ואילך. תד, ב ואילך. שם (כרך ו) תתשמז, ב ואילך. סה\"מ תרנ\"ג ע' רנח ואילך. עזר\"ת ע' קיז ואילך. סה\"מ מלוקט ח\"ג ע' רכא ואילך."],["589","28","<b>דהנה נש\"י נקראו בחי' רגל</b>: בהבא לקמן ראה תו\"א ר\"פ בראשית א, ב."]]],[2000510225,"כך נש\"י הם בטלים לאלקות, ובדרך פרט יש בכל נשמה ראש ורגל, ראש הוא בחי' מוחין חב\"ד, חג\"ת הוא בחי' ידים, ורגל נה\"י הוא בחי' מעשה. והנה אע\"פ שהרגל הוא למטה מהראש מ\"מ יש מעלה ברגל שהוא מוליך את הראש, שהילוך הוא מעלה גדולה וכמ\"ש ונתתי לך מהלכים בין העומדים האלה שההילוך הוא בלי גבול ממש. וזהו שהמועדים נק' שלש רגלים, והיינו לפי שבכל יו\"ט הוא בחי' עליית העולמות, וכמ\"ש מי זאת עולה מן המדבר שהיא כמו בחי' שבת שביתה מע\"מ מילין דהדיוטא, וכך יו\"ט הוא בחי' שביתה אפי' כשחל יו\"ט ביומין דחול.\n<b>והנה</b> כ\"ז כשהרגל הוא בשלימות, משא\"כ כשחלה ברגליו שפגם באיזה מעשה ואפילו בדקדוקי סופרים נק' חולה, וכמ\"ש סומך ה' לכל הנופלים כו', ואז נק' חולה, [וע' מענין חולה בד\"ה כתפוח בעצי היער בס' פ'<sup data-n=\"590\">29</sup> מענין חולה שיש בו סכנה וחולה שאין בו סכנה וחולה שחסר שער הנו\"ן, וע' בלק\"ת בד\"ה והי' מדי חדש<sup data-n=\"591\">30</sup> מענין חולת אהבה, וע' בד\"ה ולא זכר שר המשקים, ך\"ו<sup data-n=\"592\">31</sup>]. ואמר להם בדבר קל אתה מתרפא שהוא בחי' תשובה שנק' רפואה, וכמשארז\"ל גדולה תשובה שמביאה רפואה לעולם. ולהבין מהו ענין בחי' רפואה, הנה כתיב באליהו וירפא את מזבח ה' ההרוס<sup data-n=\"593\">32</sup>, ולהבין מה שייך במזבח ענין רפואה, הענין הוא דהנה על המזבח הי' אש שלמטה ואש שלמעלה, ואש שלמטה מצוה להביא מן ההדיוט. והנה בעבודה אש בחי' אהבה כרשפי אש, ויש ב' מיני אהבה, היינו אהבה ממילין דהדיוטא מהתבוננות של עולמות איך שהם רק זיו והארה בעלמא ועי\"ז נעשה לו אהבה ותשוקה לאלקות, זהו הנק' אש של הדיוט. ויש אהבה הבאה מלמעלה ונק' אש שלמעלה [וע' בד\"ה ועשית ציץ, ובד\"ה מגילה נקראת<sup data-n=\"594\">33</sup> מענין ב' בחי' אהבה, אה\"ע ואה\"ר הבאה מלמעלה ע\"י אהרן כהנא רבא, בחי' אהבתי אתכם אמר ה']. אך הנה יש בחי' אש זרה דהיינו רשפי אש בבחי' מילי דעלמא, ויש אש זרה ממש דהיינו תאוות רעות ואפי' בהיתר, ואז נק' חולה, כמו למשל האדם צריך שיהי' לו חום הטבעי, אבל כשנעשה לו אש זרה אז נעשה חולה וצריך לרפואה. וזהו שאמר להם בדבר קל אתם מתרפאין<sup data-n=\"595\">34</sup>, לפי שנש\"י היו אז בחי' חולה ברגליהם לפי שהיו מושקעים במ\"ט שערי טומאה והיו צריכים לרפואה, ואמר להם בדבר קל היינו",[["590","29","<b>וע' מענין חולה בד\"ה כתפוח בעצי היער בס' פ'</b>: כנראה הכוונה לד\"ה זה שבבוך 1120 רצג, א ואילך [משנת תרכ\"ב. — בוך זה נזכר גם לעיל ספ\"ב]. ונדפס באוה\"ת שה\"ש (כרך א) ע' קצא. וראה בארוכה המשך וככה תרל\"ז ספפ\"ג ואילך (ע' צז ואילך)."],["591","30","<b>בלקו\"ת בד\"ה והי' מדי חדש</b>: ס\"פ ברכה צז, ב."],["592","31","<b>וע' בד\"ה ולא זכר שר המשקים ך\"ו</b>: לע\"ע לא מצאנו מאמר זה. וראה ד\"ה זכור גו' עמלק בסה\"מ תרכ\"ו (הוצאת תשמ\"ט) ע' כ ואילך [שם נת' מענין חולה, וכן נת' שם הפסוק ולא זכר גו']. ובשינויים שם בד\"ה אנכי ה\"א שם ע' נא וע' נח-ט. — ואולי הוא ד\"ה ולא זכר הנ\"ל בשינוי ההתחלה."],["593","32","<b>הנה כתי' באליהו וירפא את מזבח ה' ההרוס</b>: ראה בכ\"ז אוה\"ת נ\"ך (כרך א) ע' עז ואילך. שם ע' שנה. סה\"מ תרל\"ה ח\"ב ע' דש ואילך. המשך וככה תרל\"ז שם. סה\"מ תרנ\"א ע' רמ. תרנ\"ה ס\"ע קמג-ד. תרח\"צ ע' רי."],["594","33","<b>וע' בד\"ה ועשית ציץ ובד\"ה מגילה נקראת</b>: סה\"מ תרכ\"ז ע' קנג. וע' קעט-פ."],["595","34","<b>שאמר להם בדבר קל אתם מתרפאין</b>: הכוונה להמשך לשון השהש\"ר (ב, ג [ב] שם: ואמר לו בדבר קל אתה מתרפא. . כך אמר משה לישראל אתם מבקשים להגאל בדבר קל אתם נגאלין."]]],[2000510226,"באזוב שהוא בחי' ביטול ושפלות, כי בעל תשובה הוא בחי' שפלות לב נשבר ונדכה כו'.\n<b></b>[וטבלתם מן הדם אשר בסף, הוא בחי' תושב\"כ ותושבע\"פ<sup data-n=\"596\">35</sup>, כי סף הוא בחי' סמ\"ך מסכתות וכמ\"ש ששים המה מלכות ושמונים פלגשים וארז\"ל ששים המה מלכות ס' מסכתות ושמונים פלגשים אלו ברייתות שהוא בחי' תושבע\"פ, ודם הוא בחי' תושב\"כ לפי שרמ\"ח פקודין הם רמ\"ח אברין, והתורה היא בחי' דם בחי' פנימיות החיות של האברים כמ\"ש כי הדם הוא הנפש, ולכן נק' התורה אדם כמ\"ש זאת התורה אדם, אדם ר\"ת א' דם כמ\"ש בלק\"ת בד\"ה בשעה שהקדימו<sup data-n=\"597\">36</sup> פ\"ב. ועי\"ז והגעתם אל המשקוף ואל שתי המזוזות בחי' ג' אבות חח\"ן קו הימין בג\"ה קו השמאל וקו האמצעי המחברן, והיינו שכל אחד יכול לומר מתי יגיע מעשי למעשה אבותי. ועוי\"ל אל המשקוף ע\"ד השקיפה ממעון קדשך כו' וברך שגם מבחי' השקפה יומשך שיהי' וברך את עמך ישראל, וע\"ד שארז\"ל גדולי'. והיינו ואשים דברי כו' ובצל ידי כו' לנטוע שמים כו' ע\"י ג' בחי' תורה ועבודה וגמ\"ח עי\"ז ממשיכים בהשמים מבחי' על השמים כנ\"ל והיינו ע\"י ואגודתו על ארץ, עי\"ז נמשך הבונה בשמים מעלותיו וכנ\"ל]<sup data-n=\"598\">37</sup>.\n<b>וזהו</b> שאמר ר' יצחק<sup data-n=\"599\">38</sup> בזח\"ג הנ\"ל ואגודתו כד\"א ולקחתם אגודת אזוב, והיינו שכמו ע\"י האגודה נמשך להיות הבונה בשמים מעלותיו כנ\"ל, כמו\"כ זהו\"ע שע\"י האזוב וע\"י הדם אשר בסף בחי' תומ\"צ עי\"ז והגעתם אל המשקוף כו', דהנה אזוב הוא א\"ז ו\"ב, והיינו שהאל\"ף מאיר ונמשך בזיי\"ן זהו כענין הבונה בשמים מעלותיו, ו\"ב היינו שאח\"כ וא\"ו זעירא נמשך בבי\"ת היינו בחי' המל' בחי' ברכה, וזהו אזוב וסף זהו גימט' יוסף בחי' השפעת יסוד למל'. ומה שעל הזיי\"ן נמשך אל\"ף ובבי\"ת וא\"ו זהו כענין אחד בחלופי אתוון ועד שמתחלף האל\"ף על וא\"ו, וכמו לא צר, ולא אנחנו קרי בוא\"ו וכתיב באל\"ף, וזהו ע\"ד כגוונא דאינון מתייחדין<sup data-n=\"600\">39</sup> לעילא באחד אוף הכי איהי אתייחדא לתתא ברזא דאחד, ע\"כ צ\"ל אגודה אחת, ואז הבונה בשמים מעלותיו למהוי אחד באחד. ויובן זה ע\"ד מ\"ש בסדור ענין כגוונא דאינון מתייחדין שהמדות עליונות כשבאין למטה הן בבחי' הפירוד והתחלקות זמ\"ז, אך בעודן כלולים בהשכל שם הם ביחוד ויוכל להמתיק הדין כו', ועד\"ז בבי\"ע כי מיכאל שר של מים וגבריאל שר של אש, אך ע\"י המשל ופחד עושה",[["596","35","<b>וטבלתם מן הדם אשר בסף הוא בחי' תושב\"כ ותושבע\"פ</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת בא שם ע' שיב-ג (ס\"ז, וס\"ט)."],["597","36","<b>בלק\"ת בד\"ה בשעה שהקדימו</b>: פ' במדבר יג, א."],["598","37","<b>[וטבלתם. . וכנ\"ל]</b>: קטע זה נרשם בגוכי\"ק בס' תרכ\"ז בעלה בפ\"ע בתור הגה\"ה."],["599","38","<b>וזהו שא' ר' יצחק</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת בא שם ע' שיד (סי\"ג). ע' שטו (סט\"ז). וע' שכג. ובארוכה סה\"מ תרכ\"ז ע' רכח (בשוה\"ג). וס\"ע רכט ואילך."],["600","39","<b>בסידור ענין כגוונא דאינון מתייחדין</b>: סידור עם דא\"ח דף קסח, א ואילך. וראה גם סה\"מ תרכ\"ז ע' קעב-ג."]]],[2000510227,"שלום במרומיו<sup data-n=\"601\">40</sup> נעשה לאחדים כו', אך מ\"מ למעלה יחו\"ע ביטול אמיתי, ולמטה יש ובטל. ואח\"כ למהוי אחד באחד יחוד יחודא עילאה ביחודא תתאה, והיינו כמ\"ש בזהר ויקהל דקצ\"ז ע\"ב לייחדא רתיכא עילאה ברתיכא תתאה. ומזה יובן ענין ולקחתם אגודת אזוב יחוד ב' בחי' ביטול הנ\"ל, ועי\"ז נמשך להיות והגעתם אל המשקוף השקיפה כו' מן השמים וברך כו' שיומשך מבחי' על השמים בשמים, ואז וברך את עמך ישראל דוקא.",[["601","40","<b>המשל ופחד עושה שלום במרומיו</b>: ראה אגה\"ק סי\"ב (קיז, א). לקו\"ת תזריע כג, רע\"ג. ובהנסמן בסה\"מ תרל\"ג ח\"ב ע' תקלה. לעיל ע' לז. וש\"נ."]]],[2000510228,"<h3>אז ישיר כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ בשלח, ל\"א).</b>\nישראל ותורה\nבשלח\n<b>אז</b> ישיר<sup data-n=\"602\">1</sup> משה ובני ישראל, וארז\"ל ברבות ע\"ז הה\"ד נכון כסאך מאז<sup data-n=\"603\">2</sup> א\"ר ברכי' בשם ר' אבהו אע\"פ שמעולם אתה, לא נתיישבה כסאך ולא נודעת בעולמך עד שאמרו בניך שירה לכך נאמר נכון כסאך מאז, מאז ישיר, משל למלך שעשה מלחמה ונצח ועשו אותו אגוסטוס<sup data-n=\"604\">3</sup>, אמרו לו עד שלא עשית המלחמה היית מלך ועכשיו עשינו אותך אגוסטוס, מה כבוד יש בין מלך לאגוסטוס, מלך עומד על",[["602","1","<b>אז ישיר</b>: מאמר זה מיוסד והגהות על ד\"ה זה להצ\"צ בכת\"י 1120 נז, א [הכולל הנחות ממאמרי אדמו\"ר הצ\"צ]. המאמר נמצא עם ההגהות בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בכת\"י 1038 נב, א ואילך [הכולל מאמרים מלוקטים מכ\"ק אדמו\"ר מהר\"ש]. ונמצא גם בד\"ה זה בסה\"מ תרכ\"ט ע' קמד ואילך. ובספר תרמ\"א [ד\"ה אז ישיר וד\"ה זכור את יום השבת].\nמאמר הצ\"צ הנ\"ל מיוסד על ד\"ה אז ישיר בס' מאמרי אדה\"ז תקס\"ה ח\"א ע' רלו ואילך. הנחה אחרת במאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפב ואילך. ובארוכה בשער האמונה לאדהאמ\"צ פמ\"ב-מז (סט, א ואילך). אוה\"ת בשלח ע' תצ ואילך. וראה גם שם (כרך ז) ע' ב'תרסד ואילך.\nתוכן המאמר נמצא בשינויים והוספות בד\"ה זה: בסה\"מ תרנ\"ה ע' פ ואילך. תרס\"ה ע' קיט ואילך. עת\"ר ע' שיג ואילך. המשך תער\"ב ח\"ג ע' א'תג ואילך. עטר\"ת ע' רו ואילך. תרצ\"ב [ד\"ה אז ישיר וד\"ה לא תהי' משכלה]. הש\"ת ע' 58 ואילך [ד\"ה אז ישיר, וד\"ה עוטה אור, וד\"ה איזהו דרך ישרה]. תש\"ד ע' 127 ואילך. ד\"ה כמגדל דוד בסה\"מ תש\"ה ע' 119 ואילך. ד\"ה תורה צוה בסה\"מ תשי\"ז ע' 18 ואילך. ד\"ה והחרים וד\"ה ויהי ביום השמיני בסה\"מ תשכ\"ט ע' קעו ואילך. וע' קפז ואילך. ד\"ה הפך ים ליבשה בסה\"מ תשד\"מ (הוצאת תשס\"ב) ע' 358 ואילך."],["603","2","<b>וארז\"ל ברבות. . נכון כסאך מאז</b>: הובא ונת' (נוסף להנסמן בהערה הקודמת) בהמשך תער\"ב ח\"ב ע' תתמב. וע' תתנ. שיחת ש\"פ בשלח תנש\"א (ס' השיחות תנש\"א ח\"א ע' 290-1)."],["604","3","<b>למלך שעשה מלחמה ונצח ועשו אותו אגוסטוס</b>: ראה פרש\"י לב\"ר פ\"א, יב: בלשון יון אגוסטא — אדון. ובמ\"כ לשמו\"ר כג, א: אגוסטוס שם למלך אדיר. ובפי' מהרז\"ו הקצר לב\"ר שם: קיסר אגוסטלי כו' שמות של הקסריות בלשון רומי, אשר שמות אלו אינם זוכים אלא אחר שעושה מלחמות ונצחונות וכבישת מדינות רבות שמרחיב הממלכה. וראה המשך תער\"ב ח\"ג ע' א'תב: במלוכה יש ב' מדריגות הא' מלוכה על עבדים והוא בבחי' התנשאות על עם דהיינו בחי' חיצוניות המלוכה כו', והב' מלוכה על המלכים והוא הנק' אגוסטוס מלך המלכים שזהו בבחי' התנשאות עצמי כו'. וראה גם תו\"א מקץ מ, ב. אוה\"ת בשלח ע' תצ. וע' תצח. שם (כרך ז) ע' ב'תרעא. מאמרי אדהאמ\"צ בראשית ע' תכז. דברים ח\"ג ע' א'מט. שער האמונה לאדהאמ\"צ פמ\"ז (עו, א ואילך). מאמרי חודש תשרי תשי\"ז."]]],[2000510229,"הלוח ואגוסטוס יושב<sup data-n=\"605\">4</sup>, כך אמרו ישראל עד שלא בראת עולמך היית אתה, ומשבראת אותו אתה הוא, אלא כביכול עומד שנאמר עמד וימודד ארץ, אבל משעמדת בים ואמרנו שירה לפניך באז נתיישבה מלכותך וכסאך נכון, הוי נכון כסאך מאז.\n<b>והנה</b> להבין זה צ\"ל מ\"ש עוד ברבות שה\"ש כמגדל דוד צוארך מה שגידל אתכם דוד בספרו שנאמר לגוזר ים סוף לגזרים כי לעולם חסדו. והנה לכאורה צ\"ל פעם מצינו שישראל נתגדלו על הים וכמשארז\"ל במד\"ר ראה הפחות שבפחותים בימי משה מה שלא ראה הגדול שבנביאים, ורש\"י ז\"ל פי' ע\"פ זה אלי ראתה שפחה על הים<sup data-n=\"606\">5</sup> מה שלא ראו נביאים, והוא מהילקוט שמעוני רמז רמ\"ד שהביא בשם מכילתא וז\"ל ר' אליעזר אומר מנין אתה אומר שראתה שפחה על הים מה שלא ראה יחזקאל וישעי' שנאמר וביד הנביאים אדמה (הושע י\"ב) וכתיב נפתחו השמים ואראה כו' (יחזקאל סי' א'). ועוד ארז\"ל ברבות כמה גדולים יורדי הים<sup data-n=\"607\">6</sup> שהרי משה רבן של כל הנביאים כמה נתחבט שביקש הראני נא את כבודך, ומעלת נבואתו הי' שנתנבא בזה, ועל הים אמרו כולם זה אלי וכמארז\"ל כל א' מראה באצבעו זה אלי כו', ונמצא שבשעת קי\"ס נתגדלו ישראל. ופעם משמע להיפוך שהים נתבטל לפני ישראל וכמ\"ש בוקע ים לפני משה שכיון שראה הים את משה ובנ\"י נתבטל ונקרע לפניהם, וכדמשמע גם מהמדרש הנ\"ל כמגדל דוד כו' שגידל אתכם דוד בספרו וסיפר איך שהים נתבטל לפניהם כמ\"ש לגוזר י\"ס לגזרים כל\"ח, שמכ\"ז משמע שישראל גבוהים מהים.\n<b>אך</b> הענין הוא דהנה כדוגמא זו מצינו בתורה ג\"כ, שפעם משמע שהתורה היא למעלה מישראל, ופעם משמע שישראל הם למעלה<sup data-n=\"608\">7</sup> מהתורה, וכמשארז\"ל ע\"פ תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורסה שהתורה נק' כלה וכנס\"י חתן, ונמצא כי גדלה מעלת ישראל על התורה, ופעם משמע להיפוך שהרי איתא בזהר תלת קשרין מתקשרין דא בדא<sup data-n=\"609\">8</sup> ישראל באורייתא ואורייתא בקוב\"ה, נמצא שהתורה היא למעלה מישראל, שהרי באמצעות התורה מתקשרין ישראל לקוב\"ה. והענין הוא דשניהם אמת, דהנה כמו שנתלבשו נשמות בגופים התורה היא למעלה",[["605","4","<b>מלך עומד על הלוח ואגוסטוס יושב</b>: כאשר המלך שעל כל המלכים שנקרא אגוסטוס בא לעיר אז המלך עומד לפניו ואגוסטוס יושב כו' (שער האמונה שם)."],["606","5","<b>במד\"ר ראה הפחות שבפחותים בימי משה. . ראתה שפחה על הים</b>: ראה בכ\"ז בארוכה לקמן המשך והחרים ס\"ע רסד ואילך."],["607","6","<b>ברבות כמה גדולים יורדי הים</b>: נת' בארוכה לקמן המשך והחרים ע' רסו. רסז."],["608","7","<b>אך הענין. . מצינו בתורה ג\"כ. . שהתורה היא למעלה. . שישראל הם למעלה</b>: בהבא לקמן ראה גם לקו\"ת שה\"ש טז, ד ואילך. שם יז, ד ואילך. ובכ\"מ."],["609","8","<b>תלת קשרין מתקשרין דא בדא</b>: בסה\"מ תרנ\"ז ע' כח מציין על לשון זה [והובא בהערה בסה\"מ ה'ש\"ת שם]: צ\"ע דבזהר (ח\"ג עג, א) לא נאמר ג' קשרין, כי אם ג' דרגין כו', אמנם בודאי נמצא באיזה מקום בזהר או בתיקונים בל' ג' קשרין. וכפי הנראה אדמו\"ר הזקן אמר בכל פעם בל' ג' קשרין שכן נזכר הל' בכל הדרושים. ע\"כ. וראה גם במפתח ענינים שם [מכ\"ק אדמו\"ר] ע' שכה — שמציין להלשון באגרת אדה\"ז [אגרות-קודש אדה\"ז ע' צט]. וראה לקו\"ש ח\"ט ע' 73."]]],[2000510230,"מישראל, והיינו כי כדי שיהי' התחברות אלקות עם נש\"י זהו ע\"י אמצעות התורה שישראל מתקשראן באורייתא, והתורה היא בחי' לבושו של הקב\"ה<sup data-n=\"610\">9</sup> וכמ\"ש עוטה אור כשלמה<sup data-n=\"611\">10</sup> שהתורה היא בחי' שלמה ולבושו של הקב\"ה ועל ידה מתחבר אוא\"ס עם העולמות. וענין אור ושלמה שיש בבחי' התורה היינו שיש בתורה שני בחי', והם הנק' אור ושלמה, בהיות מבואר כי התורה היא הממוצע בין אוא\"ס להעולמות<sup data-n=\"612\">11</sup> וכמ\"ש בזהר אסתכל באורייתא וברא עלמא, וזהו בראשית ברא בבחי' התורה שנק' ראשית כמ\"ש ה' קנני ראשית דרכו ברא את כל העולמות, והיינו שהתורה היא ממוצע בין אוא\"ס לעולמות, וכל ממוצע צ\"ל כלול מב' הבחי' כנודע<sup data-n=\"613\">12</sup>, והיינו שהיא כלולה מאוא\"ס שהוא בלתי בע\"ג, וגם מבחי' שרש ומקור הגבול, שהעולמות הם בבחי' גבול כו'. וזה\"ע אור ושלמה שיש בתורה היינו ב' הבחי' שבהממוצע כו'. וזהו מה שישראל מתקשראן באורייתא להיות כי נש\"י נתלבשו בגופים, וכדי שיתחברו לאוא\"ס זהו ע\"י התורה, ואורייתא סתים וגליא וישראל סתים וגליא, וע\"י סתים שבתורה נתחבר הסתים שבישראל אל בחי' סתים דקוב\"ה, וע\"י גליא שבתורה נתחבר הגליא שבישראל אל בחי' גליא דקוב\"ה, או י\"ל<sup data-n=\"614\">13</sup> שבחי' סתים שבנש\"י מתחבר עם בחי' גליא דתורה, וע\"י בחי' סתים דתורה מתחבר לבחי' גליא דקוב\"ה, ונמצא כי סתים וגליא דתורה הם הממוצעים בין סתים דנש\"י לבחי' גליא דקוב\"ה, וזהו שהתורה היא ממוצע. ובכ\"ז יובן מ\"ש על מה אבדה הארץ ויאמר ה' על עזבם את תורתי, והיינו כמארז\"ל ע\"פ אותי עזבו, הלואי אותי עזבו ותורתי שמרו שהמאור שבה מחזירם למוטב כו', והיינו כמשנת\"ל שיש בכח התורה לחבר נש\"י לאלקות כו'.\n<b>וזהו</b> שארז\"ל מעיקרא כי עביד אינש אדעתא דנפשי' קעביד, דהיינו כדי שעי\"ז יתחבר הנפש לאלקות, אך אח\"כ צ\"ל עסק התורה לשמה היינו לשם התורה, דהנה התורה נתלבשה למטה בדברים גשמיי' כמו המחליף פרה בחמור, ארבע רשויות לשבת, שא\"א לומר שהתורה כמו שהיא למעלה<sup data-n=\"615\">14</sup> היא באופן זה כמו שהיא למטה ממש, רק שלמעלה הנה ענין ארבע רשויות, רשות הרבים הו\"ע עולם התהו, ורשות היחיד הוא עולם התיקון, וכשנמשכה למטה נתלבשה בדברים גשמיי' כו', וצריכים לחבר את התורה כמו שהיא למטה עם תורה שלמעלה, וזהו פי' לשמה דהיינו לשם התורה שלמטה לחברה עם תורה שלמעלה. וזהו מ\"ש ביעקב ויצוק",[["610","9","<b>והתורה היא בחי' לבושו של הקב\"ה</b>: ראה תניא פנ\"ב (עג, א)."],["611","10","<b>עוטה אור כשלמה</b>: ראה גם לקו\"ת דרושים לשמע\"צ פו, א. סידור עם דא\"ח ג, ג ואילך. אמ\"ב שער הציצית פ\"א. יהל אור להצ\"צ עה\"פ."],["612","11","<b>כי התורה היא. . הממוצע בין אוא\"ס להעולמות</b>: ראה בארוכה המשך תער\"ב ח\"א ע' שכד ואילך. ובכ\"מ."],["613","12","<b>וכל ממוצע צ\"ל כלול מב' הבחי' כנודע</b>: ראה לקמן המשך והחרים ע' שיב. [ובהמ\"מ שם]."],["614","13","<b>ואורייתא סתים וגליא. . וישראל. . או י\"ל</b>: ראה גם המשך תרס\"ו ע' שפה-ו. תער\"ב ח\"ב ע' תשמו-ז. ד\"ה זה היום תחלת מעשיך (די\"ט כסלו) תשד\"מ. ועוד."],["615","14","<b>כמו המחליף פרה בחמור. . שהתורה כמו שהיא למעלה</b>: ראה סה\"מ תרל\"ח ע' קסא ואילך. וש\"נ. סה\"מ תרע\"ח (הוצאת תשד\"מ) ע' תטז. המשך תער\"ב ח\"א ע' שסח-ט. סה\"מ תרפ\"ז ס\"ע קפז-ח. תרפ\"ט ע' 157-8. תש\"א ע' 38-9. תש\"ו ע' 112. ד\"ה איהו וחיוהי חד תשט\"ז. ועוד."]]],[2000510231,"שמן על ראשה דהיינו שהמשיך בחי' תורה כמו שהיא למעלה בבחי' ח\"ע<sup data-n=\"616\">15</sup> שנק' שמן למטה כו'.\n<b>ועוי\"ל</b> לשמה לשם התורה שלמעלה, דהיינו להמשיך אוא\"ס בתורה, וכמשארז\"ל דוד הי' מחבר תורה שלמעלה<sup data-n=\"617\">16</sup> בהקב\"ה, דהנה אורייתא מחכמה נפקת, ובאמת לגבי אוא\"ס אפי' ח\"ע אין ערוך אליו וכמ\"ש כולם בחכ' עשית כו' שהחכ' נחשבת כעשי' גשמי'<sup data-n=\"618\">17</sup> לפניו ית'. וזהו שהתורה נק' בחי' לבוש וכנ\"ל בענין עוטה אור כשלמה, והנה בלבוש יש הפרש בין כשהמלך לובש את הלבוש ובין כשאין לובש אותו הלבוש, שגם בשעה שאינו לובש אותו הוא ג\"כ לבוש המלך, וכמ\"ש יביאו לבוש מל' אשר לבש בו המלך היינו שלבש אותו כבר, מ\"מ כשהמלך מלובש כעת בלבוש מל' הוא נראה ונגלה לכל שהוא לבוש המלך כו', ועד\"ז יובן בענין התורה שהיא בחי' לבושו של הקב\"ה הנה עבודת נש\"י להמשיך שיתלבש אוא\"ס ב\"ה בלבושי התורה שזהו\"ע לחבר תורה שלמעלה בהקב\"ה שיתלבש בלבושי התורה כו'. והכח שיש לנש\"י להמשיך אוא\"ס ב\"ה שיתלבש בלבושי התורה, דהנה התורה נק' ראשית וכמ\"ש בראשית בשביל התורה שנק' ראשית, והנה ראשית ל' נוק' שהוא בחי' מקבל, אבל ישראל הם בחי' לי ראש ל' דכר, והיינו שממשיכים בבחי' ראשית שהיא התורה מבחי' אשר שהוא בחי' תענוג עליון. וזהו פי' לשמה לשם התורה להמשיך אא\"ס בהתורה כו'. וזהו שארז\"ל מעיקרא כי עביד אינש אדעתא דנפשי' קעביד ואח\"כ ילמוד לשמה, דהיינו מתחלה צריך ללמוד כדי שעי\"ז יהי' התקשרות הנפש לאלקות, ישראל מתקשראן באורייתא, וכשמתקשר לאוא\"ס מתעלה עד שרש ומקור נש\"י ואז יכולים להמשיך אוא\"ס ב\"ה בתורה, וזהו לשמה לשם התורה להמשיך אא\"ס בתורה. וזהו מ\"ש כי אם בתורת ה' חפצו ובתורתו<sup data-n=\"619\">18</sup> יהגה כו', והיינו שמתחלה נק' תורת הוי', שהתורה היא למעלה ממנו, ואח\"כ נק' תורתו, ע\"ד מה שהתורה נק' תורת משה וכמ\"ש זכרו תורת משה עבדי, שנק' תורת משה לפי שמשה המשיך אוא\"ס בתורה לכן נק' תורת משה, וזהו ג\"כ פי' וענין תורתו שע\"י שממשיך אוא\"ס בתורה נק' תורתו. נמצא ששניהם אמת ישראל מתקשראן באורייתא שהתורה למעלה ממנו, וגם כנס\"י נק' חתן והתורה נק' כלה מאורסה כו'.\n<b>ועד\"ז</b> מצינו במצות ג\"כ, דהנה אנו אומרים אשר קדשנו במצותיו דמשמע שהמצות הם למעלה מהאדם, שרמ\"ח פקודין הם רמ\"ח אברים דמלכא שהוא בחי' המלך הקדוש, וכתי' אשר יעשה אותם האדם וחי בהם וארז\"ל אתם כתיב מעלה אני עליכם כאלו עשאוני, שישראל עושים את המצות בחי' רמ\"ח",[["616","15","<b>וזהו מ\"ש ביעקב ויצוק שמן על ראשה. . ח\"ע</b>: ראה בכ\"ז תו\"א ויצא כא, ב. כב, ב."],["617","16","<b>דוד הי' מחבר תורה שלמעלה</b>: ראה גם לקו\"ת שלח נא, א. ובכ\"מ."],["618","17","<b>כולם בחכמה עשית. . כעשי' גשמי'</b>: ראה גם שעהיוה\"א פ\"ט (פו, א). ובכ\"מ."],["619","18","<b>מעיקרא. . אדעתא דנפשי' קעביד. . בתורת ה'. . ובתורתו</b>: ראה בכ\"ז בס' מאמרי אדהאמ\"צ דרושי-חתונה ח\"א ע' יט. קעד. רסז. ח\"ב ע' תפג. ובס' מאמרי אדהאמ\"צ שמות ח\"ב ע' שסז [ובהמ\"מ שם נסמן למקומות רבים בזה]."]]],[2000510232,"אברים דמלכא שהוא בחי' רמ\"ח אברים דז\"א, שהרי באמת ע\"י המצות עצמם בלא איש הישראלי העושה המצוה הרי היא אינה מצוה כלל<sup data-n=\"620\">19</sup> ולא נמשך על ידה כלום, עד\"מ תפילין כשהם מונחים על השולחן ה\"ה רק תשמישי קדושה ולא מצוה ואין נמשך על ידה כלום, כ\"א ע\"י שהישראל מניח התפילין, ונמצא כי נש\"י עושים את המצות כו', ושניהם אמת. דהנה בשבת אומרים קדשנו במצותיך, ולכאו' אינו מובן שהרי אנו מברכין על המצות אשר קדשנו במצותיו<sup data-n=\"621\">20</sup>, ומהו שאומרים בשבת קדשנו במצותיך דרך בקשה, אלא הענין הוא שיש שני בחי' במצות, שיש בחי' מצות הוי' ומצותיך ממש<sup data-n=\"622\">21</sup>, מצות הוי' הוא בחי' רמ\"ח פקודין רמ\"ח אברי' דמלכא שהם בחי' כלים, כי ט' ספירות דז\"א ט' פעמים ט' הם פ\"א, וראש תוך סוף הוא רמ\"ג וה' חסדים המגדילי' הם רמ\"ח, ויש בחי' מצותי<sup data-n=\"623\">22</sup>ו ממש והו\"ע תר\"ך עמודי אור כו'. וזהו שמתחלה המצות הם למעלה מנש\"י אשר קדשנו במצותיו שע\"י המצות נתעלה האדם לשרשו, אבל אח\"כ נש\"י הם למעלה מהמצות כי נש\"י ממשיכים אח\"כ במצות מבחי' אא\"ס ממש בחי' תר\"ך עמודי אור כו'. ובזה יובן מ\"ש וזכרתם את כל מצות הוי' כו' למען תזכרו ועשיתם את כל מצותי כו', והיינו שמתחלה המצות הם בחי' דכר ונקראי' מצות הוי' כו', אבל אח\"כ למען תזכרו ועשיתם את כל מצותי, שנש\"י הם בחי' דכר שממשיכי' ומשפיעים מבחי' מצותי ממש לבחי' מצות הוי' כו'. וזהו ג\"כ ע\"ד מ\"ש והחיות נושאות את הכסא, וארז\"ל נושאות ומנושאות<sup data-n=\"624\">23</sup>, שמתחלה נושאות ואח\"כ מנושאות, וכן ארז\"ל ארון נושאיו נשא, ועד\"ז הוא התומ\"צ עם נש\"י כו' שהתומ\"צ מגביהים ונושאי' את נש\"י, ועי\"ז הם מנושאות כו'.\n<b>ובזה</b> יובן ג\"כ ענין קריעת ים סוף, שפעם משמע שנש\"י נתעלו על הים, ופעם משמע שהים נתבטל לפניהם, ושניהם אמת. דהנה ים ויבשה הוא בחי' עלמא דאתכסיא ועלמא דאתגלי'<sup data-n=\"625\">24</sup>, וכמו שארז\"ל כל מה שיש ביבשה יש בים כו', רק שההפרש הוא שהברואים שבים הם מובלעים בים ואינם נפרדים כלל, משא\"כ הברואי' שביבשה הגם שמקבלים חיות מהיבשה אעפ\"כ הם נפרדים כו', ועד\"ז יובן למעלה שיש בחי' עלמא דאתכסיא ועלמא דאתגלי'. והנה נש\"י כמו שנמשכו למטה הם בחי' ארץ וכמ\"ש כי תהיו לי אתם ארץ חפץ, והארץ לעולם עומדת, עמד וימודד ארץ ויש פי' שקאי על נש\"י<sup data-n=\"626\">25</sup> שמדד שיקבלו את התורה, נמצא שנש\"י נק'",[["620","19","<b>בלא איש הישראלי. . אינה מצוה כלל</b>: ראה גם תו\"א שמות נג, ד. יתרו ע, סע\"ד. ד\"ה הבאים ישרש תשמ\"ג."],["621","20","<b>בשבת אומרים קדשנו במצותיך. . אינו מובן שהרי אנו מברכים. . קדשנו במצותיו</b>: ראה בכ\"ז בארוכה לקו\"ת במדבר ט, ג."],["622","21","<b>שיש שני בחי' במצות. . מצות הוי' ומצותיך ממש</b>: ראה לקו\"ת במדבר ט, ג שם."],["623","22","<b>ובזה יובן מ\"ש וזכרתם. . מצות הוי' כו' למען תזכרו. . מצותי</b>: בהבא לקמן ראה בארוכה לקו\"ת שלח מה, סע\"א-ב. מו, א-ב. מז, ג."],["624","23","<b>וארז\"ל נושאות ומנושאות</b>: בפיוט ”וחיות\" בקדושת כתר במוסף א' דר\"ה: ”נראות נושאות והם נשואות עם כסא. . ארבע חיות נושאות ומנושאות עם כסא\". וראה עד\"ז בחיי תרומה כה, י — בשם פדר\"א [ספ\"ד. וראה רד\"ל שם]. במדב\"ר ספי\"ד. שמו\"ר ספכ\"ג."],["625","24","<b>ים ויבשה. . עלמא דאתכסיא ועלמא דאתגליא</b>: בהבא לקמן ראה בארוכה לקמן המשך והחרים ע' רסד-ה. וש\"נ. ע' שו ואילך. וש\"נ."],["626","25","<b>עמד וימודד ארץ ויש פי' שקאי על נש\"י</b>: ראה ויק\"ר פי\"ג, ב: רשב\"י פתח עמד וימודד ארץ מדד הקב\"ה כל האומות ולא מצא אומה שהיתה ראויה לקבל את התורה אלא דור המדבר. — הובא ונת' בד\"ה עמד וימודד ארץ בסה\"מ תש\"ה ע' 192 ואילך."]]],[2000510233,"ארץ לפי שכשירדו למטה הם בבחי' יש ודבר נפרד, לכן ע\"י קי\"ס שים הוא בחי' עלמא דאתכסי', וכשנעשה הים ליבשה בחי' גילוי עלמא דאתכסי' בעלמא דאתגלי' עי\"ז נתעלו ישראל ואמרו זה אלי וזכו לנבואה, כי נבואה הו\"ע גילוי ההעלם, וקי\"ס הוא ג\"כ גילוי ההעלם שמעלמא דאתכסי' נעשה עלמא דאתגלי', לכן זכו לנבואה.\n<b>אך</b> זה מה שהים הוא למעלה מישראל זהו כמו שנש\"י הם למטה, אבל שרש הנשמות הם למעלה מהים, כי ים הוא בחי' עלמא דאתכסי' שהוא בחי' עלמין כו', אבל נש\"י קדמו לעולם וכמשארז\"ל שבעה דברים קדמו לעולם ומחשבתן של ישראל קדמה לכל דבר, ומה גם שהים ויבשה שניהם נבראו מבחי' דבור, אבל נש\"י עלו במח' וכמ\"ש בעבר הנהר ישבו אבותיכם<sup data-n=\"627\">26</sup> ששרש הנשמות הם למעלה אפי' מבחי' נהר, כי ים הוא בבחי' ים סוף שהוא סופא דכל דרגין בחי' מל', ונהר הוא בחי' בינה<sup data-n=\"628\">27</sup>, ושרש הנשמות הם למעלה אפי' מבחי' נהר, ולכך מצד שרש נשמתם נתבטל הים לפניהם בוקע ים לפני משה, לפי שבים הי' גילוי בחי' שרש הנשמה<sup data-n=\"629\">28</sup> וכמ\"ש משה ובני ישראל, בנ\"י הם בחי' הנשמה כמו שהיא למטה, ומשה הוא הממשיך בחי' מקור ושרש הנשמה וכמ\"ש כי תקנה עבד עברי, עבד הוא בחי' הנשמה כמו שהיא למטה שנק' עבד וכמ\"ש יעקב עבדי, ועברי הוא בחי' שרש הנשמה בעבר הנהר ישבו אבותיכם, ומשה הוא הממשיך מבחי' שרש הנשמה למטה, וזהו כי תקנה עבד עברי, קנין הוא המשכה מהעלם אל הגילוי, וכי תקנה קאי על משה שמשה שהוא בחי' דעת הוא ממשיך מבחי' שרש הנשמה למטה כו', ובחי' משה ישנו בכאו\"א וכמ\"ש ועתה מה הוי' שואל מעמך כ\"א ליראה, ומקשינן אטו יראה מילתא זוטרתי היא<sup data-n=\"630\">29</sup>, אין לגבי משה מילתא זוטרתי היא, ולכאו' אינו מובן שהרי מעמך כתיב, אלא לפי שבחי' משה יש בכאו\"א שהוא בחי' דעת שבכאו\"א שממשיך מבחי' שרש הנשמה למטה, וזהו משה ובני ישראל.\n<b>וזהו</b> מ\"ש אז ישיר, דלכאו' אינו מובן שהי' צ\"ל אז ישירו משה ובנ\"י, אלא לפי שמשה ובנ\"י הוא בחי' אחת<sup data-n=\"631\">30</sup>, וזהו אז ישיר, ישיר הוא בחי' העלאה ממטלמ\"ע, ואז הוא בחי' המשכה מלמעלמ\"ט כי אז הוא בחי' אל\"ף זיי\"ן<sup data-n=\"632\">31</sup>, זיי\"ן הוא בחי' ז' מדות ואל\"ף הוא בחי' אלופו של עולם שהוא המשכה מבחי' אלופו של",[["627","26","<b>נש\"י עלו במח' וכמ\"ש בעבר הנהר ישבו אבותיכם</b>: ראה בארוכה לקו\"ת בחקותי מו, סע\"ד ואילך. סה\"מ תרנ\"ז ע' ס ואילך. תש\"כ ע' 104 ואילך."],["628","27","<b>ים. . ים סוף. . בחי' מל' ונהר. . בינה</b>: ראה בארוכה לקו\"ת צו טז, ד. יז, א ואילך. ועוד."],["629","28","<b>וכמ\"ש כי תקנה עבד עברי. . ועברי. . שרש הנשמה</b>: ראה בכ\"ז תו\"א משפטים עה, ד."],["630","29","<b>אטו יראה מלתא זוטרתי. . שבחי' משה יש בכאו\"א</b>: ראה תניא פמ\"ב (נט, א)."],["631","30","<b>דלכאו'. . צ\"ל אז ישירו. . אלא לפי שמשה ובנ\"י הוא בחי' אחת</b>: ראה פי' האוה\"ח עה\"פ הובא ונת' בלקו\"ש חל\"א ע' 70 ואילך."],["632","31","<b>אז הוא בחי' אל\"ף זיי\"ן</b>: ראה בכ\"ז לקו\"ת דרושים לשמע\"צ פח, ב. ובארוכה סה\"מ תרע\"ח ע' רסט ואילך. תש\"ד ע' 191 ואילך. תש\"ה ע' 167 ואילך. תשי\"ג ע' 394. [ובדרושים שנסמנו לעיל בתחילת המאמר]."]]],[2000510234,"עולם בבחי' ז' מדות, וכשנעשה התחברות בחי' אז וישיר דהיינו משה ובנ\"י, כי אז קאי על שרש הנשמה וכמ\"ש נכון כסאך מאז, ולמדו מזה במד\"ר שכסה\"כ קדמה לעולם שנא' נכון כסאך מאז, וגם נש\"י קדמו לעולם לכן הם נקראי' אז וכמ\"ש כגר כאזרח שפי' אזרח הוא בחי' תושב שהוא מכבר<sup data-n=\"633\">32</sup> כו' שזהו כמו אז, אזי בוקע ים לפני משה שבטל הים לפניהם. וזהו מ\"ש לגוזר ים סוף לגזרים ואיתא בילקוט שהוא בזכות המילה שבערבי קורין למהולים גזורים, וכן איתא בגמ' ר\"י הגוזר ופרש\"י ז\"ל מוהל תינוקות, וזהו לגוזר ים סוף לגזרים שבזכות המילה נקרע הים, לפי שמילה היא ג\"כ בשמיני שהוא בחי' אל\"ף זיי\"ן, וכמשארז\"ל לכך המילה בשמיני כדי שיעבור עליו שבת א', שמילה הוא למעלה משבת<sup data-n=\"634\">33</sup> ששבת הוא יום הז' ומילה הוא למעלה משבת כו', ולכך נקרע הים לפניהם.\n<b>וזהו</b> משארז\"ל קשה לזווגם כקרי\"ס, דלכאו' אינו מובן מה שייך קרי\"ס לזיווג, אך הענין הוא כנ\"ל דהתורה נק' מאורסה לפי שהתורה נקראת ראשית שהיא בחי' נוק' שהיא בחי' מקבל, אבל נש\"י שהוא לי ראש הם ממשיכים בתורה בחי' אשר בחי' תענוג עליון שהוא למעלה מחכ'. וכן עד\"ז כתי' זכור את יום השבת לקדשו, דלכאו' אינו מובן שהרי שבת מקדשא וקיימא<sup data-n=\"635\">34</sup> ומהו לקדשו, אלא הענין הוא דשבת נק' שבת בראשית שהוא בחי' מוחי' דאבא והוא בחי' מקבל, אבל נש\"י הם בחי' זכור שממשיכי' בבחי' חכ' מבחי' תענוג עליון וכמ\"ש וקראת לשבת ענג אז תתענג על הוי', למעלה משם הוי' שהוא בחי' חכ' הוי' בחכ' כו'. וזהו משארז\"ל אמרה שבת לפני הקב\"ה לכולם נתת בן זוג ולי לא נתת בן זוג, א\"ל הקב\"ה כנס\"י יהי' בן זוגך, משמע שנש\"י הם בחי' דכר ושבת היא בחי' נוק' בחי' מקבל שנש\"י הם ממשיכים בשבת, ונק' שבת בחי' זיווג זכור את יום השבת כו'. ועד\"ז הוא בבחי' ים סוף שנק' זיווג, והיינו לפי שנש\"י הם למעלה מבחי' ים וממשיכים בים לפי שים הוא ים סוף סופא דכל דרגין שהוא בחי' מל', ונש\"י הם בבחי' ז\"א כו', ואפי' אם נפרש שים הוא בחי' ים החכ' אעפ\"כ שרש נש\"י הם למעלה גם מבחי' חכ' כנ\"ל בפי' זכור את יום השבת לקדשו שממשיכים בבחי' חכ' כו', ולכן נק' קי\"ס בחי' זיווג.\n<b>וזהו</b> מ\"ש ברבות כמגדל דוד צוארך מה שגידל אתכם דוד בספרו לגוזר י\"ס לגזרים, היינו שדוד הודיע לנו שזה שנבקע הים ובטל לפניהם זהו מצד שרשם שהם למעלה מהים, כי בתורה לא נא' רק ובנ\"י הלכו ביבשה בתוך הים, שמזה משמע שע\"י הים נתעלו נש\"י שהלכו ביבשה בתוך הים, דהיינו שמעלמא",[["633","32","<b>שפי' אזרח. . תושב שהוא מכבר</b>: ראה גם סה\"מ תרכ\"ו ע' רח. תרל\"ג ח\"ב ע' תמה. ס\"ע תנו. לקמן המשך והחרים ע' שטו-ז."],["634","33","<b>המילה בשמיני. . למעלה משבת</b>: ראה לקו\"ת תזריע כ, ד ואילך. אוה\"ת דרושים ליוהכ\"פ ע' א'תקנו. א'תקנח. סה\"מ תרל\"ג ח\"ב ע' תקיט. סה\"מ מלוקט ח\"ה ע' טו-ז. ועוד."],["635","34","<b>זכור את יום השבת לקדשו. . שהרי שבת מקדשא וקיימא</b>: ראה תו\"א יתרו סט, סע\"ג. באוה\"ת יתרו ע' תתרכה ובסה\"מ תרכ\"ו ע' א מובא קושיא זו בשם האלשיך. וראה גם אוה\"ת יתרו (כרך ז) ע' ב'תרצ. סה\"מ תרכ\"ז ע' קכה."]]],[2000510235,"דאתכסיא נעשה עלמא דאתגלי' שזהו מעלת הים, אבל דוד הודיע לנו ואמר לגוזר י\"ס לגזרים שמצד שרש הנשמה נתבטל הים לפניהם להיותם במעלה ומדרגה גבוה יותר מהים כו'. ואח\"כ אמר והעביר ישראל בתוכו, היינו שמספר גם מעלת הים שע\"י הים נתעלו נש\"י, ולכן חלקם ואמר ב' פעמים כי לעולם חסדו אחד על עברם בים ואחד על מה שנגזר הים לגזרים, דלכאו' אינו מובן שהרי הם בחי' אחת שהרי מה שגוזר הי\"ס לגזרים היינו בכדי שיעברו ישראל בתוכו, דאילו לא העביר ישראל בתוכו מאי מעליותא במה שגזר הי\"ס לגזרים, אך לפי הנ\"ל יובן היטב לפי שבאמת הוא חסד בפ\"ע מה שגזר הי\"ס לגזרים, לפי שבזה גילה לנו ששרש הנשמות הם למעלה מהים עד שהים נתבטל לפניהם לכן הוא חסד בפ\"ע. ולכן אנו אומרים בהגדה אילו קרע לנו את הים<sup data-n=\"636\">35</sup> ולא העבירנו בתוכו בחרבה דיינו, לפי שבזה עצמו הי' די לנו שבזה הודיע שרש ומקור נש\"י כנ\"ל.\n<b>ובזה</b> יובן המדרש נכון כסאך מאז, אעפ\"י שמעולם אתה לא נתיישבה כסאך אלא מאז כו', לפי שמתחלה כביכול עמד וימודד ארץ, ובקי\"ס נתיישבה מלכותך כו'. והענין הוא דהנה בשבת אנו אומרים ביום השביעי נתעלה וישב<sup data-n=\"637\">36</sup> על כסא כבודו, ולכאו' צ\"ל היכן מרומז זה בתורה שביום השביעי נתעלה וישב כו'. והענין הוא דהנה אנו רואים ההפרש שבין עמידה לישיבה<sup data-n=\"638\">37</sup> שעמידה הוא כשאדם טרוד במלאכה אזי הוא עומד, משא\"כ ישיבה מורה על בחי' מנוחה, וכמ\"ש בשלמה וישב על כסא ה' וכתי' בו והוא יהי' איש מנוחה, וכן כתי' וישב יעקב ופרש\"י ביקש לישב בשלוה, לפי שישיבה מורה על מנוחה כו'. ועד\"ז יובן ענין שביום השביעי נתעלה וישב כו', והיינו לפי שבששת ימים נתלבשו החכ' והמדות בבחי' עשי', והגם כי לא בעמל ויגיעה ברא הקב\"ה את עולמו, אבל מ\"מ בחי' עשרה מאמרות נק' בחי' עשי' לפי שעשרה מאמרות הם מילין דהדיוטא לגבי אוא\"ס ע' בד\"ה ולקחתם אגודת אזוב<sup data-n=\"639\">38</sup>, ולאו אורחא דמלכא לאשתעי במילין דהדיוטא, לכך נק' עשרה מאמרות בשם עשי', וזהו בחי' עמידה. אך בשבת שהוא בחי' שביתה ומנוחה לכן הוא בחי' ישיבה, וזהו ביום השביעי נתעלה וישב על כסא כבודו, כסא הוא בחי' שביעאה<sup data-n=\"640\">39</sup> כי שית דרגין לכורסייא ושביעאה עלייהו, שביעאה הוא בחי' כסא כו', וזהו וישב על כסא כו'. ועד\"ז יובן ענין שבקי\"ס נתיישבה כסאך, והיינו לפי שקודם קי\"ס כתי'",[["636","35","<b>ולכן חלקם. . ב\"פ כי לעולם חסדו. . אילו קרע לנו את הים</b>: ראה בארוכה מאמרי אדהאמ\"צ ויקרא ח\"א ע' שסז. ד\"ה אילו קרע לנו את הים וד\"ה הפך ים ליבשה — תשכ\"ז. ובהגש\"פ עם לקוטי טעמים ומנהגים (הוצאת תשמ\"ו ואילך) ע' קסה-ו."],["637","36","<b>בשבת אנו אומרים ביום השביעי נתעלה וישב</b>: בכ\"ז ראה גם מאמרי אדה\"ז על מארז\"ל ותפילה ע' שנח."],["638","37","<b>ההפרש שבין עמידה לישיבה</b>: ראה בארוכה אוה\"ת חנוכה (כרך ז) תתתרנז, א ואילך. בהעלותך ע' שנט. סה\"מ תרנ\"ד ע' קסב ואילך. המשך תער\"ב ח\"א ע' תשא. ח\"ג ע' א'רצא ואילך. ד\"ה ואתה ברחמיך תשי\"ז ותשל\"ט. ד\"ה באתי לגני וד\"ה היושבת בגנים — תשל\"ט [סה\"מ באתי לגני ח\"ב ע' קסג, קסח ואילך, קעה]."],["639","38","<b>בד\"ה ולקחתם אגודת אזוב</b>: תרל\"א לעיל ס\"ע קמה-ו."],["640","39","<b>כסא הוא בחי' שביעאה כי שית דרגין לכורסי'</b>: נת' בארוכה באוה\"ת ויקרא ע' רסב ואילך. ד\"ה ואל משה אמר וד\"ה וראיתי אני תרל\"ט. סה\"מ תרס\"ב ע' שנ ואילך. תרפ\"ה ע' שלד ואילך. תרצ\"ט ע' 209 ואילך. תש\"ח ס\"ע 279 ואילך."]]],[2000510236,"ה' איש מלחמה, וכיון שהוא בחי' מלחמה א\"כ אין זה מנוחה, וזהו כביכול עומד, אבל כשעברו ישראל בים ואמרו שירה נתיישבה כסאך, לפי שאז לא הי' צריך למלחמה אלא שממילא בטלו וכמ\"ש שמעו עמים ירגזון כו' תפול עליהם כו', ולא הי' צריך למלחמה והי' בחי' מנוחה הוא בחי' ישיבה כו'.\n<b>ולהבין</b> ענין המלחמה איך שייך לומר בחי' מלחמה וכמ\"ש מלחמה לה' בעמלק, וכן מ\"ש הוי' איש מלחמה איך שייך למעלה בחי' מלחמה כו'. הענין הוא דהנה כתי' וידעו מצרים כי אני הוי' וארז\"ל מאני של בשר ודם אתה למד אני של הקב\"ה<sup data-n=\"641\">40</sup>, פרעה אמר אני פרעה זכה יוסף לגדולה, לכשיתגלה אני של הקב\"ה עאכו\"כ כו'. והענין הוא דהנה פרעה אמר לא ידעתי את הוי', דהנה כתי' רם על כל גוים הוי' על השמים כבודו, שאוה\"ע אומרים<sup data-n=\"642\">41</sup> שהוא רם בבחי' רוממות ולכן על השמים כבודו שהם בחי' שכלים נבדלים, אבל למטה בארץ הנה עזב ה' את הארץ לפי שהוא השפלה נגדו ית', ולכן אומרים עזב ה' את הארץ בידי המזלות כו', אבל ישראל אומרים המגביהי לשבת המשפילי לראות בשמים ובארץ, לפי שגם השמים הוא בחי' השפלה נגדו ית', וכמו שהוא יכול להשפיל א\"ע בשמים כן יכול להשפיל א\"ע בארץ, ששמים וארץ הם שוין לפניו ית'. וזהו וידעו מצרים כי אני הוי', והיינו לפי שפרעה הוא בחי' עורף ומקבל ממקום גבוה שהוא בחי' עורף דא\"א<sup data-n=\"643\">42</sup>, שהוא בחי' רם דהיינו שמקבלים מבחי' רוממות כו' ששם כחשיכה כאורה כו'. ועוד שהם מקבלים מבחי' הצמצום דשם אלקים, אבל מבחי' הוי' אינם יכולים לקבל, לפי שכדי לקבל משם הוי' צריך שיהי' בחי' ביטול, לכן אמר פרעה לא ידעתי את הוי' ולא הי' רוצה לקבל משם הוי', וז\"ע מלחמה להוי'. וזהו וידעו מצרים כי אני הוי', והיינו שאני קאי על בחי' מל' אני ראשון ואני אחרון, ואני והוי' כולא חד כו'. וגם י\"ל אני ה' קאי על אני ראשון שהוא בחי' כתר<sup data-n=\"644\">43</sup>, ואני והוי' כולא חד, והיינו כי שניהם אמת כי הוי' הוא מחבר בין ב' בחי' אני ראשון ואני אחרון, וכמ\"ש לע\"ל ראו עתה כי אני אני הוא שיתחברו ב' בחי' אני כו', וזהו מ\"ש הוי' שמו, שמו הוא בחי' משארז\"ל בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, והוי' הוא כולא חד כו'. וזהו וידעו מצרים כי אני הוי' שכולא חד, לא כמו שהם אומרים רם על כל גוים הוי' שמקבלים מבחי' רוממות או משם אלקים בחי' צמצום, אלא אני הוי' שכולא חד ממש. וז\"ע המלחמה לה', ה' איש מלחמה, וכן מלחמה לה' בעמלק, כי עמלק הוא בגימ' רם<sup data-n=\"645\">44</sup> שמפני שהוא רוצה לקבל מבחי' רם כו', ולא מבחי' שם הוי' כי חלק הוי' עמו דוקא, וזהו מלחמה לה' משם אורידך נאום הוי' כו'.",[["641","40","<b>מאני של בו\"ד אתה למד אני של הקב\"ה</b>: בהבא לקמן עד סוף הפיסקא ראה לקו\"ת שלח מח, א."],["642","41","<b>רם על כל גוים הוי'. . שאוה\"ע אומרים</b>: ראה בארוכה תו\"א מקץ לד, ד. וראה גם סה\"מ תרכ\"ז ע' קעא. וש\"נ. תרכ\"ט ע' רצב. ועוד."],["643","42","<b>שפרעה הוא בחי' עורף. . עורף דא\"א</b>: ראה סידור עם דא\"ח רצד, ג. ובכ\"מ."],["644","43","<b>שאני. . בחי' מל' אני ראשון. . בחי' כתר</b>: ראה לקו\"ת שלח מז, ד. ובכ\"מ."],["645","44","<b>עמלק הוא בגימ' רם</b>: ראה גם אוה\"ת תצוה ע' א'תרחצ. נ\"ך ע' ריד. ועוד."]]],[2000510237,"<b>והנה</b> קודם קרי\"ס שהי' מלחמה להוי' לכן אינו מנוחה עדיין, אבל בקי\"ס שנא' וידעו מצרים כי אני הוי' וא\"צ למלחמה כי ממילא בטלו לכן נתיישבה מלכותך. וז\"ע עשינוך אגוסטוס הוא מלך המלכים שאין צריך למלחמה לפי שכשנמשכה המשכה מלמעלה מהשתל' בבחי' שם הוי' אז אין צריך למלחמה כלל כי ממילא מתבטלים כו' וכמ\"ש שמעו עמים ירגזון כו'. וזהו ע\"ד ההפרש שבין דוד לשלמה<sup data-n=\"646\">45</sup> כי דוד הי' איש מלחמה שכל ימיו הי' צריך למלחמה ולהכניע שונאיו ולא הי' לו מנוחה, ולכך לא בנה את בהמ\"ק, אבל שלמה נק' איש מנוחה לפי שלא הי' צריך למלחמה כלל כי כל העמים היו בטלים אליו והיו באים לשמוע חכמתו לכך נק' איש מנוחה. ועד\"ז הי' ענין קרי\"ס שכולם בטלו ממש ולא הי' צריך ללחום כלל, ולכך ע\"י קרי\"ס נתיישבה מלכותך בחי' ישיבה, אגוסטוס יושב, לפי שבקי\"ס הי' הגילוי בחי' אז אל\"ף בזיי\"ן שהוא בחי' א\"א לכן א\"צ למלחמה כלל, כי המלחמה הוא רק בשם הוי' שהוא בחי' ז\"א כו', אבל למעלה בא\"א אין שייך מלחמה כי ממילא הם בטלים כו', וע\"ד שיהי' לע\"ל שנא' אז אהפוך כו' לקרוא כולם בשם הוי' כו' שכל העמים יהיו בטלים לנש\"י, והיינו לפי שיהי' הגילוי מבחי' אז ויתהפכו כולם, ועד\"ז הי' בקי\"ס ע\"י שאמרו אז כו', וזהו נכון כסאך מאז כו'.\n<b>וזהו</b> סיום המדרש מה כבוד יש בין מלך לאוגוסטוס, ופי' מה כבוד דהנה יש שני בחי' כבוד, וכמ\"ש מלא כל הארץ כבודו וכתי' איה מקום כבודו, והיינו שיש שני בחי' כבוד, בחי' כבוד תתאה ובחי' כבוד עילאה<sup data-n=\"647\">46</sup>, כי כבוד הוא בגימט' ל\"ב והיינו בחי' ל\"ב נתיבות חכ', ויש ב' בחי' כבוד היינו כבוד תתאה הוא בחי' ל\"ב פעמים אלקי' שבמע\"ב שזהו כבוד מלך, והיינו שהכבוד הוא מבחי' ביטול היש לאין שזהו ג\"כ בחי' כבוד בחי' ביטול של הנבראי' שזהו בחי' כבוד מלך, ובחי' כבוד זה מלא כל הארץ כבודו שהוא בחי' עומד, אבל כבוד עילאה הוא בחי' ל\"ב נתיבות חכ' כו' ז\"ע אגוסטוס יושב. וזהו מ\"ש שאו שערים כו' ויבא מלך הכבוד מי זה מלך הכבוד ה' עזוז וגבור כו' ואח\"כ כתי' שאו שערים<sup data-n=\"648\">47</sup> כו' מי הוא זה מלך הכבוד ה' צבאות הוא מלך הכבוד כו', והיינו שמתחלה קאי על כבוד תתאה, ומלך הוא בחי' ז\"א שמלובש בבחי' ל\"ב פעמים אלקי' שבמע\"ב שזהו ה' גבור מלחמה שבזה שייך עדיין מלחמה. ואח\"כ מיירי בבחי' כבוד עילאה, וזהו מי הוא זה מלך הכבוד הוי' צבאות הוא מלך הכבוד כו' ולא כתי' גבור מלחמה, לפי שזה מיירי בבחי' כבוד עילאה ל\"ב נתיבות חכ' ומלך הכבוד הוא בחי' א\"א שמלובש בל\"ב נתיבות חכ' שבזה לא שייך מלחמה כי ממילא הם בטלים, וזהו אגוסטוס יושב לפי ששם אין שייך מלחמה והוא בחי' מנוחה וזהו נכון כסאך מאז כו'.",[["646","45","<b>ההפרש שבין דוד לשלמה</b>: ראה סה\"מ תרנ\"ט ע' קסד. ועוד."],["647","46","<b>שני בחי' כבוד. . כבוד תתאה ובחי' כבוד עילאה</b>: ראה לקו\"ת שה\"ש מז, ב ואילך. סידור עם דא\"ח קכח, ד ואילך. ס' מאמרי אדהאמ\"צ דרושי-חתונה ח\"א ע' א [ובהמ\"מ בתחלת המאמר שם]. סה\"מ תרל\"ג ח\"א ע' יב. פר\"ת ס\"ע שז ואילך. תרפ\"ו ע' צא ואילך. תרצ\"ט ס\"ע 249 ואילך. ועוד."],["648","47","<b>שאו שערים. . ואח\"כ כתי' שאו שערים</b>: ראה בכ\"ז ביהל אור להצ\"צ עה\"פ ע' צ-צא. ובאוה\"ת דברים (כרך ד) ע' א'תתקמה."]]],[2000510238,"<b>ועוי\"ל</b> שההפרש בין כבוד מלך לכבוד אגוסטוס, שהמלך עומד על הלוח ואגוסטוס יושב, דהנה כשהמלך עומד אזי אין ניכר מי הוא המלך, כיון שגם הוא עומד ונמצא שאין יודעים מי המלך, אבל אגוסטוס יושב הוא ניכר וידוע לכל מי הוא המלך לפי שכולם עומדים והוא יושב, שישיבה מורה על רוממות המלוכה. ועד\"ז יובן למעלה שמתחלה הי' רק בחי' עומד ואח\"כ יושב, והענין הוא דהנה יש שני בחי' השפעה<sup data-n=\"649\">48</sup>, בחי' השפעה שמחדש בכל יום תמיד מעשה בראשית כו' שתמיד נתחדש מע\"ב בכל רגע, ואעפ\"כ אינו ניכר ההשפעה וחידוש זה לפי שהחידוש הוא רק על אופן א' ממש, והוא בחי' טבע עולם כמנהגו נוהג, ולכן נק' עומד וכמו למשל מלך עומד שאינו ניכר מהמלך מי הוא, אבל ע\"י קי\"ס שהי' גילוי אותות ומופתים זהו בחי' אגוסטוס יושב שהכל יודעין מי הוא המלך, ולכך ע\"י קרי\"ס שהי' גילוי אותות ומופתים נתיישבה מלכותך שההשפעה זו ניכרת לכל וד\"ל.",[["649","48","<b>שני בחי' השפעה. . שמחדש בכי\"ת מע\"ב</b>: ראה אוה\"ת בשלח (כרך ז) ע' ב'תרעא. סה\"מ תרכ\"ט ע' קפז ואילך. וש\"נ. קצה. ועוד."]]],[2000510239,"<h3>וכל העם רואים</h3>\n<b>בס\"ד.</b>\n<b>וכל</b> העם רואים<sup data-n=\"650\">1</sup> את הקולות ואת הלפידי' ואת קול השופר וגו' וירא העם וינועו ויעמדו מרחוק. ולכאו' יפלא מה\"ע הקולות האלו<sup data-n=\"651\">2</sup>, הלא הדבורי' והציווים אשר נצטוו במ\"ת הם דברי' פשוטי' מאד, כמו לא תרצח לא תענה ברעך עד שקר, שהם דברי' פשוטי' שגם אם לא היינו נצטוי' עליהם הנה גם ע\"פ היושר ראוי לקיימם ולנהוג כן, וכמארז\"ל ערובין דף ק' סע\"ב אלמלא לא ניתנה תורה היינו למדים צניעות מחתול, וגזל מנמלה, ועריות מיונה, נמצא שגם הבעלי חיים נזהרי' בדברי' כאלו גם בלתי ציווי כו', זולת למיניהם שנא' ביצירתם, וצניעות",[["650","1","<b>וכל העם רואים</b>: תוכן המאמר נמצא בקיצור ובשינויים בד\"ה זה בסה\"מ תרכ\"ט ע' ריז ואילך. [וראה גם שם ע' ריב ואילך]. המיוסד (כנראה) על ד\"ה וידבר גו' אנכי להצ\"צ בכת\"י.\nחלק מהמאמר נמצא בשינויים: לקמן בד\"ה זכרוניכם משלי [וראה בהנסמן שם בתחילת המאמר]. ובד\"ה זכור גו' עמלק: בסה\"מ תרל\"ב ח\"א ע' קטז ואילך. וע' רנ-נא. תרנ\"ד ע' קצא ואילך. תרס\"ה ע' רכ ואילך.\nתוכן המאמר נמצא בשינויים והוספות וכו' בד\"ה זה: בסה\"מ תרמ\"ד ע' רכד [שם נמצא רק ההתחלה]. תרס\"ב ע' רסד ואילך. תרע\"ח ע' קסד ואילך. ד\"ה זה תרפ\"ב. ד\"ה לריח שמניך בסה\"מ תרפ\"ג ע' קצו ואילך. המשך חג השבועות תרצ\"ד ותש\"ו (סה\"מ תש\"ו ע' 94 ואילך). ד\"ה וידבר גו' אנכי בסה\"מ תשי\"ד ע' 130 ואילך. ד\"ה קדש ישראל בסה\"מ תשח\"י ע' 490 ואילך. ד\"ה וכל העם בסה\"מ תשד\"מ (הוצאת תשס\"ב) ע' 302. וראה גם סה\"מ תרל\"ב ח\"א ע' ז. וע' קפב-ג. תרמ\"ח ע' קצ ואילך."],["651","2","<b>מה\"ע הקולות האלו הלא. . הם דברים פשוטים מאד</b>: ראה עד\"ז לקו\"ת במדבר יב, ג. מאמרי אדה\"ז תקס\"ב ח\"א ע' רה-ו. שם ח\"ב ע' תמה. אוה\"ת דרושים לחג השבועות ע' קנז. [ובדרושים שנסמנו לעיל בתחילת המאמר]."]]],[2000510240,"וגזל לא נצטוו כלל, ונמצא כי מהראוי הי' לאדם שהוא נברא בעל שכל ומשכיל על דבר לקיים מדעתא דנפשי' ליזהר בדברי' הנ\"ל וכ\"ש ללמוד מנבראי' הנ\"ל. ואם כי י\"ל שלכן נצטוינו בעשרת הדברות בדברי' אלו להיות כי גדול המצווה ועושה ממי שאינו מצווה, ולהיות כי חיבב הקב\"ה את ישראל לכן ציום גם על דברי' פשוטי' בכדי להרבות להם שכר. מ\"מ אינו מהראוי להרעיש כ\"כ בקולות וברקי' וענן כבד, להיותם דברי' פשוטי' שמראוי לנהוג כן גם בלתי ציווי כו'. וכאשר נבין דבר זה נבין ג\"כ משארז\"ל בילקוט שכאו\"א מישראל הי' אומר עמי הדבור מדבר, שנדמה לכל אחד שהבורא דבר אתו בפרט, ולכן אמר אנכי הוי' אלקיך ל' יחיד, ולא אלקיכם ל' רבי' כמ\"ש בכל התורה, בכדי שכל או\"א יסבור שעמו הדבור מדבר.\n<b>והענין</b> יובן בהקדם ענין כל חידוש מ\"ת מהו, הלא ארז\"ל קיים אברהם כל התורה כולה עד שלא ניתנה וא\"כ מהו החידוש במ\"ת<sup data-n=\"652\">3</sup>, ומה נתוסף בנתינתה הלא אברהם קיימה עד שלא ניתנה כו'. אך הענין הוא דהנה ארז\"ל ע\"פ לריח שמניך טובים שמן תורק שמך, כל המצות שעשו האבות ריחות היו אבל אנו שמן תורק שמך דבר שמריקי' מכלי אל כלי, פי' כי ענין הריח הוא אינו עצם הדבר<sup data-n=\"653\">4</sup> שהרי יכול להריח כל היום וכל הלילה ואעפ\"כ לא יחסר מאומה ע\"י הריח שמריח, ונמצא כי זהו הוראה שלא יש בקבלתו שום עצמיות כלל שהרי איננו חסר כלל, אבל אנו שמן תורק שמך דבר שמריקי' מכלי אל כלי הוא עצם הדבר כמו שהוא. והיינו כי מה שקיים אברהם כל התורה הוא ע\"י עבודתו ברצוא ושוב<sup data-n=\"654\">5</sup>, וקיים כל הענינים ברוחניות<sup data-n=\"655\">6</sup>, שהרי לא הי' אפשר לו לקיים מצות תפילין עד\"מ לכתוב פ' קדש שכתוב בה סיפור ענין יצ\"מ, שעדיין לא הי' ענין שעבוד מצרי', וכמו\"כ ענין הציווי שבפ' והי' אם שמוע תשמעו אל מצותי שעדיין לא ניתנו המצות כלל, אלא שקיים כל המצות ברוחניות הענינים, וע\"י עבודתו בגמ\"ח להאכיל ולהשקות לכל העוברי' ושבי' ואמר להם אח\"כ ברכו למי שאכלתם משלו והודיע אלקותו ית' בעולם, וכמו\"כ ע\"י הנסיונות שניסה אותו הקב\"ה ועמד בכולם, ע\"י עבודתו זה הלך ברצוא ושוב מדרגא לדרגא עד שהגיע לבחי' נגבה הוא בחי' החסד שהוא",[["652","3","<b>והענין יובן בהקדם. . קיים אברהם כל התורה. . מהו החידוש במ\"ת</b>: ראה בכ\"ז תו\"א יתרו סו, סע\"ד ואילך. סז, ד ואילך. עג, סע\"ג ואילך. מג\"א צו, ג ואילך. ועוד. [וראה אוה\"ת יתרו ע' א'ט-י שמביא ג' שיטות בזה מדרושי אדה\"ז. עיי\"ש]. בהבא לקמן ראה בארוכה [נוסף להדרושים שנסמנו לעיל בתחילת המאמר] מאמרי אדה\"ז תקס\"ב ח\"א ע' יא ואילך. מארז\"ל ע' קז ואילך. מאמרי אדהאמ\"צ שמות ח\"א ע' רנז ואילך. אוה\"ת תשא ע' א'תתקסו ואילך. אוה\"ת ראה ע' תשנד ואילך. סה\"מ תרכ\"ז ע' קס ואילך."],["653","4","<b>לריח שמניך. . שמן תורק. . הריח הוא אינו עצם הדבר</b>: בכ\"זֶראה גם לקו\"ת שה\"ש ג, א-ב. אוה\"ת שה\"ש (כרך א) ע' ל. ועוד."],["654","5","<b>מה שקיים אברהם כל התורה. . עבודתו ברצוא ושוב</b>: ראה בארוכה תו\"א יתרו שם עג, ד. מג\"א שם צו, ג."],["655","6","<b>וקיים כל הענינים ברוחניות</b>: בכ\"ז ראה גם תו\"א לך לך יא, ד. יתרו סח, א ואילך. לקו\"ת שה\"ש ט, סע\"ב. ובכ\"מ."]]],[2000510241,"שירותא דעלמא עילאה<sup data-n=\"656\">7</sup> כמ\"ש בזהר, להיות כי הנברא ע\"י עבודתו עצמו (בלא תומ\"צ), א\"א לו להגיע יותר נעלה משרשו ומקורו אשר נלקח משם.\n<b>וראי'</b> לזה ממה שארז\"ל ש\"מ מעין עין עיטם<sup data-n=\"657\">8</sup> גבוה מקרקע העזרה ך\"ג אמה, שהרי מקוה של הכה\"ג שהי' בבית הפרוה היתה על הפתח<sup data-n=\"658\">9</sup>, שהפתח הי' עשרים אמה גובהה וג' אמות על מקום המים<sup data-n=\"659\">10</sup>, ואם נאמר שיכולי' להגביה המים גם עוד יותר מהמעיין אשר נובע ממנו א\"כ מנ\"ל שמעין עין עיטם גבוה ך\"ג אמה, אלא בהכרח לומר שא\"א להגבי' קויית המים גבוה יותר מהמקום אשר נלקח משם<sup data-n=\"660\">11</sup>. ומזה נלמוד לכל דבר אשר א\"א שיתעלה ע\"י עבודתו למעלה ממקור שורשו. גם ענין ירידת הנשמה בגוף תוכיח<sup data-n=\"661\">12</sup> שא\"א לעלות כ\"א ע\"י ירידתה שירדה עשר מעלות אחורנית להתלבש בגוף ונה\"ב המעלים ומסתיר על בחי' האהוי\"ר אשר הי' לה קודם ירידתה והתלבשותה בגוף, כמ\"ש חי ה' אשר עמדתי לפניו כו' וכמ\"ש מזה במ\"א באורך<sup data-n=\"662\">13</sup>, והיינו כי כמו פעולת המים שהוא ענין קיבוץ וקיווי המים א\"א להיות גבוה יותר מגובה המעיין עצמו, כן פעולת כל דבר נברא א\"א להיות גבוה יותר משרשו הקדום. ובזה יובן היטיב דקדוק הלשון שאמרו בענין ירידת הנשמה בגוף שהירידה היא צורך עלי', הנה כיוונו לזה באמרם שהירידה דוקא היא צורך עלי',",[["656","7","<b>נגבה הוא בחי' החסד. . שירותא דעלמא עילאה</b>: ראה אוה\"ת יתרו ע' תשעה-ו. סה\"מ תרל\"ג ח\"א ע' רצד. תרנ\"ה ע' פח. תש\"ב ע' 102. וראה גם תו\"א יתרו סו, ד."],["657","8","<b>וראיה לזה ממה שארז\"ל ש\"מ מעין עין עיטם</b>: בהבא לקמן ראה [נוסף להדרושים שנסמנו לעיל בתחילת המאמר] מאמרי אדה\"ז הקצרים ע' ב. על מארז\"ל ע' רד [בשם הע\"ח]. מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'לג. סה\"מ תרכ\"ט ע' ריא. תרס\"ה ע' ז. רכא. תרפ\"ט ע' 269 ואילך. תש\"ג ע' 23."],["658","9","<b>מקוה של הכה\"ג שהי' בבית הפרוה היתה על הפתח</b>: מש\"כ כאן ”בבית הפרוה\" ראה ד\"ה זה תרס\"ב בהגה\"ה: צ\"ע, וע' בפרש\"י ביומא דל\"א ע\"א דהיינו בהמקוה שהייתה ע\"ג שער המים, ועי' שם בתוס' ד\"ה וכולן. ע\"כ. — ראה יומא לא, א: חמש טבילות כו' טובל כהן גדול כו' בו ביום וכולן בקודש בבית הפרוה, חוץ מראשונה שהיתה בחול על גבי שער המים כו', אמר אביי שמע מיניה עין עיטם גבוה מקרקע עזרה כ\"ג אמות. ובפירש\"י ד\"ה עין עיטם: עין עיטם ממנו באה אמת המים לבית טבילת שער המים שעל החומה. ובתוס' ד\"ה וכולן שם גורס בגמ': וכולן בקודש בגג בית הפרוה [אלא שהתוס' ס\"ל ש”גג בית הפרוה היה שוה לקרקע העזרה\"]. וכנראה שבמאמר כאן קאי עפ\"י הגירסא שהובאה בתוס' שהמקוה שבבית הפרוה היתה בגג בית הפרוה, אך מ\"מ ס\"ל שגג בית הפרוה היה גבוה מקרקע העזרה. [ולהעיר שברוב הדרושים שנסמנו לעיל בתחילת המאמר (ד\"ה וכל העם תרכ\"ט תרע\"ח, וכו' וד\"ה זכור גו' תרל\"ב ועוד) הלשון הוא ”המקוה של כה\"ג הי' ע\"ג הפתח\" ולא נכתב שם שהי' ע\"ג בית הפרוה. אך בסה\"מ תש\"ו ע' 96 מביא מפירש\"י שם שהי' ע\"ג שער המים]."],["659","10","<b>וג' אמות על מקום המים</b>: בד\"ה זה תרע\"ח מוסיף: שיעור מקוה הוא אמה על אמה ברום ג' אמות. [וראה יומא לא, סע\"א שם. ובתוס' ד\"ה אמה]."],["660","11","<b>שא\"א להגבי' קויית המים גבוה יותר מהמקום אשר נלקח משם</b>: בד\"ה זכור גו' תרנ\"ד שם מעיר ע\"ז: צ\"ל הכוונה דמעצמם א\"א להמים לעלות יותר משרשם, אבל להגביה אותם יכולים גם למעלה כו' כנראה בחוש שמגביהים ע\"י הכלי הנק' פאמפע וכ\"ה בנמשל ג\"כ."],["661","12","<b>גם ענין ירידת הנשמה בגוף תוכיח</b>: ראה בארוכה בד\"ה זה תרע\"ח ע' קסה-ז. סה\"מ תש\"ו שם ע' 96 ואילך."],["662","13","<b>ירידת הנשמה בגוף. . המעלים. . האהוי\"ר. . חי ה' אשר עמדתי לפניו כו' וכמ\"ש מזה במ\"א באורך</b>: ראה תו\"א וישב כט, ב. ל, סע\"א ואילך. בשלח סב, סע\"ד ואילך. לקו\"ת שלח לח, ד. סה\"מ תרל\"ב ח\"א ע' קעז-ח. תרל\"ג ח\"א ע' רלג ואילך. ועוד."]]],[2000510242,"ולא כשהיתה עומדת באהוי\"ר בהיותה באוצר הנשמות למעלה כו'. ולזה יובן ג\"כ בענין עבודת אברהם שהי' עובד בלתי ציווי כ\"א מעצמו, לא הי' ביכולתו להגיע למעלה יותר משרשו כו'. ולכן ארז\"ל ריחות היו והיינו שכמו הריח הוא רק הארה מעצם הדבר ולא ממשו של הדבר, כן עבודת הנברא מצד עצמו הוא רק ריח פי' הארה בעלמא, מפני כי א\"א להגיע יותר נעלה משרשו, וכל שורש הנבראי' הוא רק הארה בעלמא, בהבראם בה\"א בראם<sup data-n=\"663\">14</sup> בחי' אתא קלילא דלית בי' מששא, והגם כי האבות היו נשמות דאצי' מ\"מ ירדו דרך הבריאה, ואברהם אברהם פסיק טעמא, שנת' בת\"א<sup data-n=\"664\">15</sup> שאברהם שלמטה אינו כמו אברהם שלמעלה, ולכן לא הי' יכול להגיע ע\"י עבודתו כ\"א לשורשו כו'.\n<b>אך</b> הנה צ\"ל הלא האבות הן הן המרכבה, וא\"כ אברהם הי' מרכבה לבחי' החסד<sup data-n=\"e54\">ב</sup> דאצי', שנודע שאצי' הוא בחי' אלקות כו'. אך הענין דבאמת שורש התהוות העולמות הוא מבחי' המדות וכמ\"ש כי אמרתי עולם חסד יבנה, וכתי' זכור רחמיך<sup data-n=\"665\">16</sup> וחסדיך כי מעולם המה, שבחי' המדות רחמי' וחסדי' שייכי' לעולמות כו', ולכן עם כי האבות הן הן המרכבה כו', עכ\"ז הוא רק לבחי' שורש ומקור ההתהוות כו'. ועדיין צ\"ל הלא נשמת אברהם ירדה להתלבש בגוף, וע\"י ירידתה היא צריכה לבוא למעלה משורש מקור חוצבה. אך הענין דעיקר ענין העלי' שע\"י ירידת הנשמה בגוף זהו מחמת קיום התומ\"צ<sup data-n=\"666\">17</sup> שזה א\"א כ\"א ע\"י ירידת הנשמה בגוף גשמי לקיים התומ\"צ בגשמי', אבל ע\"י הירידה לבד אינו שייך כלל שתעלה עי\"ז, כי אם שאי אפשר לקיים התומ\"צ בגשמיות כ\"א ע\"י שתתלבש הנשמה בגוף, ונמצא כי אברהם כשלא נצטוה על קיום המצות הגם כי ירדה נשמתו להתלבש בגוף לא הגיע בעבודתו כ\"א לגילוי שם שדי, שנת' במ\"א ע\"פ המדרש שדי באלקותו לכל ברי',",[["663","14","<b>א\"א להגיע יותר נעלה משרשו. . בהבראם בה\"א בראם</b>: בד\"ה זה תרס\"ב שם מוסיף כאן: ובהבראם אותיות באברהם כמ\"ש במד\"ר בראשית פי\"ב, שגם אברהם הגיע בעבודתו לבחי' בה\"א בראם לבד כו'."],["664","15","<b>ואברהם אברהם פסיק טעמא שנת' בת\"א</b>: פ' משפטים עה, ג. וראה בארוכה סה\"מ תר\"ל ע' נו-ז. תש\"ב ע' 84 ואילך. ועוד."],["665","16","<b>התהוות העולמות. . מבחי' המדות. . חסד יבנה. ֿ. זכור רחמיך</b>: בכ\"ז ראה בארוכה סה\"מ תרל\"ב ח\"א ע' צ. וש\"נ. תרל\"ג ח\"ב ע' תקמ ואילך. וש\"נ. תרל\"ד ע' נב ואילך."],["666","17","<b>דעיקר ענין העלי'. . זהו מחמת קיום התומ\"צ</b>: בד\"ה זה תרס\"ב מוסיף: עליית הנשמה שנעשה ע\"י הירידה בגוף היא בב' אופנים, הא' כשהגוף והנה\"ב מעלימים ומסתירים על הנה\"א ומונעים אותו בדרכי עבודתו עי\"ז נעשה תוקף הרצוא בנה\"א כו' [עיי\"ש הביאור בזה בארוכה], והאופן הב' בעליית הנשמה ע\"י ההתלבשות בגוף הוא ע\"י קיום התומ\"צ בגשמיות [כדלקמן בפנים]. וראה עד\"ז בד\"ה זה בסה\"מ תרע\"ח שם ע' קסז-ח. סה\"מ תש\"ו שם ע' 104 ואילך.\n\n<b>ב</b>  <b>אך הנה צ\"ל. . אברהם הי' מרכבה לבחי' החסד. ֿ. חסד יבנה</b>: בשולי הגליון נרשם בגוכי\"ק: מרכבה חג\"ת, גם חג\"ת שורש הנבראים חסד יבנה, ומה שגם אברהם ירד להתלבש בגוף, צ\"ל שהעלי' היא לא ע\"י הירידה לבד כ\"א ע\"י קיום התומ\"צ שא\"א באופן אחר, מ\"מ כל זמן שלא נצטוו אי אפשר."]]],[2000510243,"היינו שמבחי' זו יכול להיות גם נס<sup data-n=\"667\">18</sup>, אמנם גם הנס מתלבש בדרכי הטבע, שלכן זהו שם שדי מל' שאמר לעולמו די, ל' הגבלה<sup data-n=\"e55\">ג</sup> כו'.\n<b>אבל</b> אנו שמן תורק שמך<sup data-n=\"668\">19</sup> כמו דבר שמריקי' מכלי אל כלי היינו בחי' עצם הדבר. והגם כי רמ\"ח מ\"ע הם ג\"כ רק בחי' רמ\"ח איברין שהם בחי' ז\"א, כנודע שז\"א הוא בעל ט' ספירות, וט' פעמים ט' הם פ\"א, וראש תוך סוף הם רמ\"ג וה' חסדים המגדילי' זהו מספר רמ\"ח. י\"ל שזהו רק מה שהמצות נק' כלי' שהוא בחי' הכלי שבה יומשך האור שע\"י המצות, והאורות הוא מבחי' תר\"ך עמודי אור, שתרי\"ג מצות דאורייתא וז' מצות דרבנן הם תר\"ך עמודי אור. וגם שענין מצות ל\"ת שרשם בי\"ה כמ\"ש במ\"א<sup data-n=\"669\">20</sup>. ונמצא כי ע\"י ירידת הנשמה בגוף בכדי לקיים התומ\"צ כמו שהם נתלבשו בדברי' גשמי', ציצית בצמר גשמי, ותפילין בקלף גשמי, וד' מינים שבלולב בצמחי' הגשמי', ועד\"ז כל בחי' פרטי המצות, שזהו א\"א לקיים כ\"א כאשר תתלבש הנשמה בגוף הגשמי דוקא עי\"ז ממשיכי' מבחי' הגבוה יותר כו'. וזהו שמן תורק המשיל ענין ההמשכה שע\"י המצות לשמן, והיינו כי השמן רומז לבחי' חכ', והוא גם על בחי' הנעלמה שהוא בחי' ח\"ס, ולכן כתי' שמן משחת קדש שהשמן מושח את הקדש<sup data-n=\"670\">21</sup>, להיותו בחי' חכ' הנעלמה ח\"ס לכן יכול למשוח את הקדש בחי' חכמה דאצי'. וכמו\"כ על מעשה המצות שנמשלו לשמן אנו מברכים אשר קדשנו במצותיו וצונו, פי' שע\"י עשיית המצות נתקדשנו ג\"כ, וכמ\"ש כי עם קדוש אתה, והתקדשתם והייתם קדושי', קדושי' תהיו, שזהו ע\"י המצות, שבהם ועל ידם נתקדשנו ג\"כ כו', והיינו כמו השמן שמושח את הקדש, וכח זה ניתן במ\"ת דוקא.\n<b>אבל</b> האבות שקיימו התורה הנה זהו ע\"י עבודתם במס\"נ כל אחד לפי מדריגתו, אברהם הי' מרכבה לבחי' החסד דאצי' ולכן אמרה מדת החסד כל ימי היות אברם בארץ לא הוצרכתי אני לעשות מלאכתי שנא' וישמור משמרתי, כמ\"ש בפרד\"ס בשם ספר הבהיר, ויצחק ע\"י חפירות בארות שהו\"ע ההעלאות מלמטלמ\"ע, וכ\"ז בכח מס\"נ וכענין העקידה כו', ויעקב עבד בענינים אחרים וכמ\"ש בזהר",[["667","18","<b>שנת' במ\"א ע\"פ המדרש שדי באלקותו. . יכול להיות גם נס</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' צז. תר\"ל ע' סב. וע' רסז. תרל\"ה ח\"א ע' מג. וש\"נ. סה\"מ מלוקט ח\"ה ע' קלט ואילך. וש\"נ. לקמן ד\"ה זאת חוקת. וש\"נ."],["668","19","<b>אבל אנו שמן תורק שמך</b>: בשולי הגליון נרשם בגוכי\"ק: רק ריח, אבל אנו שמן תורק."],["669","20","<b>שענין מצות ל\"ת שרשם בי\"ה כמ\"ש במ\"א</b>: ראה לקו\"ת פקודי ג, ב ואילך. סה\"מ תרל\"ד ע' פא-ב. וש\"נ. סה\"מ תר\"ם ח\"א ע' רט ואילך. ועוד."],["670","21","<b>שמן משחת קדש שהשמן מושח את הקדש</b>: ראה בארוכה לקו\"ת בהעלותך ל, סע\"ג-ד. לא, א. קרח נד, ד. ובכ\"מ.\n\n<b>ג</b>  <b>גם הנס מתלבש בדרכי הטבע שלכן זהו שם שדי. . ל' הגבלה</b>: בגוכי\"ק נוסף כאן (ואח\"כ נרשם ע\"ז שא\"צ להעתיקו): אך ענין אשר ניצול מאור כשדים לכאו' זהו יוצא מדרכי הטבע לגמרי, וצ\"ע."]]],[2000510244,"שהמקלות הי' כענין התפילין. והשינויים שלהם בעבודתם הנה זה גופא יורה שההמשכה שלהם הי' באופן אחר מההמשכה שלנו, שהרי כל אחד שינה מעשיו לפי שרשו ומקורו. אבל מאחר שניתנה תורה הרי כולם שוין בקיום המצות<sup data-n=\"671\">22</sup>, כמו שמאי שהי' מבחי' הגבורה והלל הי' מבחי' החסד ומ\"מ שניהם שוים בקיום המצות<sup data-n=\"672\">23</sup>, ולא כמו אברהם ויצחק שהיו חלוקי' במדריגתם, שזה הי' מרכבה למדת החסד וזה למדת הגבורה, היו חלוקי' בעבודתם כו', והיינו כי הם קיימו כל התורה עד שלא ניתנה הנה קיימו זה ע\"י עבודתם במס\"נ, שלכן חלוקי' הם במעשיהם אברהם בגמ\"ח והכנסת אורחי' ויצחק הי' חופר בארות, אבל מאחר שניתנה תורה הרי יד כולם שוה.\n<b>ומה</b> שנתלבשה התורה בדברי' גשמי' הנה זה יורה על רוממות ההמשכה, שדוקא מבחי' היותר גבוה ביכולתו לירד מטה מטה דוקא<sup data-n=\"673\">24</sup>, וכמו אותיות כשחוקקים על האבן הטוב, הנה מחמת רוב בהירות האבן טוב א\"א לקרות האותיות כמו שהם חקוקי' בהאבן, כ\"א כשחותמי' אותם בשעוה אז יכולי' לקרות האותיות, והיינו כמו שמתרחקי' מהמקור, כן לעוצם מעלת גובה ההמשכה שע\"י המצות א\"א כ\"א שתתלבש בדבר גשמי שרחוק בערך במהות אחר לגמרי כו'.\n<b>ויובן</b> זה ממה שאנו רואי' גם בכוחות שבנפש המוגבלי' לגמרי מ\"מ חלוקי' הם בהתלבשותם, והוא מענין ההפרש בין ראי' לשמיעה<sup data-n=\"674\">25</sup>, שהראי' תופס דבר גשמי כמו עץ ואבן, והשמיעה אינה תופסת דבר גשמי כ\"א רוחני<sup data-n=\"675\">26</sup>, כענין הקול שיוצא מהבל הלב או מכלי זמר. ולכאו' יפלא הלא ראי' הוא כח היותר נעלה משמיעה, שהרי אינו דומה שמיעה לראי', והיינו שראי' הוא בחי' הנחה בנפש בבחי' היותר נעלה, שהרי כשישמע האדם בהפלגת איזה דבר ויצייר בנפשו היטיב ענין ציור הדבר ששמע עד שמבין היטיב, מ\"מ כשיראה הדבר ההוא אח\"כ יתפעל ביותר מכמו אשר צייר הדבר ששמע, שלזה כיוונו באמרם שאינו דומה שמיעה לראי', והיינו שהגם שע\"י השמיעה נצטייר בנפשו דבר ההוא, מ\"מ ההנחה שעושה בנפשו על הדבר שראה בראי' חושיית היא יותר נעלה בערך מכמו מה שנתצטייר אצלו ע\"י השמיעה ששמע, אשר זה יורה ומובן לכל אשר ראי' הוא כח היותר נעלה, וכנודע מספרי חכמי האמת שראי' רומז לבחי' החכ' ושמיעה על בחי' הבינה, ומ\"מ בענין פעולתם הנה השמיעה תופס הקול שהוא רוחני, והראי' דבר",[["671","22","<b>האבות. . כל אחד לפי מדריגתו. . אבל מאחר שניתנה תורה הרי כולם שוין בקיום המצות</b>: ראה ד\"ה זה תרע\"ח: שהאבות היו מחולקים בעבודתם כ\"א לפי שרשו ומקורו כו', והיינו מפני שעבודתם הי' להגיע לשרשם ומקורם, ע\"כ כפי אופן שרשם כן הי' עבודתם כו', אבל אחר שניתנו תומ\"צ במ\"ת הרי כולם שוים בקיום המצות כו', והוא מפני שאי\"ז עבודה לפי שרש ומקור הנברא, כ\"א מה שניתן מלמעלה למעלה משרש ומקור הנבראים בחי' המשכת עצמות וע\"כ הכל שוים בזה כו'."],["672","23","<b>שמאי. . מבחי' הגבורה והלל. . מבחי' החסד ומ\"מ שניהם שוים בקיום המצות</b>: בד\"ה זכור גו' תרנ\"ד מעיר ע\"ז: מצד הכוונה פרטית י\"ל דבאמת היו חלוקים לפי אופן מדריגתם לפי שרשן ומקורן, אבל אין זה עיקר המצוה כ\"א העשי', ומצד כח המצווה כו' ובזה כולם שוים כו'."],["673","24","<b>שדוקא מבחי' היותר גבוה ביכולתו לירד מטה מטה דוקא</b>: ראה לקו\"ת שה\"ש כג, א. מאמרי אדה\"ז תקס\"ד ע' קכו. סידור עם דא\"ח עא, ד. שא, ג. תו\"ח ויצא כג, ד. ובארוכה שערי אורה שער הפורים כח, א-ב. שם פה, א ואילך. אוה\"ת וארא ע' קסב ואילך. וע' ריד."],["674","25","<b>ויובן זה. . מענין ההפרש בין ראי' לשמיעה</b>: בהבא לקמן ראה סה\"מ תרכ\"ח ע' יב ואילך. המשך וככה תרל\"ז פל\"ג (ע' מד-ה). פנ\"ז (ע' פו-ז). לקמן המשך והחרים."],["675","26","<b>שהראי' תופס דבר גשמי. . והשמיעה. . רוחני</b>: ראה גם תו\"א וירא טו, ד. לקו\"ת הוספות לס' ויקרא נד, ג. [ובמקומות שנסמנו בהע' שלפנ\"ז]."]]],[2000510245,"גשמי כעץ ואבן, שלכאו' הי' צ\"ל בהיפוך. אך הענין שלהיות הראי' הוא כח היותר נעלה בהכרח שתרד להתלבש בדבר היותר נמוך ואז תוכר מעלתה, משא\"כ בענין רוחני כקול א\"א עדיין להכיר בחינתה ומעלתה, כי אין ענין הרוחני כלי להעלים ולהסתיר על גודל בחי' מעלתה<sup data-n=\"676\">27</sup>, ואין זה אמצעות שתתגלה רוחניות כח ראיית העין ע\"י הדבר רוחני כקול, כ\"א כשתרד עוד עד שתתלבש בדבר גשמי אז ניכר מעלתה, והרי אין זה ירידה לבד שהרי ע\"י הירידה ניכר מעלתה שהרי אינה דומה שמיעה לראי'. כן עד\"ז יובן שלעוצם גודל מעלת מעשה המצות א\"א כ\"א שתתלבש בדברי' גשמי' כציצית מצמר הגשמי ותפילין בקלף הגשמי וד' מינים שבלולב בצמחי' הגשמי' דוקא.\n<b>ובזה</b> יובן מה שהשיב הקב\"ה להמלאכי' כשבקשו שתנתן להם התורה, כלום יצה\"ר יש ביניכם<sup data-n=\"677\">28</sup>, שלכאו' אינו מובן התשובה כלל, דאם היו מבקשי' התורה כמו שניתנה בגשמיות הי' נכון התשובה כלום יצה\"ר יש ביניכם, אבל הנה הם בקשו התורה ברוחניות שהרי אינו שייך שילבשו ציצית מצמר ותפילין מקלף גשמי, אלא הכוונה על המצוות כמו שהם ברוחניות ל\"ב חוטי הציצית הם ל\"ב נתיבות חכ', וצמר הציצית הוא בחי' שער רישא, ותפילין הוא בחי' ד' מוחין וכדומה בכל פרטי המצות ומה תשובתו כלום יצה\"ר יש ביניכם. אך הענין הוא כנ\"ל דלעוצם מעלת ומדריגת המצות א\"א להם להתגלות כ\"א בדבר גשמי, ושתרד הנפש להתלבש בגוף ונה\"ב המעלים ומסתיר על אור ה' וקדושתו, ומ\"מ יקיים ציווי כל מצוה כתיקונה ובפרט במצות הנק' חוקים כפרה אדומה וכדומה, אשר ע\"ז הוא נכון התשובה שהשיב להם כלום יצה\"ר יש ביניכם שתוכלו לקיים המצות כו', ובזה הסיר הקטרוג שלהם והבקשה שבקשו תנה הודך על השמים.\n<b>וכן</b> השיב להם משה למצרים ירדתם כו', והענין דבכדי שיוכלו ישראל לקבל את התורה שנתלבשה בדברי' גשמי' שזה מורה על גודל מעלת ההמשכה כמשנת\"ל זהו ע\"י שעבוד מצרים, שע\"י הגלות והשעבוד נצטרפו ונתלבנו עד",[["676","27","<b>אין ענין הרוחני כלי להעלים ולהסתיר על גודל בחי' מעלתה</b>: בד\"ה זה בסה\"מ תרס\"ב שם ס\"ע רסט מבאר זה: כי כל אור א\"א שיתגלה כ\"א ע\"י איזה לבוש המעלים עליו קצת ועי\"ז דוקא מתגלה, וכמו שכל המתלבש באותיות הדיבור או באותיות הכתב הרי האותיות מעלימים על האור כו' ומ\"מ ע\"י מתגלה השכל כו' כי א\"א לקבל גילוי אור בלי לבוש כלל כו' אמנם כאשר האור הוא נעלה ביותר אין הרוחני לבוש אליו, דרוחני אאפ\"ל לבוש כ\"א לאור שבערכו כו' אבל לאור שאינו בערכו א\"א לרוחני להיות לבוש לזה כי מפני תוקף האור מתבטל הלבוש ואינו שייך שיעלים כו' כ\"א גשמי דוקא יכול להיות לבוש לאור נעלה ביותר כו', ושרש הענין הוא דהנה רוחני הוא בבחי' כלי להאור המתלבש בתוכו וזה א\"א כ\"א בדבר שבערך כו', אבל גשמי אינו בדרך כלי."],["677","28","<b>שהשיב הקב\"ה להמלאכי'. . כלום יצה\"ר יש ביניכם</b>: כ\"ה גם בד\"ה זה תרס\"ב שם. [וראה לקמן בהמשך המאמר: השיב להם משה למצרים ירדתם]. וראה שבת פח, ב: א\"ל הקב\"ה למשה החזיר להן תשובה כו' אמר להן למצרים ירדתם כו' יצה\"ר יש ביניכם."]]],[2000510246,"שיוכלו אח\"כ לקבל התורה<sup data-n=\"678\">29</sup>. וזהו כענין מ\"ש מצרף לכסף כור לזהב<sup data-n=\"679\">30</sup>, פי' כמו שהכסף וזהב הנה בתחלת מציאתם הם מעורבין הכסף וזהב עם הפסולת יחד, ובכדי לעשות מהם כלי צריכי' לנקות תחלה הכסף או הזהב מכל פסולת הנמצא בה עד שתהא ראוי' לעשות ממנה כלי, כן בכדי שיהיו ישראל ראויים לקבלת התורה להיות עם קדוש לה' אלקיך זהו ע\"י אשר נצטרפו ונתלבנו תחלה במצרים עד שנעשו נקי מכל פסולת, ואז אח\"כ בנו\"ן יום קבלו את התורה. ולכן אמר במ\"ת אנכי כו' אשר הוצאתיך מארץ מצרים, ולכאו' יפלא הלא הי' צ\"ל בורא שמים וארץ<sup data-n=\"680\">31</sup> שזהו יותר פלא יחשב ממה שהוציא אותנו ממצרים, שהרי ענין הבריאה נעלם מעין כל חי וכמארז\"ל אלמלא מתכנשין כל באי עולם אינם יכולי' לברוא אפי' כנף יתוש א', וענין יצ\"מ זולת מה שהי' ע\"י אותות ומופתי' הנה מצינו כמה מלכים שנצחו זולתם, והרי לא נא' אשר עשיתי אותות ומופתי' במצרי' כ\"א אשר הוצאתיך מאמ\"צ שדבר כזה מצוי, וכמו מלחמת ל\"א מלכי' שביהושע. אך הענין הוא דכל ענין הבריאה הוא יש מאין לבד, פי' מאין הוא בחי' הארה בעלמא, וגם אין שאינו מושג, ושניהם אמת<sup data-n=\"681\">32</sup>, שגם ההארה שממנה הוא בחי' התהוות כל העולמות<sup data-n=\"682\">33</sup> הוא בחי' רוממות המלוכה, שהיא בחי' הארה ולא מעצמיות ופנימיות הכוחות כמ\"ש מזה במ\"א, הנה גם ההארה זו אינו מושג כלל, כי ענין התהוות הנבראי' צ\"ל בדרך העלם והסתר הבורא מהנברא כמ\"ש בד\"ה מהיכן זכו ובד\"ה מי כמוכה<sup data-n=\"683\">34</sup> באלים באריכות, שאם לא כן הי' בחי' השתלשלות, שזהו ההפרש בין השתלשלות עו\"ע שהעלול משיג מקצת עילתו, ובריאה יש מאין<sup data-n=\"684\">35</sup> אינו מושג כלל מאין נברא, ולשם זה גם אמרו ל' בריאה יש מאין, פי' לבד מה שזהו רק הארה בעלמא אשר לשם זה נק' אין, הנה הוא אינו מושג שזהו נכלל ג\"כ בפי' תיבת אין שאינו מושג כלל. אבל יצ\"מ זהו הקדמה למ\"ת, שע\"י בחי' תומ\"צ נמשך המשכה עצמיות מאלקות, וכמארז\"ל ע\"פ ויקחו לי תרומה אותי אתם לוקחים, פי' אותי היינו אוא\"ס עצומ\"ה ית', שלכן אמר בעת מ\"ת אנכי ה' אלקיך אשר הוצאתיך מאמ\"צ דוקא ולא אשר ברא שמים וארץ, כי בריאת שמים וארץ זהו מהארה בעלמא שאינו נוגע כלל, כי לא בעמל ולא ביגיעה ברא הקב\"ה את עולמו, אמנם ע\"י התומ\"צ נמשך המשכה עצמיות, וכנ\"ל בענין שמן תורק דבר שמריקי' מכלי אל כלי, וכענין אותי אתם לוקחים, וכן ארז\"ל כביכול נמכרתי עמה במד\"ר ר\"פ תרומה פל\"ג, והיינו שנמשך המשכת אוא\"ס ב\"ה המשכה עצמיות כו'.",[["678","29","<b>ע\"י שעבוד מצרים. . נצטרפו ונתלבנו עד שיוכלו אח\"כ לקבל התורה</b>: ראה תו\"א שמות מט, א. נד, סע\"א. וארא נו, ד. [וראה גם תו\"א לך לך יא, ד]."],["679","30","<b>כענין מ\"ש מצרף לכסף כור לזהב</b>: ראה בכ\"ז סה\"מ תר\"ל ע' קיב. תרל\"ב ח\"א ע' צב."],["680","31","<b>אנכי כו' אשר הוצאתיך מארץ מצרים. . הי' צ\"ל בורא שמים וארץ</b>: ראה בכ\"ז לקו\"ת במדבר י, ג. אוה\"ת יתרו ע' תתקה. סה\"מ תרכ\"ו ע' נ. תרכ\"ז ע' רלג-ד. סה\"מ מלוקט ח\"ג ע' קעה ואילך. וש\"נ. סה\"ש תש\"נ ח\"א ע' 286 ואילך. וש\"נ."],["681","32","<b>יש מאין. . פי' מאין. . הארה בעלמא וגם אין שאינו מושג ושניהם אמת</b>: ראה גם אוה\"ת מסעי (כרך ו) ע' א'תתקנט. דרושים לר\"ה ע' א'תא. סה\"מ תרל\"ב ח\"א ע' קה ואילך. ס\"ע עדר. תרל\"ה ח\"ב ע' שצא."],["682","33","<b>ההארה שממנה הוא בחי' התהוות כל העולמות. ֿ. בחי' הארה ולא מעצמיות ופנימיות הכוחות כמ\"ש מזה במ\"א</b>: ראה אוה\"ת מסעי ע' א'תתקנט. סה\"מ תרכ\"ז ע' שסו."],["683","34","<b>בד\"ה מהיכן זכו ובד\"ה מי כמוכה</b>: ד\"ה מהיכן זכו בסה\"מ תרכ\"ז ע' שפז-ח. וד\"ה מי כמוכה בסה\"מ תרכ\"ט ע' קסא ואילך."],["684","35","<b>שזהו ההפרש בין השתלשלות עו\"ע. . ובריאה יש מאין</b>: ראה גם לקו\"ת דרושים לר\"ה נו, סע\"א ואילך. שה\"ש מ, ב. ואילך. ובכ\"מ."]]],[2000510247,"<b>והנה</b> כתי' פנים בפנים דיבר הוי' עמכם כו', פי' ע\"י שדיבר הוי' עמכם במ\"ת עי\"ז נעשה הוי' עמכם, שנעשה שם הוי' בכאו\"א מישראל<sup data-n=\"685\">36</sup>, והיינו כי בעבודה בנפש האדם יש שם הוי', יו\"ד הוא בחי' נקודה<sup data-n=\"686\">37</sup>, הו\"ע בריקת וסקירת השכל, והה\"א הוא בחי' השגה והבנה להבין בגדולת א\"ס ב\"ה, והוא\"ו הוא בחי' מדות אהוי\"ר, וה\"א אחרונה הוא בחי' דבור<sup data-n=\"687\">38</sup> כו', וע\"י מה נעשה הוי' עמכם זהו ע\"י שדבר הוי' עמכם. וזהו שהי' כל אחד ואחד מישראל אומר עמי הדבור מדבר, פי' שהרגיש בנפשו הארת בחי' שם הוי' בכוחות נפשו בגילוי כו', וכמו\"כ גם עכשיו ע\"י לימוד התורה מתגלה שם הוי' בנפש האדם וכמארז\"ל כל הקורא ושונה הקב\"ה קורא ושונה כנגדו, וכדכתי' ה' צלך, ומאחר שהצל הנעשה הוא בחי' שם הוי'<sup data-n=\"688\">39</sup> בהכרח שהגורם הצל הוא ג\"כ בחי' הוי' והיינו שם הוי' שבנה\"א כו'. ושורש המשכה זו שבמ\"ת נלקח מבחי' ומדריגה גבוה מאד נעלה, כי כדי שיוכל להיות נמשך למטה כ\"כ עד שיוכל כאו\"א להרגיש בנפשו גילוי שם הוי' צ\"ל ההמשכה מבחי' גבוה מאד נעלה, ולכן על כל דיבור ודיבור פרחה נשמתן כו'.\n<b>ועל</b> המשכה גבוה כזו מובן ענין הקולות וברקי' שהי', להיות כי ענין הרעש הוא על דבר פלא, או מה שאינו מושג ע\"פ השכל, וכמו והאופנים וחיות הקדש ברעש גדול שנת' במ\"א שזהו מפני שמשיגי' שיש בחי' שאינם משיגי'<sup data-n=\"689\">40</sup> שלכן הם ברעש, וכמו\"כ על דבר שהוא פלאי ביותר לעוצם גובה מדריגתו יתכן ג\"כ הרעש, לכן על הגילוי אלקות כזה שלעוצם הגילוי א\"א לבוא בהלבשה כ\"א בדבר גשמי דוקא שייך בחי' קולות וברקי' כו'. ולכן יתורץ למה הי' צ\"ל קולות וברקי' לדברי' פשוטי' כאלו, שאדרבה שלהיות דברי' פשוטי' שרומזי' על גודל מעלת הגילוי שא\"א להתלבש כ\"א בדברי' פשוטי' דוקא ולכן הי' קולות וברקי' וקול שופר חזק מאד כו'.",[["685","36","<b>במ\"ת. . שנעשה שם הוי' בכאו\"א מישראל</b>: ראה בכ\"ז לקו\"ת פקודי ד, ב. מטות פו, ג. ובארוכה לקו\"ת ראה יח, א ואילך. תצא לח, ג. אוה\"ת יתרו ע' תתנה ואילך. תצא ע' תתקסב ואילך. סה\"מ תרכ\"ט ע' רטז-יז. וע' ש-שב. תרל\"ג ח\"ב ע' תמד ואילך. [ובהנסמן שם בתחילת המאמר]."],["686","37","<b>בעבודה בנפש האדם. . יו\"ד הוא בחי' נקודה</b>: בהמאמר כאן לא נת' ענין היו\"ד בעבודה, וראה ד\"ה זה תרס\"ב שם: יו\"ד הוא בחי' נקודה כו' ובעבודה הו\"ע הצמצום שכובש כל רצונותיו הן במח' כו' ובדיבור כו' ובמעשה כו' וצמצום זה הוא מבחי' החכ' שהוא הביטול למעלה מטעם המושג כו'. ובד\"ה זה תרע\"ח: היו\"ד הוא הביטול עצמי שבנשמה שלמעלה מטו\"ד המושג."],["687","38","<b>וה\"א אחרונה הוא בחי' דבור</b>: בד\"ה זה תרע\"ח מבאר ענינו בעבודה: ה\"א אחרונה הוא הדיבור בתורה ותפלה כו'."],["688","39","<b>וכדכתי' ה' צלך. . שהצל הנעשה הוא בחי' שם הוי'</b>: ראה סה\"מ תרכ\"ז ע' שכו. וש\"נ. תרל\"ג ח\"ב ע' תע. תעג-ד. וש\"נ."],["689","40","<b>והאופנים וחיות הקדש ברעש גדול שנת' במ\"א שזהו מפני. . שאינם משיגי'</b>: ראה לקו\"ת נשא כח, ד. האזינו עד, סע\"ג ואילך. ברכה צז, א-ב. סה\"מ תרכ\"ט ע' פג. וש\"נ. תרל\"ד ע'רמד. וע' רמו ואילך. ועוד."]]],[2000510248,"<h3>ויראו את אלקי ישראל</h3>\n<b>בס\"ד.</b>\n<b>במד\"ר</b><sup data-n=\"690\">1</sup> ס\"פ אחרי פך\"ג דף קצ\"א ע\"ד, דרש ר' לוי בר סיסי בנהרדעא, ויראו את אלקי ישראל ותחת רגליו כמעשה לבנת הספיר, זו עד שלא נגאלו (היתה תחת רגליו כדמות לבינה ע\"ש עמו אנכי בצרה, או ע\"ש וירא את ענינו) אבל משנגאלו היכן דרכה של לבינה להיות נתון שם, שם היא נתונה (כלומר לא נראית עוד, כ\"א רינה ושמחה במעונו כדכתי' בסיפא דקרא וכעצם השמי' לטוהר, עכ\"ל המ\"כ), וכ\"ה בירושלמי סוכה פ\"ד. ונמצא כי מפרש שבמקום שהיתה הלבינה נתונה בזמן גלות מצרי' היתה אח\"כ כעצם השמי' לטוהר. ובתרגום יונתן מפרש<sup data-n=\"691\">2</sup>, וזקפו נדב ואביהו ית עיניהו וחמו ית איקר אלקא דישראל ותחות אפיפורין דרגלי' דמיצע תחות כורסיא הי כעובד אבן סנפירנון מדכר שעבודא דשעבידו מצראי ית בנ\"י בטינא ובליבנין, והוו נשיא בטשן ית טינא עם גובריהן, הות תמן חד ריבא מפנקתא מעוברתא ואפילת ית עוברא ואיתבטש עם טינא, נחת גבריאל ועבד מינא לבינתא ואפקי לשמי מרומא ואתקני' גלוגדק תחות אפיפורין<sup data-n=\"692\">3</sup> דמארי עלמא, זיוי' הי כעובד אבן טבא, והי כתקוף שפר שמיא כד הוין ברירין מן ענניא. ונמצא מפרש שמהלבינה שעשו במצרי' כשהפילה הילדה עוברה עשה גבריאל ממנה כסא קטנה תחת כסה\"כ, א\"כ מהלבינה עצמה עשו השרפרף, והיא כמראה אבן ספיר שהוא אבן טוב שדומה לעצם השמי' כשהוא בטהרתו. והוא כי באבן ספיר רבו המפרשי' בו מהו, יש שפירשו על קריסטאל, ויש שפי' על דימאנט, כמ\"ש בבחיי ובמכלול<sup data-n=\"693\">4</sup>. והנראה כי הוא מפרש שזהו אבן טוב שמראיתה תכלת, והיינו כמארז\"ל סוטה די\"ז ים דומה לרקיע<sup data-n=\"694\">5</sup> ורקיע דומה לכסה\"כ מקרא זה ומתחת רגליו, וכתי' כמראה אבן ספיר דמות כסא, עכ\"פ מפרש שהלבינה עצמה נעשה כעצם השמי'.",[["690","1","<b>במד\"ר. . ויראו את אלקי ישראל</b>: מאמר זה (מפיסקא: אך הענין יובן ע\"פ מ\"ש בפע\"ח, עד פיסקא: ובכדי לתקן חטא זה) הוא חלק מד\"ה והי' הנשאר בציון תרל\"א פרקים א-ד (לעיל ע' יא ואילך) בשינויים והוספות. ומיוסד על ד\"ה ויהי כל הארץ באוה\"ת נח (כרך ג) תרנד, סע\"א ואילך. לכללות המאמר ראה בהנסמן לעיל בד\"ה והי' הנשאר בציון בתחילתו.\nתוכן המאמר נמצא בשינויים והוספות בד\"ה זה בסה\"מ תרנ\"ה ע' צד ואילך. וחלקו הראשון בד\"ה ויראו את אלקי ישראל בסה\"מ תרס\"ח ס\"ע קו ואילך.\nלהתחלת וסיום המאמר ראה ד\"ה זה באוה\"ת משפטים ס\"ע א'רפח-ט. וע' א'רצב."],["691","2","<b>ובתרגום יונתן מפרש</b>: ראה ד\"ה זה תרס\"ח: בת\"י מפרש ג\"כ על שעבוד מצרים רק שמפרש דהלבינה גופא נעשה כעצם השמים לטוהר."],["692","3","<b>ואתקני' גלוגדק תחות אפיפורין</b>: ראה פי' יונתן לתרגום יונתן שם: אפיפורין תרגום של הדום רגליו כו' ופי' הערוך כורסן קטן תחת רגליהם. וגלוגדק הוא ספסל יותר קטן ממנו ונמצא בגמ' פ' אין צדין זקן אחד היה בשכונתי ויוצא בגלוגדקא שלו."],["693","4","<b>באבן ספיר רבו המפרשים בו מהו. . בבחיי ובמכלול</b>: ראה בכ\"ז בארוכה אוה\"ת משפטים ע' א'רפו. א'רצג."],["694","5","<b>שמראיתה תכלת. . כמארז\"ל סוטה די\"ז ים דומה לרקיע</b>: ז\"ל הגמ' שם (יז, סע\"א): שהתכלת דומה לים וים דומה לרקיע ורקיע דומה לכסא הכבוד שנאמר ויראו את אלקי ישראל ותחת רגליו כמעשה לבנת הספיר וכעצם השמים לטהר וכתיב כמראה אבן ספיר דמות כסא. ובפירש\"י: ורקיע דומה לכסא הכבוד, קראי קדריש דכתיב ברקיע כמעשה לבנת הספיר וכתיב בכסא הכבוד כמראה אבן ספיר דמות כסא."]]],[2000510249,"<b>ולהבין</b> דבריו וגם דברי הירושלמי והמדרש הנ\"ל, צ\"ל טענת משה שטען למה הרעותה לעם הזה למה זה שלחתני, וארז\"ל במד\"ר ס\"פ שמות, שאמר משה נטלתי ספר בראשית ומדת הדין היתה, פי' שהודה שמגיע להם עונשם, והיינו שקאי על דור המבול ודור הפלגה, אבל אלו מה חטאו, והשיב לו הקב\"ה וידבר אלקי' כו' אני הוי', שמובן התשובה שאין זה מדה\"ד כ\"א רחמים. ולכאו' אינו מובן האיך יתכן לומר על שעבוד קשה כזה בחומר ובלבנים שזהו רחמים כו'.\n<b>אך</b> הענין יובן ע\"פ מ\"ש בפע\"ח<sup data-n=\"695\">6</sup> שער חגהמ\"צ שישראל שהיו במצרי' הם היו גלגול דור הפלגה שחטאו ועשו עיר ומגדל וראשו בשמים, ומפני כי לא היו אבני' בבבל כמארז\"ל וכי יש אבני' בבבל, לכן ותהי להם הלבנה לאבן, ולתקן חטא דור הפלגה לכן עינו אותם במצרי' בחומר ובלבנים להיות להם לכפרת עון וזיכוך על שחטאו בלבנים בבנין העיר והמגדל. ולהבין זה צ\"ל שורש ההפרש בין אבן ללבינה<sup data-n=\"696\">7</sup>, בהיות ידוע כי האבני' הם בריאה בידי שמי' והלבינה היא הנעשית בידי אדם, והענין הוא דהנה האבני' בכלל הם אותיות וכנודע ממ\"ש בס\"י שתי אבנים בונות שתי בתי', כינה להאותיות בשם אבנים וצירופי התיבות בשם בתים<sup data-n=\"697\">8</sup>, והיינו שכמו הבית הוא כאשר מצרפי' הרבה אבנים יחד, כן בהקבץ כמה אותיות יחד נעשה מזה תיבה אחת, ותיבה אשר היא משני אותיות יכולי' לצרפה על שני צירופי' עד\"מ אב יש בו שני צירופי' אב בא, אמנם הנה נודע שענין האותיות הם כלים להאור המלובש בו, וכמו תיבת אב מורה על שהולידו, ותיבת בא מורה שיבוא, הרי האותיות הם כלים להאור הגנוז בו. והנה נודע ממ\"ש בע\"ח בכ\"ד שמ\"ה מברר ב\"ן, וידוע שבחי' מ\"ה וב\"ן יש בהם אורות וכלים<sup data-n=\"698\">9</sup>, והיינו שבשם מ\"ה יש אותיות הם הנק' כלים דמ\"ה, ויש אור המאיר בהאותיות, וכן בשם ב\"ן יש ג\"כ אורות וכלים שהאותיות הם כלים והאור הוא המלובש בהאותיות.\n<b>וביאור</b> הענין נבין תחלה ענין האותיות דשם מ\"ה, הנה ידוע שבחי' שם מ\"ה הוא בחכ', שע\"ש זה נק' חכמה מלשון כח מ\"ה, וענין בחי' מ\"ה הוא בחי' הביטול לאלקות שזה בא מצד החכמה שהוא בחי' מהות הביטול שלכן השראת אוא\"ס הוא בחכ' להיותה בחי' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה, וזהו כענין שאמר משה ונחנו מ\"ה, אמר להם להיותן בבחי' ביטול עד שלא הי' מורגשי' בנפשם לאיזהו מציאות דבר כ\"א בתכלית הביטול לכן לא עלינו תלונותיכם כי מה",[["695","6","<b>אך הענין יובן ע\"פ מ\"ש בפע\"ח</b>: הבא לקמן (עד פיסקא: ובכדי לתקן חטא זה) הוא מד\"ה והי' הנשאר בציון שם בשינויים והוספות."],["696","7","<b>ולהבין זה צ\"ל שורש ההפרש בין אבן ללבינה</b>: בהבא לקמן ראה בארוכה ד\"ה ויראו את אלקי ישראל בתו\"א משפטים עז, סע\"ג ואילך. עח, ב-ג. אוה\"ת משפטים ע' א'רעג ואילך. וראה גם לקו\"ש ח\"ו ע' 15 ואילך."],["697","8","<b>האבני' בכלל הם אותיות. . שתי אבנים בונות שתי בתים</b>: ראה בכ\"ז תו\"א ויצא כא, ב. וארא נו, סע\"ב."],["698","9","<b>וידוע שבחי' מ\"ה וב\"ן יש בהם אורות וכלי'</b>: ראה ד\"ה זה תרנ\"ה: בד\"כ ב' בחי' אלו (מ\"ה וב\"ן) הם בחי' אורות וכלים, שם מ\"ה הוא בחי' האור כו' ושם ב\"ן עיקרו בחי' כלים, וזהו בדרך כלל, אך בדרך פרט יש בכל אחד מב' הבחי' מ\"ה וב\"ן בחי' אורות וכלים [כדלקמן בפנים]."]]],[2000510250,"אנו נחשבי' כו'. והנה בהכרח לומר שיש בחי' כלי להכיל ולקבל בחי' ביטול הלזה שבחכ', כי א\"א לאור להתקיים בלתי ע\"י איזה דבר הנאחז, וכמו האש שבלתי פתילה או עץ הנאחז בו אינו מתקיים, וכן המים בלתי כלי ישפכו וילכו להם מגבוה לנמוך, ולכן גם לבחי' הביטול דמ\"ה שבחכ' בהכרח שיהי' בו איזה כלי שיאחז בו האור והוא בחי' אותיות שבשכל שהם הנק' כלי' שבהם מלובש האור כו', ובחי' האותיות אלו הם המביאי' לידי גילוי בחי' אור הביטול דשם מ\"ה. וזהו מ\"ש מכון לשבתך פעלת כו' שבחי' הכלי' הם מכון לשבת האור דשם מ\"ה שבחכ', כדמיון הבית שהוא מקום מושב האדם כו'. והנה אותיות אלו דשם מ\"ה הם הנק' אבנים, כי אבן הוא מל' א' ב\"ן<sup data-n=\"699\">10</sup>, אל\"ף הוא בחי' שם מ\"ה שהוא שם הוי' במילוי אלפי\"ן אז עולה מספרו מ\"ה, ובחי' ב\"ן שבתיבת אבן הוא בחי' הכלי לאור הזה דשם מ\"ה, ונמצא כי זהו בחי' ב\"ן דמ\"ה, ובחי' אותיות אלו דב\"ן שבמ\"ה הם היורדי' להתגלות מלמעלה שעל ידם יומשך הביטול דמ\"ה כו' ועז\"נ תשתפכנה אבני קדש, שיש אבנים שבהם וע\"י מתגלה בחי' קדש הוא בחי' ביטול שבחכ' שנק' קדש בכלל.\n<b>וכמו\"כ</b> יובן ענין הכלים דשם ב\"ן, שענין שם ב\"ן הוא בחי' ביטול היש לאין, ולא בחי' ביטול בעצם<sup data-n=\"700\">11</sup> כביטול דמשה שאמר ונחנו מ\"ה, כ\"א יש ובטל, דהיינו מה שהוא יש ודבר מ\"מ יתבטל לאין המהוה אותו, וה\"ז כביטול המלאכי' נבראי', כמו עד\"מ ביטול מיכאל שהוא באהבה הנה מאחר שיש לו אהבה הרי הוא בבחי' מציאות איזה דבר, כי הרי בהכרח לומר שיש מי שאוהב ומתפעל באהבה<sup data-n=\"701\">12</sup>, וכן גבריאל ביראה, וכן הוא בשרפים. וכאשר יבואו לבחי' הביטול כתי' בעמדם תרפינה כנפיהם, פי' כנפיהם היא בחי' הביטול דאהוי\"ר<sup data-n=\"702\">13</sup> כו', וכן המלאך כשהולך בשליחותו של מקום הרי משתנה למהות ביטול<sup data-n=\"703\">14</sup> עד שיכול לקרות על עצמו בשם הוי' וכמ\"ש ותקרא את שם הוי' הדובר אלי', וכתי' במלאך שאמר לאברהם בי",[["699","10","<b>אבן הוא מל' א' ב\"ן</b>: ראה שעהיוה\"א פ\"ז (פד, ב). ובכ\"מ."],["700","11","<b>שענין שם ב\"ן הוא בחי' ביטול היש לאין ולא בחי' ביטול בעצם</b>: בד\"ה זה תרנ\"ה מוסיף: דזהו לבנים הנעשים בידי אדם אדם בגימ' מ\"ה דהיינו מה שבחי' מ\"ה מברר ב\"ן, והיינו שהביטול שלהם אינו ביטול עצמי כ\"א האור פועל בהם הביטול."],["701","12","<b>ביטול מיכאל שהוא באהבה. . בהכרח לומר שיש מי שאוהב ומתפעל באהבה</b>: בד\"ה זה תרנ\"ה נוסף כאן הגה\"ה: וצ\"ע איך הכוונה כאן, אם הכוונה שהאהבה גופא הוא בחי' יש כמ\"ש במ\"א בענין יש מי שאוהב כו', ולפ\"ז מ\"ש אח\"כ [במאמר כאן] בענין תרפינה כנפיהם היינו הביטול דהאהוי\"ר שמתבטל מהאהוי\"ר כו', וביטול זה הוא ג\"כ ביטול היש לבד כמשי\"ת, אמנם לא משמע כן ממ\"ש לקמן האהבה והיראה הוא האור כו'. או הכוונה שבהכרח שיש מי שמתפעל באהבה זו והיינו הגוף שהוא המתפעל כו' (ובבחי' מ\"ה לא שייך לומר כן שהרי מ\"ה הוא בחי' ביטול במציאות כו'), וכן ביראה היינו בחי' יראה תתאה ג\"כ יש מי שמתפעל ביראה כו', ולפ\"ז מ\"ש בעמדם תרפינה כנפיהם אין הכוונה לדקדק תיבת תרפינה שהוא הרפיון כנ\"ל, כ\"א הכוונה בחי' הכנפיים שהם האהוי\"ר שלהם שזהו ביטולם כו'."],["702","13","<b>בעמדם תרפינה כנפיהם. . בחי' הביטול דאהוי\"ר</b>: ראה בארוכה לקו\"ת שה\"ש כו, ב. אוה\"ת שה\"ש (כרך ב) ע' שצט. ועוד."],["703","14","<b>המלאך. . משתנה למהות ביטול. . לקרות על עצמו בש' הוי'</b>: ראה גם אגה\"ק סי' כה (קמא, סע\"א). לקו\"ת במדבר יא, ב. שה\"ש כ, ג. מאמרי אדהאמ\"צ במדבר ח\"ג ע' תח ואילך. דרך מצותיך כז, א. אוה\"ת תשא ע' ב'לא. סה\"מ תרכ\"ט ע' ריב ואילך. תרל\"ב ח\"א ע' מ. תרל\"ג ח\"א ע' נב-ג. ועוד."]]],[2000510251,"נשבעתי, ולכאו' יפלא האיך יקרא עצמו בשם הוי', אך הענין להיות כי הוא בטל לגמרי להמשלח לכן קורא עצמו בשם משלחו, נמצא שהביטול הוא ביטול גבוה מאד נעלה, מ\"מ הרי זהו ביטול היש שהרי הוא נברא יש מאין, וכמארז\"ל במד\"ר שהמלאכי' יש מי שאומר שנבראו בשני ויש מי שאומר שנבראו בחמישי, ואמרו שם הכל מודי' שלא נבראו בראשון שלא יהיו אומרי' מיכאל מותח בדרום וגבריאל בצפון והקב\"ה ממדד באמצע, הה\"ד אני ה' עושה כל מי אתי, מי הי' שותף אתי<sup data-n=\"704\">15</sup> במע\"ב, הרי הם נבראי' בע\"ג, וממילא א\"א לקרות בחי' הביטול שלהם כ\"א בחי' ביטול היש לאין כו', והרי זהו בחי' ב\"ן, האהבה והיראה הוא בחי' האור, וגוף המלאך שמתפעל באהוי\"ר הרי גופם הוא מב' יסודות אש ורוח<sup data-n=\"705\">16</sup> כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט זה נלקח מבחי' האותיות דשם ב\"ן. ונמצא מובן שגם בשם ב\"ן יש אורות וכלים שהם בחי' האהוי\"ר והכלי המחזיקן אשר יש להם בחי' אהוי\"ר כו'.\n<b>אמנם</b> כ\"ז הוא בבחי' הביטול דקדושה, וכמו\"כ בלעו\"ז יש ג\"כ ב' בחי' אלו דמ\"ה וב\"ן, כי את זה לעומת זה עשה האלקי', ולכן כמו שיש בקדושה בחי' מ\"ה וב\"ן כן בלעו\"ז יש ג\"כ מ\"ה וב\"ן, והוא מ\"ש ופלגשו ושמה ראומה, ראו מ\"ה<sup data-n=\"706\">17</sup> שבחי' הביטול הוא בהרגשה הרי זהו בחי' מ\"ה שבלעו\"ז, שזהו עדיין קליפה דאצי'. אמנם הנה בלבושי נוגה שלמטה מזה יש בחי' הקליפה שהוא לעומת שם ב\"ן<sup data-n=\"707\">18</sup>, והוא בחי' לבינה שע\"ז ארז\"ל זקף לבינה והשתחוה לה.\n<b>ועפ\"ז</b> יובן ענין חטא דור הפלגה שבנו עיר ומגדל מן הלבינה שעשו תמורת האבן, והיינו כי כל עיקר ההמשכה שהי' בקדושה הוא ע\"י עיר ומגדל, שהעיר הוא בחי' עיר אלקינו, והמגדל הוא בחי' בהמק\"ד שהי' בירושלי' שע\"ז נא' כרם הי' לידידי ויבן מגדל בתוכו, שקאי על בהמק\"ד. והנה ענין עיר אלקינו<sup data-n=\"708\">19</sup> הוא בחי' כללות עולם הדיבור, והיינו שכמו מקיבוץ בתים הרבה נעשה עיר, והבית עושי' מאבנים כן יובן שענין האבנים הוא בחי' האותיות שמהם נעשו צירופי התיבות, וכלליות עולם הדבור נק' בשם עיר. ונק' עיר אלקינו להיות כי שם אלקי' הוא שורש בחי' הכלי' כנודע ממ\"ש במ\"א ששם הוי' הוא שורש האורות ושם אלקי'",[["704","15","<b>וכמארז\"ל במד\"ר שהמלאכי'. . שנבראו בשני. . מי הי' שותף אתי</b>: ראה גם בכ\"ז סה\"מ תרכ\"ט ע' קנו."],["705","16","<b>גופם. . מב' יסודות אש ורוח</b>: ראה לקו\"ת ברכה צח, א. סה\"מ תרל\"ג ח\"א ע' רסט. ובכ\"מ. וראה לקו\"ש ח\"ט ע' 404. וש\"נ."],["706","17","<b>ופלגשו ושמה ראומה ראו מ\"ה</b>: ראה גם לקו\"ת תזריע כג, ד. בהר מג, א. מאמרי אדה\"ז אתהלך לאזניא ס\"ע ח. וע' רמט. סה\"מ תרל\"ג ח\"ב ע' תנו. וש\"נ."],["707","18","<b>הקליפה שהוא לעומת ש' ב\"ן והוא בחי' לבינה</b>: נת' בד\"ה זה תרנ\"ה: וזהו אותיות דלעו\"ז שהם בתכלית הישות (וי\"ל שהן מחדו\"מ דלעו'ז כו'), וזהו לעו\"ז דשם ב\"ן שהוא בחי' יש ובטל להאין כנ\"ל, ובלעו\"ז הוא בתכלית הישות והעדר הביטל לגמרי כו'."],["708","19","<b>והנה ענין עיר אלקינו</b>: בהבא לקמן (עד קרוב לסוף המאמר) ראה אוה\"ת נח שם תרנה, א-ב. וראה גם שם תרסג, ב. שם (כרך ו) תתער, א-ב. שם (כרך ז) תתשעה, ב ואילך. נ\"ך (כרך א) ע' קמה ואילך."]]],[2000510252,"הוא שורש הכלי'<sup data-n=\"709\">20</sup>, ונק' אלקינו שהוא בחי' אלקי' שלנו<sup data-n=\"710\">21</sup> והיינו כי כל עיקר מכוון מברה\"ע הוא בשביל נש\"י, וכמ\"ש אנכי עשיתי ארץ ואדם עלי' בראתי, ואתם דוקא קרוי' אדם, וכן ארז\"ל ע\"פ בראשית ברא בראשית בשביל התורה שנק' ראשית ובשביל ישראל שנק' ראשית, לכן נק' כלליות עולם הדבור שהוא מקור כל סדרי ההשתלשלות בשם עיר אלקינו כו' להיות כי עיקר המכוון הוא בשביל ישראל. וענין המגדל הוא בחי' שם הוי' כמ\"ש מגדל עוז שם הוי', ששם הוי' הוא בחי' המגדל שבתוך עיר אלקינו הנ\"ל, וכמ\"ש גדול ה' ומהולל מאד בעיר אלקינו ואמרז\"ל אימתי הוא גדול כשהוא בעיר אלקינו, משא\"כ מלכא בלא מטרוניתא הרי אמרו בזהר ויקרא ד\"ה ע\"ב לאו איקרי מלכא ולא איהו גדול ולא איקרי מהולל, והיינו מפני כי עיקר המכוון הוא בשביל בריאה הגשמיות שיקיימו נש\"י תומ\"צ כמו שהם מלובשי' בדברי' גשמי', אך בכדי שיהי' עוה\"ז הי' צריך תחלה להיות השתלשלות העולמות ברוחני' עד שנתהוה בדרך בריאה יש מאין עוה\"ז הגשמי כמ\"ש מזה במ\"א<sup data-n=\"711\">22</sup>, ולכן שם הוי' בלא שם אלקי' לאו איהו גדול, כי עיקר המכוון הוא מה שנתהוה ע\"י צמצום דשם אלקי' כו'.\n<b>והנה</b> כדי להמשיך תוס' וריבוי אורות בשם אלקי' מקור בחי' עיר אלקינו ושם הוי' בחי' המגדל, זהו ע\"י בחי' עיר ומגדל שיש בנפש האדם, דהנה כתי' ואשים דברי בפיך<sup data-n=\"712\">23</sup> ובצל ידי כסיתיך לנטוע שמים וליסוד ארץ ולאמר לציון עמי אתה, וארז\"ל בירושלמי חזרנו על כל המקרא ולא מצינו שנק' ישראל ציון אלא בפסוק הזה, והיינו ע\"י ג' דברי' אלו שנא' בו, ואשים דברי בפיך זו תורה שהיא בחי' דבר ה' וכמ\"ש ודברי אשר שמתי בפיך, ופי' דברי בפיך שהתורה היא המשכה בבחי' פנימיות וכמ\"ש ותורתך בתוך מעי<sup data-n=\"713\">24</sup>, ובצל ידי כסיתיך זהו מעשה המצות שע\"י נמשך מקיפי' עליונים, וכמ\"ש ה' צלך על יד ימינך פי' שהצל והמקיף נמשך על יד ימינך הוא בחי' המצות, לנטוע שמים וליסוד ארץ הוא בחי' קרבנות, וכמארז\"ל אלמלא מעמדות לא נתקיימו שמים וארץ, ועכשיו תפילה במקום קרבנות שהוא בחי' סולם מוצב ארצה וראשו מגיע השמימה, וע\"י ההעלאות שבסולם זה דתפילה עי\"ז מתקיים שמים וארץ, ולכן מתחלת התפילה מדברי' קטנים שלא עשני עבד, ואח\"כ פסוקי דזמרה וברכת ק\"ש וק\"ש, עד שבשמ\"ע הוא בחי' המשכה בשם הוי', שזהו פי' ברוך אתה הוי' פי' שיבורך ויומשך המשכת תוס' וריבוי אורות בשם הוי', והיינו לפי ערך המס\"נ בק\"ש בבחי' אליו ולא למדותיו לפי ערך זה הוא בחי' ההמשכות בשמו\"ע, ועי\"ז הוא קיום שמים וארץ כו'. והנה ע\"י ג' בחי' אלו תורה ומצות וקרבנות ועכשיו תפילה במקום קרבנות נק' נש\"י ציון שהוא בחי' מגדל",[["709","20","<b>כנודע ממ\"ש במ\"א שש' הוי'. . שורש האורות. . אלקי'. . שורש הכלי'</b>: ראה סה\"מ תר\"ל ע' רלז. ובכ\"מ."],["710","21","<b>ונק' אלקינו. . אלקי' שלנו</b>: ראה לקו\"ת נצבים נג, סע\"ג. ועוד."],["711","22","<b>השתלשלות העולמות ברוחני' עד שנתהוה. . יש מאין. . כמ\"ש במ\"א</b>: ראה סה\"מ תרכ\"ט ע' קנז ואילך. וש\"נ. תרל\"ב ח\"א ע' ערב ואילך. וש\"נ."],["712","23","<b>והנה כדי להמשיך. . ואשים דברי בפיך</b>: בהבא לקמן ראה בארוכה אוה\"ת ויצא ריג, ב ואילך. דברים ע' לו ואילך. שם (כרך ו) ע' ב'תקצז ואילך. נ\"ך (כרך ג) ע' א'קפז ואילך. ועוד."],["713","24","<b>שהתורה. . פנימיות. . ותורתך בתוך מעי. . המצות. . מקיפים</b>: ראה גם לעיל ד\"ה ת\"ר נר חנוכה. וש\"נ."]]],[2000510253,"ובחי' ירושלי' שהיא עיר אלקינו, וע\"י התומ\"צ ותפילה עי\"ז נמשך תוס' אורות בש' הוי' ושם אלקי' היא בחי' העיר והמגדל הנבנה מאבנים שהם בריאה בידי שמים. ובעבודה הוא בחי' האותיות דתורה ותפילה, שהם בחי' אותיות דש' מ\"ה בחי' הביטול, כי אותיות התורה הם דבר ה' ודברי אשר שמתי בפיך, וכן התפילה הוא בחי' הביטול שמספרי' ענין בחי' ביטול המלאכי' וכל צבא השמי' כו'. ובדרך פרט הוא בחי' אותיות דמ\"ה ואותיות דב\"ן, אותיות התורה הוא בחי' אותיות דמ\"ה, ואותיות התפילה הוא בחי' אותיות דב\"ן, להיות כי התפילה הוא מביטול המלאכי' שנת\"ל שהם בחי' ביטול היש, אמנם באמת גם בתפילה יכולי' לבוא לבחי' ביטול אמיתי, והיינו ע\"י מס\"נ דק\"ש שזהו מצד מעלת נש\"י שיכולי' ע\"י ביטולם במס\"נ לבוא לבחי' ביטול במציאות, שזהו ג\"כ מבחי' ביטול דמ\"ה וממילא האותיות הם הכלי' לבחי' ביטול זה כו' וה\"ז אותיות דמ\"ה כמשנ\"ת לעיל. ובזה יובן מה שארז\"ל עתידי' צדיקי' שיאמרו לפניהם קדוש שנא' והי' הנשאר בציון והנותר בירושלי' קדוש יאמר לו, שלכאו' יפלא הלא הנשארי' בציון וירושלי' הם מעט מן המעט, שרוב ישראל הם בחו\"ל ומהו הנשאר בציון כו', וגם הלא קורא אותם צדיקי' סתם והל\"ל צדיקי' שבארץ. אך הענין הוא כנ\"ל שע\"י קיום ג' דברי' אלו נק' ישראל ציון וירושלי' גם בהיותם בארץ לא להם, ולכן יתכן לקרותם צדיקי' סתם, היינו כשמקיים ג' בחי' אלו דתורה ומצות ותפילה שעי\"ז נק' ציון לע\"ל יאמרו לפניהם קדוש כו', ולפ\"ז פי' ציון הוא מל' ציון וסימן שע\"י שישראל הם מסויימים בג' דברי' אלו כו' עי\"ז ממשיכי' תוס' וריבוי אור בבחי' עיר ומגדל כו'.\n<b>אמנם</b> הנה דור הפלגה לא רצו בזה<sup data-n=\"714\">25</sup>, וידעו שההמשכה בקדושה הוא ע\"י עיר ומגדל, אך א\"א לקבל מבחי' זו כ\"א ע\"י הביטול דוקא, והם היו חכמים להרע לכן התחכמו לבנות עיר ומגדל<sup data-n=\"715\">26</sup> וראשו בשמים, פי' שרצו לקבל השפעות חיצוניות ע\"י שמושי השמות וקבלה מעשיות<sup data-n=\"716\">27</sup> שיומשך להם השפעה גשמיות, ורצו להרוס כל בנין הקדושה ולעשות עיר ומגדל בקליפה היפך עיר ומגדל דקדושה, וזהו שאמר הכתוב וראשו בשמים, פי' שרצו לקבל מבחי' שמים כענין שכתוב דרך הנשר בשמים והיינו שרצו לקבל מבחי' אוא\"ס אשר שם כחשיכה כאורה ואינו תופס מקום כלל, לזה אמר הכתוב אם תגביהי כנשר<sup data-n=\"717\">28</sup> משם אורידך נאום הוי' פי'",[["714","25","<b>אמנם הנה דור הפלגה לא רצו בזה</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת נח שם תרנז, א-ב. וראה גם שם תרסב, ב ואילך. שם (כרך ו) תתרסו, ב ואילך. סה\"מ תרכ\"ו ע' קיח. סה\"מ תר\"ל ע' ד ואילך. המשך זאת חנוכת המזבח תר\"מ בסה\"מ תר\"ם ח\"א ע' ע ואילך."],["715","26","<b>לקבל. . ע\"י הביטול. . התחכמו לבנות עיר ומגדל</b>: בהבא לקמן ראה תו\"א נח יא, א-ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' עב ואילך. תו\"ח נח עד, ב ואילך. אוה\"ת נח (כרך ו) תתרסט, ב ואילך."],["716","27","<b>ע\"י שמושי השמות וקבלה מעשיות</b>: ראה ד\"ה זה תרנ\"ה: ענין השבעת השמות שנמשך מהשם פעולה נפלאה והוא אינו יודע ואינו מרגיש כלל את השם וגודל מעלתו כו'. — וראה בכ\"ז אוה\"ת נח שם. וראה גם תו\"א נח שם י, ב. מאמרי אדהאמ\"צ שמות ח\"א ע' כה ואילך. אוה\"ת נח תרסד, א. וארא (כרך ז) ע' ב'תתקנב-ג. ב'תקנז. מטות ע' א'רפט. סה\"מ תר\"ם שם."],["717","28","<b>דרך הנשר בשמים. . אם תגביהי כנשר</b>: ראה בכ\"ז הוספות לתו\"א ויחי קב, סע\"ב-ג. סה\"מ תרל\"ב ח\"א ע' נג ואילך. וש\"נ. שם ע' רכה ואילך."]]],[2000510254,"שאם אפי' תגביהי כנשר לקבל מבחי' אשר שם כחשיכה כאורה מ\"מ משם אורידך נאום הוי'. וזהו שהי' חטאם גדול מאד מפני שרצו להרוס כל בנין הקדושה ולהמשיך בסט\"א שיומשך להם השפעת גשמיות ע\"י השבעת השמות וקבלה מעשיות. ומה שהי' כח לעשות דבר זה הוא מפני כי היו באחדות<sup data-n=\"718\">29</sup> והי' להם שפה אחת ודברי' אחדי', לכן ע\"י האחדות היו יכולי' לעשות זאת אם לא בלל ה' שפתם אשר לא ישמעו איש שפת רעהו ולא יבינו דיבורם זע\"ז, כי האחדות הוא כח נפלא להיות יכולי' להמשיך ולפעול כרצונם, וכענין שארז\"ל דורו של אחאב היו כולו עובדי ע\"ז ועכ\"ז היו יורדין למלחמה ונוצחי' כי זהו ע\"י כח האחדות שהי' בניהם וכמ\"ש חבור עצבים אפרים הנח לו, וכמו\"כ יובן בענין דור הפלגה שמפני שהיו עם אחד ושפה אחת עי\"ז היו יכולי' לבנות העיר והמגדל.\n<b>ובכדי</b> לתקן חטא זה<sup data-n=\"719\">30</sup> ירדו אבותינו למצרים, ובעת השעבוד ירדו נשמות שהיו בדור הפלגה ונתגלגלו בישראל שהיו במצרים, ונשתעבדו בחומר ובלבנים עד שנזדככו ותיקנו חטא שעשו הלבינה לאבן שהוא בחי' שפחה כי תירש גבירתה, ובמדה שאדם מודד בו מודדי' לו לכן היו עבדים, ונשותיהם היו שפחות במצרים. ונמצא כי הגם ששעבוד מצרים הי' דין קשה מ\"מ ה\"ז הוא רחמים גמורים, כי מאחר שעי\"ז מתתקנים הנשמות שפגמו, וכמ\"ש בפע\"ח בשער חגהמ\"צ שיורדי מצרים היו גלגול דור הפלגה. ולכאו' עומד לנגד לכתבי האריז\"ל ממשנה ג' פ' חלק שדור הפלגה אין להם חלק לעוה\"ב, ע' ברש\"י ובתוי\"ט שעומדי' בדין אבל מ\"מ אין להם חלק לעוה\"ב. י\"ל שבזמן התחי' לא יקומו הגופות של דור הפלגה אבל הרי נתלבשו נשמותיהן בגופות דיורדי מצרים ונתתקנו הנשמות ויחיו בעולם התחי'. אך עדיין אינו מובן שהרי יורדי מצרי' הן הן דור המדבר שאמרו עליהם שאין להם חלק לעוה\"ב ומהו פעולת הזיכוך דמצרים. אך י\"ל הלא ר' אליעזר ור' שמעון בן מנסיא פליגי על ר\"ע ואומרי' שבאים לעוה\"ב, ור' יוחנן אמר על ר\"ע שבקי' לחסידותא עבור מה שא' שאין להם חלק לעוה\"ב, ומביא קרא דהלוך וקראת כו' זכרתי כו' לכתך אחרי במדבר, ומה אחרים באים בזכותם הם עצמן לא כ\"ש, לכן מיושב דברי הפרע\"ח על נכון.\n<b>ועפ\"ז</b> יתפרשו דברי המד\"ר שדרש ר\"ל ב\"ס, ותחת רגליו כמעשה לבנת הספיר זהו עד שלא נגאלו, והיינו להורות שקושי השעבוד בא להם לפי שעשו לבינה תמורת האבן בעת דור הפלגה כדכתי' ותהי להם הלבינה לאבן, ומשנגאלו היכן דרכה של לבינה להיות נתון שם היא נתונה, להיות כי נתבררו ע\"י השעבוד בחומר ובלבני' ולכן נעשה אח\"כ כעצם השמי' לטהר. וי\"ל שלכן מסמיך למאמר זה",[["718","29","<b>כי היו באחדות. . שפה אחת ודברים אחדים</b>: בהבא לקמן ראה תו\"א נח שם יא, ב. [ובמקומות שנסמנו לעיל הערה ד\"ה: לקבל. . ע\"י הביטול]."],["719","30","<b>ובכדי לתקן חטא זה. . שיורדי מצרי'. . גלגול דור הפלגה</b>: בהבא לקמן ראה בארוכה אוה\"ת נח שם תרסב, א. תרסד, א ואילך. שמות ע' כה. וארא (כרך ז) ע' ב'תקנב ואילך. ב'תקסז ואילך. סה\"מ תר\"ם שם. וראה גם אוה\"ת משפטים שם ע' א'רצב."]]],[2000510255,"מאמר הרואה חמה<sup data-n=\"720\">31</sup> בתקופתה ולבנה בכדורה, היינו שע\"י הבירור מחומר ולבנים נתברר ונעשה מן לבינה בחי' לבנה ולכן ישראל מונין ללבנה דוקא, וזהו שנצטוו על קידוש החדש במצרי' כמ\"ש בפ' בא החדש הזה לכם להיות כי ע\"י שעבוד מצרי' נתבררו מלבינה להיות בחי' יפה כלבנה כו'. והת\"י מפרש עוד יותר שמהלבנים שעשו שהפילה הריבא עוברה ונתבטש בטינא הנה מזה עצמו עשה גבריאל שרפרף תחת כסא הכבוד, והוא עצמו נעשה טהור כעצם השמים ע\"ד זדונות נעשו כזכיות כן הלבינה נעשה כעצם השמים לטוהר כו'.",[["720","31","<b>מסמיך למאמר זה. . הרואה חמה</b>: ראה אוה\"ת משפטים שם ע' א'רצב."]]],[2000510256,"<h3>קדש ישראל</h3>\n<b>[לד\"ה ועשו ארון]</b>\nקדש ישראל לה'<sup data-n=\"721\">1</sup> ראשית תבואתה, תבואת ה' ונק' תבואתו בוא\"ו חטה ושעורה, פסח אביב, ושבועות שתי הלחם, וישראל ראשית התבואה, וביאור הענין, ישראל מתקשראין, ופעם נק' ישראל חתן, שורש הנשמה ונשמה המלובשת בגוף, ומצד היותם למטה מתקשראין, ומצד שרשם נק' חתן, תורה כמ\"ש למעלה, דוד הי' מחבר תורה שלמעלה בהקב\"ה, והענין ברכו בתורה<sup data-n=\"722\">2</sup>, המשכת אוא\"ס, טל תורה, ואור הגנוז, גשם וטל, וישראל ממשיכי' אוא\"ס בתורה, וזהו כל הקורא ושונה, ולכאו' הלא ג' שעות כו' אך הענין שזהו בשביל התורה, וע\"י הלימוד לשמה ממשיכי' בחי' זו, את\"י בניך אלא בוניך, ואז נק' הארון שבו התורה על שמם, ומה שתלו זה בזמן שערצוש\"מ זהו כי בכדי להמשיך זהו ע\"י מס\"נ דק\"ש שעי\"ז מקשרין בחי' התורה אדם ובחי' כי לא אדם כמ\"ש בת\"א בד\"ה זכור<sup data-n=\"723\">3</sup> וכדי להעלות שזהו ע\"י עושי' רצש\"מ בחי' ק\"ש קבעומ\"ש, תחלה דוקא, עול תורה כו'.\n<b>ועול</b> תורה זהו כענין הקדמת נעשה לנשמע ולפי' הרש\"א שבעשר עושי' רצוש\"מ שוה מלאכתן כאלו עשאן משה בחי' ד\"ע כי ע\"י תורה עם ביטול זהו כענין תשובה עילאה לגבי יו\"ד, ולכן כמו ד\"ע מחבר חו\"ב כן ע\"י למוד התורה לשמה מתחבר י\"ה ולכן אמר בסש\"ב<sup data-n=\"724\">4</sup> שהתורה היא בחי' תשובה, ונק' מלמעלמ\"ט כי זהו ע\"י התורה שהוא מלמעלמ\"ט ולא כתפילה מלמטלמ\"ע כו', ולכן שוי' למדרגת משה, א\"נ ע\"ד שניהם מתכסין בטלית א' זהו ע\"ד פב\"פ דמשה, א\"נ ע\"ד משה קבל תורה מסיני, א\"נ ערש\"מ זהו ביטול שלמעלה מהשכל שזהו כביטול דמה ונחנו מ\"ה בלי מהות כו', שזהו ביטול חכ' כח מ\"ה לאוא\"ס שלמעלה מהחכ', וכענין שלהבת הקשורה בגחלת שנת' בס\"י.",[["721","1","<b>קדש ישראל לה'</b>: הוא קיצור ורישומי דברים מד\"ה ועשו ארון דלקמן."],["722","2","<b>והענין ברכו בתורה</b>: פיסקא זו ליתא לקמן בהמאמר ד\"ה ועשו ארון. וראה גם לעיל ד\"ה אז ישיר."],["723","3","<b>כמ\"ש בת\"א בד\"ה זכור</b>: פ' יתרו דף עא, ב-ג."],["724","4","<b>בסש\"ב</b>: שעהיוה\"א ספ\"ח (צח, ב). ופ\"י (צט, א)."]]],[2000510257,"<h3>ועשו ארון</h3>\n<b>בס\"ד.</b>\n<b>ועשו</b> ארון עצי שיטים<sup data-n=\"725\">1</sup> אמתים וחצי כו' ואמה וחצי כו', וארז\"ל יומא ד\"ג ע\"ב כתוב אחד אומר ועשית לך ארון עץ<sup data-n=\"726\">2</sup> וכתוב אחד אומר ועשו ארון עצי שיטים הא כיצד כאן בזמן שישראל עושי' רצונו של מקום, וכאן בזמן שאין ישראל עושי' רצוש\"מ, ופי' רש\"י ז\"ל בזמן שישראל עושי' רצוש\"מ נק' עבודה על שמם, והמהרש\"א פי' בהיפך שי\"ל שבזמן שעושי' רצוש\"מ נחשב מלאכתן כאילו עשאן משה ובזמן שאין עושי' רצוש\"מ לא נחשב מלאכתן, ונקראת על שמן<sup data-n=\"727\">3</sup> כאילו עושי' מלאכה בעלמא.\n<b>ולהבין</b> זה יובן בהקדם מ\"ש קדש ישראל לה'<sup data-n=\"728\">4</sup> ראשית תבואתה הכתי' הוא בה' לבסוף והקרי בחולם כאילו הי' נכתב בוא\"ו<sup data-n=\"729\">5</sup> והיינו כי יש ב' בחי' תבואה בכלל שהוא חטה ושעורה, והם תבואת ה' ותבואת וא\"ו, ה' הוא בחי' בהבראם בה\"א בראם שהוא בחי' מקור כל השתלשלות העולמות שנודע שכל מקור בחי' ההשתלשלות הוא מבחי' ה' דבהבראם שהוא אתא קלילא דלית בי' ממשא, והיינו שהבל הלב היוצא ע\"י מבטא ה' היא היותר פחות ולית בי' מששא<sup data-n=\"730\">6</sup> כלל, והנה כל ביטול המלאכי' הוא בבחי' זו, שע\"ז אמרו ע\"פ נודע בשערי' בעלה כל חד לפום",[["725","1","<b>ועשו ארון עצי שיטים</b>: המאמר מיוסד על ד\"ה זה באוה\"ת תרומה ע' א'תמג (סעי' ג). חלק מהמאמר הוא מד\"ה קדש ישראל בסה\"מ תר\"ל ע' רה. וע' רז ואילך.\nתוכן המאמר נמצא בשינויים והוספות בד\"ה זה: בסה\"מ תרס\"ב ע' רפד ואילך. פר\"ת ע' רעא ואילך. תרפ\"ז ע' קט [שם נמצא רק התחלת המאמר]. חלק מהמאמר נמצא בשינויים בד\"ה שמח תשמח תרל\"ז (הנחה בגוכי\"ק בנו כ\"ק אדמו\"ר מהורש\"ב נדפסה בס' תורת שמואל דרושי חתונה ע' קפ ואילך).\nלכמה מעניני המאמר ראה לעיל ד\"ה אז ישיר [ובהנסמן שם בתחילת המאמר. לקמן ד\"ה שמח תשמח [ובהנסמן שם בתחילת המאמר]. וראה לעיל ד\"ה קדש ישראל שהוא קיצור ורישומי דברים מהמאמר."],["726","2","<b>כתוב א' אומר ועשית לך ארון עץ וכתוב א' אומר ועשו ארון</b>: ראה פירש\"י עה\"פ ועשית לך ארון עץ (עקב י, א): ולא זה הוא הארון שעשה בצלאל כו'. עיי\"ש. וראה תוס' חולין צב, א ד\"ה ברוך: אע\"פ שהי' ארון אחר מסתמא כמו שהי' זה כך הי' זה. וראה אודות הדיעות אם הי' ארון אחד או ב' ארונות בהנסמן ע\"ז בתורת שלמה תרומה כה, י (ע\"פ ועשו ארון) סי' צה-ו."],["727","3","<b>והמהרש\"א פי'. . לא נחשב מלאכתן ונקראת על שמן</b>: כ\"ה ל' המהרש\"א בחדושי אגדות ליומא שם, והלשון אינו מחוור כ\"כ, ובדפוסי ווילנא נדפס (עם הוספות בין חצאי ריבוע): לא נחשב מלאכתן [כאילו עשאן משה] ונקראת על שמן."],["728","4","<b>ולהבין זה יובן בהקדם מ\"ש קדש ישראל לה'</b>: בהבא לקמן (עד פיסקא: והנה מזה משמע) הוא חלק (בקיצור) מד\"ה קדש ישראל בסה\"מ תר\"ל שם ע' רה וע' רז ואילך. [ונדפס גם (בשגגה) באוה\"ת פינחס ע' ריב ואילך]. ובשינויים בד\"ה כי תבואו גו' ושבתה שם ע' קלג ואילך. בהבא לקמן ראה אוה\"ת משפטים ע' א'קעח ואילך. שם ע' א'קפט. סה\"מ מלוקט ח\"ה ע' קעא. וראה גם תו\"א שמות נד, ב. שם, סע\"ג. סה\"מ תרכ\"ט ע' שיג."],["729","5","<b>והקרי בחולם כאילו הי' נכתב בוא\"ו</b>: בד\"ה זה פר\"ת מעיר ע\"ז: ואינו קרי וכתיב, רק שהניקוד הוא כאילו כתוב וא\"ו."],["730","6","<b>מקור בחי' ההשתלשלות. . ה' דבהבראם. . אתא קלילא דלית בי' מששא</b>: ראה בארוכה לקו\"ת האזינו עד, ד. אוה\"ת אמור (כרך ג) ע' תתנב ואילך. וראה גם לקו\"ת במדבר י, א. ועוד."]]],[2000510258,"שיעורא דילי' לפום מאי דמשער בלבי'<sup data-n=\"731\">7</sup>, שבזה ובהתבוננות זו הוא בחי' ביטול כל הנבראי' מלאכי' ונשמות כל חד לפי ערך השגתו בחי' ההארה המחי' ומהוה כל העולמות וממילא מושג בביטולם איך שנתהוו מאין שהוא בחי' הארה בעלמא, וזהו ענין שעורה שהוא שיעור ה'<sup data-n=\"732\">8</sup>, פי' כי כל האותיות דע\"מ הם נלקחי' בשרשן מן אות ה'<sup data-n=\"733\">9</sup> שהוא מקור כולם, שזהו ענין בה' בראם כללות כולם, וכל נברא יש לו אות פרטי המחי' אותו אם מהאותיות דע\"מ או מחילופיהן ותמורותיהן כנודע ממ\"ש בפרד\"ס ועה\"מ בענין רל\"א שערי' המתגלגלי' פנים ואחור וכמ\"ש בסש\"ב ח\"ב<sup data-n=\"734\">10</sup>. ונמצא כי פי' שעורה שיעור ה' יתפרש לשני פי'<sup data-n=\"735\">11</sup> הא' הוא השיעור מן הה\"א שהוא המקור להתהוות הנברא, וזהו שיעור ה', הב' כל א' לפי ערך חלקו אשר יגיע לו מן הה\"א לפי ערך זה הוא ההתבוננות שלו בבחי' ביטול העולמות לאלקות המהוה אותם, וזה הי' עבודה ראשונה בצאת בנ\"י ממצרי', שבעת היותם במצרי' היו מושקעי' במ\"ט שע\"ט, ובצאתם ממצרי', הנה ענין יציאתם מתוך ההסגר הוא המיצר דמצרים מיצר מי שבחי' ההתבוננות דבחי' מי היינו מי ברא אלה<sup data-n=\"736\">12</sup> היתה במיצר מאד, ויציאתם מן המיצר הוא שהרגישו בנפשם ענין ההתבוננות איך שמי ברא בחי' אלה כו' שז\"ע בחי' יצ\"מ לצאת מן המיצר ולהתבונן בבחי' מי ברא אלה הוא בחי' ההתבוננות בבחי' שעורה שיעור ה' הנ\"ל כו', ולכן חגה\"פ הוא בחדש האביב ואם אין השעורה אביב<sup data-n=\"737\">13</sup> מעברין את השנה, והיינו כי זה עבודה ראשונה אשר עבדו את אלקינו ית' שזהו בחי' השיעור שכל א' משער בליבי' לפ\"ע עבודתו, וזהו בחי' התבואה דתבואתה תבואת ה' היינו בחי' השעורה שיעור ה' כו'.\n<b>ושבועות</b> הוא בחי' תבואת וא\"ו<sup data-n=\"738\">14</sup> הוא בחי' אילנא דחייא בחי' כי האדם עץ השדה זאת התורה אדם הוא התורה שנק' אדם, רמ\"ח פקודין הם רמ\"ח",[["731","7","<b>נודע בשערים בעלה כל חד. . לפום מאי דמשער בלבי'</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת שופטים ע' תתכג-ד. סה\"מ תרכ\"ט ע' שיט ואילך. תרפ\"א ע' שב ואילך. תרצ\"ט ע' 244 ואילך. וראה גם לקו\"ת במדבר א, א."],["732","8","<b>וזהו ענין שעורה. . שיעור ה'</b>: ראה בארוכה לקו\"ת במדבר י, ב. יא, א. שם, ב."],["733","9","<b>שעורה. . שיעור ה' פי' כי כל האותיות. . נלקחי' בשרשן מן אות ה'</b>: ראה ד\"ה זה פר\"ת: ענין שעורה שיעור ה' הוא שאות ה' הגם שההבל שבו הוא במיעוט יותר, מ\"מ צ\"ל משוער בבחי' צמצום הן בבחי' צמצום כללי והן בבחי' צמצום פרטי, דצמצום הכללי הוא שנתעלם בחי' הפנימיות ונמשך רק בחי' חיצוניות ההבל, ואח\"כ הוא הצמצום דה' גבורות מנצפ\"ך שהן מחלקים את חיצוניות ההבל בהברות מתחלקות בביטוי הכ\"ב אותיות שמהן נעשה ריבוי צירופים וחילופים ותמורות."],["734","10","<b>וכמ\"ש בסש\"ב ח\"ב</b>: שעהיוה\"א פ\"א (עז, א)."],["735","11","<b>פי' שעורה שיעור ה' יתפרש לשני פי'</b>: ראה עד\"ז (ב' פירושים ב”נודע בשערים\": ל' שיעור וגבול, ול' השערה) בסה\"מ תרכ\"ט שם ס\"ע שיט-כ. וראה ד\"ה זה תרס\"ב: [פי' הא'] שיעור ה' היינו השיעור והמדה שנמשך מבחי' ה\"א בכל אות ואות להוות ולהחיות את הנבראים, וגם פי' שיעור ה\"א הוא כל חד וחד לפום מאי דמשער בלבו הוא ערך ההשגה וההתבוננות בבחי' הה\"א שהוא ההארה מקור הנבראים שלפ\"ע זה הוא ביטולו כו', והא בהא תליא, דלפ\"ע השיעור והמדה מבחי' ה\"א שמגיע לחלקו להוות ולהחיות מציאותו לפי אופן זה הוא השגתו וביטולו כו' [ועיי\"ש מ\"ש עוד בזה]."],["736","12","<b>המיצר דמצרים מיצר מי. . מי ברא אלה</b>: ראה בארוכה סה\"מ תרכ\"ז ע' שסז ואילך. [ובהנסמן שם בתחילת המאמר]. וראה גם תו\"א וארא נח, ב ואילך. יתרו עא, ד."],["737","13","<b>ואם אין השעורה אביב</b>: ע\"פ ל' הכתוב וארא ט, לא: כי השעורה אביב. וראה בארוכה אוה\"ת משפטים שם ע' א'קפ."],["738","14","<b>ושבועות הוא בחי' תבואת וא\"ו</b>: בהבא לקמן בפיסקא זו ראה בארוכה סה\"מ תר\"ל שם ע' קלד. וע' רט-י."]]],[2000510259,"איברין דמלכא<sup data-n=\"739\">15</sup> בחי' אדם, והוא בחי' אות אמת כמ\"ש ונתתם לי אות אמת ופי' בזהר דא אות וא\"ו, אילנא דחייא כו', וזהו בחי' התבואה דתבואתה לפי הניקוד שהוא בחולם כאילו הי' כתו' בוא\"ו, וישראל הם ראשית התבואה שהם ראשית דתבואת ה' ותבואת וא\"ו.\n<b>והנה</b> מזה משמע דישראל הם גבוה יותר<sup data-n=\"740\">16</sup> מבחי' תומ\"צ שהרי הם הנק' ראשית לבחי' התבואה דתומ\"צ, וכן ארז\"ל ע\"פ תורה ציוה לנו משה מורשה א\"ת מורשה אלא מאורסה שהתורה היא בחי' כלה ארוסה לנש\"י שנק' בשם חתן<sup data-n=\"741\">17</sup>, ופעם אמרו בזהר ישראל מתקשראין באורייתא ואורייתא בקוב\"ה, שמשמע שע\"י התורה מתקשראין נש\"י לאלקות. אך הענין הוא דהנה נש\"י כמו שנתלבשו בגוף ונה\"ב הנה בכדי שיתחברו נש\"י לאלקות זהו ע\"י התורה, וזהו ישראל מתקשראין באורייתא ע\"י התורה דהנה תלת קשרין שמתקשרין דא עם דא<sup data-n=\"742\">18</sup> ישראל מתקשראין באורייתא ואורייתא בקוב\"ה וכולהו דרגין על דרגין סתי' וגלי' והיינו שע\"י הסתים דתורה מתקשר סתי' שבנש\"י לסתים דקוב\"ה, וע\"י הגלי' דתורה מתקשר גלי' שבישראל לבחי' גלי' דקוב\"ה, או י\"ל שע\"י גלי' דתורה<sup data-n=\"743\">19</sup> מתקשר סתים שבתורה לבחי' גלי' דקוב\"ה, ונמצא כי סתים וגלי' שבתורה הם הממוצעי' בין קוב\"ה לישראל שעי\"ז מתקשרין נש\"י לאלקות. אמנם הנה כ\"ז הוא מדרגת ישראל בחי' הנשמה המלובשת בגוף, אבל מצד בחי' שורש ומקור הנשמה הנה נש\"י נק' חתן והתורה נק' כלה להיות ישראל ממשיכי' בחי' שורש ומקור התורה בתורה, ועד\"מ תורה שלומדי' בג\"ע דהיתכן לומר שלומדי' שם הלכה שני' אוחזין בטלית או המחליף פרה בחמור כמו שהוא למטה, שאין שייך שם כלל ענין הטלית ופרה",[["739","15","<b>תבואת וא\"ו. . זאת התורה אדם. . רמ\"ח פקודין הם רמ\"ח איברין דמלכא</b>: ראה ד\"ה זה פר\"ת: וזהו\"ע זאת התורה אדם דרמ\"ח פקודין רמ\"ח אברין דמלכא כו', וכמו עד\"מ בגוף הרי בחיות הנפש מאיר גילוי אור הנפש יותר ומיוחד יותר מבדיבור, שבדיבור אור הנפש מצומצם שם והדיבור נעשה נפרד מהאדם, משא\"כ הגוף מיוחד כו', כמו\"כ הוא בתורה שמאיר בה גילוי אוא\"ס כו'."],["740","16","<b>והנה מזה משמע דישראל הם גבוה יותר</b>: בהבא לקמן (עד פיסקא: ועפ\"ז יובן מה שנש\"י) ראה ד\"ה יונתי בחגוי וביאוריו בלקו\"ת שה\"ש טז, ד ואילך. יח, ב. יט, ב ואילך. [הובא בד\"ה ועשו ארון באוה\"ת תרומה שם]. לעיל ד\"ה אז ישיר. וש\"נ. לקמן ד\"ה שמח תשמח."],["741","17","<b>שהתורה. . כלה ארוסה לנש\"י. . חתן</b>: ראה גם תו\"א שמות שם נד, א. תצוה פב, ד [הובא בד\"ה ועשית ארון באוה\"ת תרומה שם]. סה\"מ תרל\"ד ע' מ. תרל\"ה ח\"ב ס\"ע תמז. תרל\"ח ע' קנה. וש\"נ. ובכ\"מ."],["742","18","<b>תלת קשרין שמתקשרין דא עם דא</b>: ראה לעיל ד\"ה אז ישיר. וש\"נ."],["743","19","<b>שע\"י הסתים דתורה מתקשר סתים שבנש\"י. . או י\"ל שע\"י גלי' דתורה</b>: אודות ב' פירושים אלו ראה גם סה\"מ תרל\"ג ח\"ב ע' תמג. המשך תרס\"ו ע' שפה-ו. תער\"ב ח\"ב ע' תשמו-ז. ד\"ה זה היום (די\"ט כסלו) תשד\"מ. ועוד. — פי' הב' הובא כאן בקיצור, וראה לעיל ד\"ה אז ישיר: או י\"ל שבחי' סתים שבנש\"י מתחבר עם בחי' גליא דתורה, וע\"י בחי' סתים דתורה מתחבר לבחי' גליא דקוב\"ה, ונמצא כי סתים וגליא דתורה הם הממוצעים בין סתים דנש\"י לבחי' גליא דקוב\"ה."]]],[2000510260,"וחמור, אלא שלומדי' שם רוחניות שבההלכה<sup data-n=\"744\">20</sup>, ונש\"י הם הממשיכי' בחי' הרוחניות שבתורה שתתלבש בגשמיות ההלכה. או י\"ל ע\"ד דוד הי' מחבר תורה שלמעלה בהקב\"ה<sup data-n=\"745\">21</sup> שהוא בחי' המשכת אוא\"ס ב\"ה בתורה שלמעלה, שמצד בחי' זו נש\"י נק' חתן ע\"ש ההשפעה והתורה נק' כלה ע\"ש קבלתה מנש\"י. ועפ\"ז יובן מה שנש\"י נק' ראשית תבואתה שמצד בחי' זו שנש\"י ממשיכי' המשכת אוא\"ס ב\"ה בתורה, ושעי\"ז מתעלי' נש\"י לאשתאבא בגופא דמלכא שהוא העלי' מבחי' פנימיות הכלי' שורש ומקור נש\"י לבחי' האורות, שזהו כל ענין ירידת הנשמה בגוף כמ\"ש מזה במ\"א<sup data-n=\"746\">22</sup>, ונמצא שהם ראשית מבחי' התבואה<sup data-n=\"747\">23</sup> שהרי הם נוטלי' חלק בראש שהרי מתעלי' לבחי' האורות כו'. וזהו שארז\"ל ע\"פ וכל בניך למודי הוי'<sup data-n=\"748\">24</sup> ורב שלום בניך א\"ת בניך אלא בוניך וכמאמר ת\"ח שעוסקי' בבנינו של עולם, ולכאו' יפלא הלא העולם בנוי ומשוכלל ומה\"ע שעוסקי' בבנינו של עולם, אך הענין הוא דהנה כתי' עשרה עשרה כף בשקל הקדש ופי' רז\"ל שעשה\"ד מכוונים כנגד עשרה מאמרות<sup data-n=\"749\">25</sup>, וע\"י עשה\"ד נמשך קיום ע\"מ, וכמארז\"ל תנאי התנה הקב\"ה עם מע\"ב אם יקיימו ישראל תורתי מוטב וא\"ל יחזיר את העולם לתהו, וכמ\"ש אם לא בריתי יומם ולילה חוקות שמי' וארץ לא שמתי, וכתי' אנכי עשיתי ארץ ואדם עלי' בראתי, שכל ענין בריאת שמי' וארץ הוא בשביל האדם שמעלתו הוא מה שמקיים תומ\"צ שלכן בראתי בגימ' תרי\"ג היינו בחי' תרי\"ג מצות אשר נצטוינו, וע\"י קיום התומ\"צ עי\"ז ממשיכי' קיום העולם, ושיומשך לע\"ל גילוי אלקות למטה כמו למעלה שמצד זה נק' ת\"ח בונים שעוסקי' בבנינו של עולם לבנות העולם ולתקנו באופן היותר נאות ומתוקן שלכן הגם שכבר נבה\"ע אמנם הנה נודע מארז\"ל העולם על מילואו נברא רק ע\"י חטא עה\"ד חסרו ו' דברים, ולתקן העולם להמשיך החסרון ועוד יתרון ותוס' בעולם זהו ע\"י עסק התומ\"צ, וגם עי\"ז נמשך תוס' וריבוי אור בתורה וכנ\"ל בענין דוד הי' מחבר תורה שלמעלה בהקב\"ה כו'.\n<b>והנה</b> ע\"י קיום התומ\"צ באופן זה שע\"י התורה ועבודה יתחבר ויומשך אוא\"ס בתורה, אז נק' הארון שבו הי' לוחות העדות מקור כל התורה על שם ישראל שזהו מ\"ש ועשו ארון עצי שיטים שישראל הם העושי' הארון שבו התורה",[["744","20","<b>תורה שלומדי' בג\"ע. . שלומדי' שם רוחניות שבההלכה</b>: ראה לקו\"ת תזריע כב, ד. סה\"מ תרל\"ה ח\"ב ע' תנא ואילך. תרל\"ח ע' קסא ואילך. וש\"נ. תרע\"ח (הוצאת תשד\"מ) ע' תטז. המשך תער\"ב ח\"א ע' שסח-ט. תרפ\"ז ע' קפז-ח. תרפ\"ט ע' 157 ואילך. תש\"א ע' 38 ואילך. תש\"ו ע' 112. תשט\"ז ע' 511 ואילך. ס\"ע 524 ואילך."],["745","21","<b>ע\"ד דוד הי' מחבר תורה שלמעלה בהקב\"ה</b>: ראה גם תו\"א תולדות יח, ג. לקו\"ת שלח מז, ג. נא, א. ובכ\"מ."],["746","22","<b>לאשתאבא בגופא דמלכא. . מבחי' פנימיות הכלי. . לבחי' האורות. . כמ\"ש מזה במ\"א</b>: תו\"א יתרו עא, א. [ד\"ה זכור את יום השבת. — הובא בד\"ה ועשו ארון באוה\"ת תרומה שם]. סה\"מ תר\"ם ח\"ב ע' תקב ואילך. תקנז. תשכג ואילך. תתסא ואילך."],["747","23","<b>ראשית מבחי' התבואה. . נוטלי' חלק בראש. ֿ. מתעלים לבחי' האורות</b>: נת' בד\"ה זה תרס\"ב: ועש\"ז נק' ג\"כ ראשית תבואתה ע\"ש שנוטלים חלק בראש, והיינו דלבד זאת שהן בבחי' ראשית לגבי התורה שמשפיעים וממשיכים בתורה, נק' ראשית ג\"כ לפי שנוטלים חלק בראש שמתעלים בהאור והן הממשיכים כו'."],["748","24","<b>וזהו שארז\"ל ע\"פ וכל בניך למודי הוי'</b>: בהבא לקמן ראה גם לקו\"ת שה\"ש שם יז, א. יח, ב [ד\"ה יונתי בחגוי הנ\"ל]."],["749","25","<b>עשרה עשרה הכף. . שעשה\"ד מכוונים כנגד עשרה מאמרות</b>: ראה בארוכה לקו\"ת חוקת נז, סע\"ג-ד. אוה\"ת יתרו ע' תתעג. שם (כרך ז) ע' ב'תרפד. שם (כרך ח) ס\"ע ב'תתקפד-ה. לקו\"ש ח\"א ע' 148. ועוד."]]],[2000510261,"להיות שישראל ממשיכי' אוא\"ס בתורה שזהו עיקר ענין עשיית התורה שהוא ע\"י לימוד התורה לשמה לשם התורה עצמה היינו בכדי שיומשך אוא\"ס ב\"ה בתורה<sup data-n=\"750\">26</sup> כו' וע\"ד שנק' התורה ע\"ש משה כמ\"ש זכרו תורת משה עבדי שנק' ע\"ש משה לפי שמסר נפשו עלי', וכמו\"כ ע\"י קיום התורה והמצות לשמה לשם התורה עי\"ז נק' התורה ע\"ש העושה והמקיים אותה. וזהו מ\"ש כי אם בתורת ה' חפצו ובתורתו<sup data-n=\"751\">27</sup> יהגה יומם ולילה, שבתחלה היא תורת הוי' אמנם ע\"י עסקו בתורה לשמה לשם התורה עצמה עי\"ז ממשיכי' אוא\"ס ב\"ה בתורה שאז נק' התורה תורתו שהיא התורה שלו, להיות כי ע\"י הלימוד לשמה ממשיכי' בתורה אוא\"ס ב\"ה שלמעלה מהתורה, ועי\"ז נעשה עילוי בתורה יותר גבוה מכמו שהי' תחלה שנתעלית עי\"ז בעילוי אחר, והרי העילוי נעשה ע\"י הלימוד שלכן נק' תורתו כו'. וזהו שהארון שבו הי' הלוחות מקור כל התורה נא' בו ועשו להיות כי ישראל ע\"י עבודתם בתומ\"צ עושי' את התורה להעלותה בעילוי אחר, ובהיפך ע\"י העדר עשיית המצות או כשעושה אותם בדרך מצות אנשי' מלומדה בקרירות כמו שאינו נוגע לו כלל, אז ע\"ז נאמר ועשית שמשה הוא העושה הארון שבו הלוחות מקור כל התורה וכמו שנק' התורה ע\"ש משה כמ\"ש זכרו תורת משה עבדי. וענין שאמר כאן משה עבדי י\"ל שע\"י מה נק' תורת משה ע\"י שהי' בבחי' עבד, שעשה רצונו ית' כעבד לאדונו בלי שום תשלום גמול ובלי טעם ודעת כ\"א בבחי' ביטול למעלה משכל המושג ועי\"ז נק' התורה על שמו כו'.\n<b>אמנם</b> עדיין צ\"ל למה תלו רז\"ל ענין קריאת עשיית הארון אם על שם בנ\"י או ע\"ש משה במה שעושין רצונו של מקום מהו ענין עושי' רצוש\"מ לקריאת שם עשיית הארון. אך הענין יובן בענין ההפרש בין פ' ראשונה דק\"ש לפ' שני'<sup data-n=\"752\">28</sup> שארז\"ל שפ' ראשונה הוא בחי' ערש\"מ ופ' שני' נק' אין ערש\"מ, שלכאו' יפלא הלא בפ' שני' נא' והי' אם שמוע תשמעו אל מצותי ואיך יקרא השומע אל מצוותיו בשם אין ערש\"מ. אך הענין הוא שבפ' ראשונה נא' בכל מאדך, ובפ' שני' לא נא' בה בכל מאדך, וענין בכל מאדך ידוע שהוא בחי' ביטול הרצון שלמעלה משכל המושג שע\"ז רומז ל' מאד שהוא בלי גבול, פי' למעלה מהגבלת הכלי אשר תוכל שאת כ\"א לצאת מכלי הגבלתו לגמרי, שזה\"ע מארז\"ל למה קדמה שמע לוא\"ש כדי",[["750","26","<b>לשמה לשם התורה. . שיומשך אוא\"ס ב\"ה בתורה</b>: ראה בכ\"ז תו\"א תצוה פב, ד. לקו\"ת בשלח א, סע\"ב. ויקרא ה, רע\"א. שלח מז, רע\"ג. מטות פו, ב. נצבים מו, ד. האזינו עג, סע\"ד. עו, א. שה\"ש יז, א. לב, ד. לעיל ד\"ה אז ישיר. ובכ\"מ."],["751","27","<b>כי אם בתורת ה'. . ובתורתו</b>: ראה גם לעיל ד\"ה אז ישיר. וש\"נ."],["752","28","<b>פ' ראשונה דק\"ש לפ' שני'. . ערש\"מ. . אין ערש\"מ. . לא נז' בה בכל מאדך</b>: בהבא לקמן ראה או\"ת להה\"מ (הוצאת קה\"ת) פ' עקב נג, סע\"ג-ד. לקו\"ת שלח מב, ג. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרעט. תקס\"ט ע' קלה. אמ\"ב שער הק\"ש עב, סע\"ג. שערי תשובה ח\"ב נא, ב. סא, סע\"ג ואילך. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתכה. הנחות תקע\"ז ע' רפו. אוה\"ת עקב ע' תפא. תצב. נ\"ך (כרך ב) ס\"ע תתנג. סה\"מ תרכ\"ט ע' קצז ואילך. המשך מים רבים תרל\"ו ע' קלז ואילך. ובארוכה המשך תרס\"ו ע' כט-לו. נה-נו. לקו\"ש חי\"ב ע' 98 ואילך. וש\"נ."]]],[2000510262,"שיקבלו עליהם עומ\"ש תחלה<sup data-n=\"753\">29</sup> ואח\"כ יקבל עליו עול מצות שענין הקב\"ע מ\"ש זהו כענין הקדמת נעשה לנשמע, שענין ביטול דנעשה מורה שנעשה כל מה שתצוה אלינו, ולא שמקבלי' על עצמם מחמת כי כבר שמעו הציוים שביכולתם לשאת, אלא כל מה שתצוה אלינו לעשות נעשה והדר נשמע איך לעשות, ממילא מובן ג\"כ שענין הקבלה דנעשה הוא קבלה בכלל, שהרי אינם יודעי' עדיין מה לעשות שזהו שאמרו אח\"כ נשמע היינו שנשמע הדבר בפרטיות מה שצריך לעשות מובן כי קודם ששמעו הציוי מה לעשות א\"י כלל מה לעשות, ומהו שאמרו נעשה היינו הביטול בכלל לאוא\"ס בעל הרצון מקור כל הרצונות פרטי' דציויי המצות אמרו לו נעשה כל מה שתצוה ותגזור עלינו, ונמצא כי ביטול זה דנעשה מאחר שאינו ברצון פרטי ה\"ה ביטול שלמעלה מהגבלת כלי פרטי כ\"א ביטול כללי שלמעלה מהכלי' והחושי' פרטי' וה\"ה כמו הביטול שלמעלה מהשכל המושג שהרי עדיין לא ידעו בשכלם כלל וכלל מהו הציוים פרטי' אשר יצוה אותם כ\"א הגיעו בביטול זה למעלה משכל המושג, ומה גם כי ענין ביטול כזה שא\"י עדיין ע\"פ שכל מה יצוה הרי זהו למעלה מן השכל כי השכל אינו מחייב עדיין לעשיות הדבר ההוא, ונמצא כי הביטול לעשות הוא למעלה משכל המושג עדיין, רק שי\"ל שמשיג ע\"פ שכל שצריך לבטל רצונו<sup data-n=\"754\">30</sup> מפני רצון העליון וכ\"ש לפני בעל הרצון, רק מ\"מ ה\"ז רק הגורם לבוא לבחי' ביטול רצון זה, אבל מיד כשמגיע לעצם ביטולו אז הוא למעלה מן השכל לגמרי ואין השכל פועל בו אז<sup data-n=\"755\">31</sup>, וגם אינו מושג אז כלל ע\"פ שכל כו'. והנה ביטול זה שלמעלה מן השכל כוחו גדול מאד שעי\"ז מקשר שכל עם בחי' אוא\"ס שלמעלה מן השכל, שהרי האדם שהוא בר שכל בעצם בא והולך ע\"פ השכל עד שמגיע למעלה מהשכל כו' ונמצא כי מתקשר שכל עם למעלה מהשכל, וממילא נמשך מבחי' אוא\"ס שלמעלה מהשכל והרצון לבוא לבחי' רצון. וז\"ע עושין רצונו ש\"מ פי' שעושי' לו רצון, היינו שמלמעלה מהרצון הוא בחי' אוא\"ס ב\"ה בעהר\"צ יומשך להיות רצון פרטי דתומ\"צ, שבאמת אוא\"ס ב\"ה הוא למעלה מהרצון ואינו תופס מקום אצלו כלל כל הרצון דתומ\"צ כמ\"ש אם חטאת כו' ורבו כו' אם צדקת כו' וכחשיכה כאורה בשני כפין<sup data-n=\"756\">32</sup> שגם האור שוה לחשך אלא שע\"י ביטול דנעשה לאוא\"ס בעהר\"צ המשיכו הרצון דפרטיות המצות, והגם כי אין זה בדרך העלאת מ\"ן מ\"מ ה\"ה בדרך כלי לקבל ושיומשך מאוא\"ס בעהר\"צ להיות רצון פרטי שז\"ע ערש\"מ כו', ולכן בזמן שישראל עושין רצוש\"מ שהוא בחי' פ' ראשונה דק\"ש מס\"נ למס\"נ באחד ובכל מאדך בלי גבול עי\"ז עושין רצוש\"מ פי'",[["753","29","<b>למה קדמה שמע כדי שיקבל עליו עומ\"ש תחלה. . כענין הקדמת נעשה לנשמע</b>: בהבא לקמן ראה סה\"מ תרכ\"ט ע' רב. [ובהנסמן שם בתחילת המאמר]. רמו. רנג-ד. ערה. ובכ\"מ."],["754","30","<b>רק שי\"ל שמשיג ע\"פ שכל שצריך לבטל רצונו</b>: בד\"ה זה תרס\"ב מוסיף: וי\"ל שז\"ע הבחירה מה שהאדם הוא בעל בחירה, די\"ל שגם בביטול כזה יש ענין הבחירה והוא מה שהשכל מסכים שצריך להתבטל כו'."],["755","31","<b>כשמגיע לעצם ביטולו. . ואין השכל פועל בו אז</b>: בד\"ה זה תרס\"ב מוסיף: שאם הי' אז פעולת השכל לא הי' הביטול שאין בחוש השכל ביטול כזה, ורק שהשכל מסכים שצ\"ל ביטול כזה, אבל א\"א שיהי' מצד השכל כ\"א צ\"ל בזה ביטול השכל לגמרי כאילו אינו כו'. [עיי\"ש בארוכה הדוגמא ע\"ז מענין המס\"נ על קידוש ה']."],["756","32","<b>וכחשיכה כאורה בשני כפי\"ן</b>: ראה לקו\"ת צו יב, א. סה\"מ תרל\"ב ח\"א ע' קכח. תרל\"ה ח\"ב ע' שעו. ועוד."]]],[2000510263,"שיומשך בבחי' הרצון פרטי ואז תופס מקום תומ\"צ וממילא עי\"ז מקשרין בחי' תורה לבחי' אוא\"ס שלמעלה מבחי' התורה.\n<b>דהנה</b> כתי' ועל דמות הכסא דמות כמראה אדם<sup data-n=\"757\">33</sup> עליו מלמעלה, ונודע כי אוא\"ס ב\"ה הוא למעלה מבחי' אדם, ונודע ג\"כ כי התורה הוא בחי' אדם כמ\"ש זאת התורה אדם, שכלול מג' קווין שהם בחי' תורה ועבודה וגמ\"ח, גמ\"ח קו הימין, עבודה קו השמאל, ותורה קו האמצעי, שכ\"ז הוא בחי' אדם. ובכדי להעלות התורה<sup data-n=\"758\">34</sup> ולקשרה באוא\"ס ב\"ה ממש שלמעלה מבחי' אדם, כי לא אדם הוא, זהו ע\"י ישראל שהם בני אברהם יצחק ויעקב בחי' האבות הן הן המרכבה, וירושה זו היא לנו מאבותינו התשוקה והצמאון להבטל ולהכלל באוא\"ס ב\"ה ממש, וניתן לנו כח זה במ\"ת שאנו נעלה וננשא את בחי' אדם ג' קווין בחי' אדם לבחי' כי לא אדם הוא, ובנו וע\"י יומשך גילוי אוא\"ס ב\"ה שלמעלה מבחי' אדם בעסק תורתינו ועבודתינו בקיום המצות שהם בבחי' אדם. וזהו אנכי ה' אלקיך שבחי' אנכי מי שאנכי נמשך להיות אלקיך אלקי' שלך, זהו ע\"י צמצום דש' הוי' כו', כמ\"ש כ\"ז בת\"א בד\"ה זכור את יום השבת בפ' יתרו<sup data-n=\"759\">35</sup>, דרוש השני. ונמצא כי מובן מארז\"ל שדוקא בזמן שישראל עושי' רצוש\"מ כנ\"ל שע\"י ביטולם ממשיכי' להיות לו רצון פרטי ואז נק' הארון שבו לוחות העדות מקור כל התורה נק' על שמן ועשו ארון עצי שיטי' שישראל הם העושי' הארון אשר בו לוחות העדות מקור כל התורה, ובזמן שאין עושי' רצוש\"מ נא' ועשית שמשה הוא העושה כו'.\n<b>אמנם</b> הנה כ\"ז הוא לפי' הפשוט שבגמ' הנ\"ל, אכן לפי' המהרש\"א בח\"א שכאשר עושי' רצוש\"מ שוה מלאכתן כאילו עשאן משה, והיינו כי משה הי' בחי' ד\"ע, ולכן בלעם לעו\"ז דמשה<sup data-n=\"760\">36</sup>, שבאו\"ה קם, נא' בו ויודע דעת עליון, וע\"י בחי' התורה עם ביטול זהו בחי' תשוב ה' עילאה לגבי יו\"ד, ולכן כמו שד\"ע דמשה מחבר חו\"ב כן ע\"י לימוד התורה לשמה, מה להלן באימה וביראה אף כאן באימה וביראה, מקשרין ומחברין י\"ה והרי שוה מלאכתן למלאכת משה היינו בחי' עבודת משה, ומה שתלו זה בענין עושי' רצוש\"מ היינו כנ\"ל שע\"י העבודה דנש\"י מתקשר התורה לבחי' אוא\"ס שהוא בבחי' כי לא אדם הוא כו', ועי\"ז נמשך מאוא\"ס שלא אדם בבחי' התורה שנק' אדם כו', ולכן נק' התורה בסש\"ב בשם תשובה שהוא בחי' תשוב ה' לגבי יו\"ד רק שזהו מלמעלמ\"ט<sup data-n=\"761\">37</sup> ולא כמדריגת התפילה שהיא מלמטלמ\"ע כו' כי כל עיקר מעלת התורה הוא מלמעלמ\"ט, וע' בד\"ה זימנא חדא<sup data-n=\"762\">38</sup> הוי צריכא",[["757","33","<b>דהנה כתי' ועל דמות הכסא דמות כמראה אדם</b>: בהבא לקמן ראה תו\"א יתרו עא, ב. [ד\"ה זכור את יום השבת. — הובא בד\"ה ועשו ארון באוה\"ת תרומה שם]."],["758","34","<b>ובכדי להעלות התורה</b>: בהבא לקמן עד סוף הפיסקא ראה תו\"א יתרו שם עא, סע\"ב-ג [והוא ע\"פ לשון התו\"א שם בשינויים והוספות]."],["759","35","<b>בת\"א בד\"ה זכור. . בפ' יתרו</b>: שם דף עא, ב-ג."],["760","36","<b>בלעם לעו\"ז דמשה</b>: ראה אוה\"ת בלק ע' תתקא. סה\"מ תרכ\"ט ע' רסו. ערב. המשך תער\"ב ח\"א ע' תקמח."],["761","37","<b>נק' התורה בסש\"ב בשם תשובה. . רק שזהו מלמעלמ\"ט</b>: ראה שעהיוה\"א ספ\"ח (צח, ב). ופ\"י (צט, א)."],["762","38","<b>בד\"ה זימנא חדא</b>: סה\"מ תרכ\"ז ע' רצב ואילך."]]],[2000510264,"עלמא למיטרא בענין מה שרצה משה לכנוס לארץ<sup data-n=\"763\">39</sup> היינו שרצה להנחיל לישראל שיהי' עבודתם בבחי' מלמעלמ\"ט כו' ושזהו ענין וחיי עולם שמברכין על התורה, ולכן רשב\"י שהי' תורתו אומנתו כשדרש דרוש ע\"פ הנה מה טוב ומה נעים שבת אחי' גם יחד ירדו גשמי', הרי השפיע הגשם מלמעלמ\"ט ע\"י לימוד תורתו שזהו מדריגת משה, שלכן רצה לכנוס לארץ להמשיך הכח בכל ישראל כן, ולא פעל זה כ\"א לראות מרחוק, וע\"י הראי' מרחוק פעל שמי שתורתו אומנתו יהי' יכול בלימוד תורתו להמשיך כן כו'. ומאחר שע\"י לימוד התורה בבחי' תורתו אומנתו יכול להמשיך כמו משה שז\"ע ע\"י עושי' רצוש\"מ ג\"כ כענין רשב\"י שאמר בחד קטירא אתקטרנא בי' אחידא בי' להיטא כו', ולכן כשישראל הם במדריגה כזו נחשב מלאכתן כאילו עשאן משה הכוונה שנק' הארון על שמם להיות כי בכח תורתן יכולי' להמשיך כל ההשפעות ע\"י התורה כו'. או י\"ל שע\"י לימוד כב\"י שניהם מתכסין בלבוש א'<sup data-n=\"764\">40</sup> שזהו כענין מ\"ש במשה פא\"פ כו' שלמעלה מבחי' פב\"פ שנא' בכלליות ישראל, שפי' הרמ\"ז<sup data-n=\"765\">41</sup> שפב\"פ הוא בחי' התלבשות פנים העליון בפנים התחתון, ופא\"פ הוא בחי' הארת פנים העליון עצמו כו'. או י\"ל שזהו ע\"ד משה קיבל תורה מסיני כן כשלומד תורה בבחי' ביטול עד שבטל לבעהר\"צ שוה כאילו קבלה מסיני כו' כמו משה. או י\"ל שע\"י בחי' הביטול שלמעלה מהשכל שנת\"ל זהו כענין ונחנו מ\"ה בחי' מ\"ה דחכ' שעש\"ז נק' חכמה כח מ\"ה ונת' בפרד\"ס שתי' כח שבחכ' הוא לרמז על התיחדותה עם הבינה, ומ\"ה שבתי' חכ' הוא בחי' ביטולה להכתר<sup data-n=\"766\">42</sup> שז\"ע כבחי' הביטול שלמעלה מן החכ' שעי\"ז ערש\"מ ונמצא כי אז חשוב מלאכתן כאילו עשאן משה כו'.",[["763","39","<b>שרצה משה ליכנס לארץ. . להנחיל לישראל. ֿ. בבחי' מלמעלמ\"ט</b>: ראה בכ\"ז לקו\"ת ואתחנן ב, סע\"ג ואילך. ג, ג ואילך. סה\"מ תרל\"ג ח\"ב ע' תכג. [ובהנסמן שם בתחילת המאמר]."],["764","40","<b>שע\"י לימוד כבי' שניהם מתכסין בלבוש א'</b>: ראה לקו\"ת אחרי כז, ב. אוה\"ת נ\"ך (כרך ב) ע' תתקב. סה\"מ תרל\"ג ח\"א ע' קיא."],["765","41","<b>פא\"פ כו' שלמעלה מבחי' פב\"פ. . שפי' הרמ\"ז</b>: ראה אוה\"ת ואתחנן ע' קצב ואילך. [ונדפס עוה\"פ שם (כרך ה) ע' ב' ואילך]. המשך תער\"ב ח\"ג ע' א'קמז. סה\"מ עטר\"ת ס\"ע תקעט ואילך. תרצ\"ז ע' 273 ואילך. ד\"ה פנים בפנים תרצ\"ג."],["766","42","<b>כח מ\"ה. . כח שבחכ'. . עם הבינה. . ומ\"ה. . ביטולה להכתר</b>: ראה בארוכה המשך וככה תרל\"ז פכ\"ה (ע' כט). ופל\"ב (ע' מג). לקמן ד\"ה כי הנה יוצר הרים. המשך והחרים ד\"ה משכיל לאיתן האזרחי. ועוד."]]],[2000510265,"<b>ועוי\"ל</b> כי הנה משה משה לא פסיק, משא\"כ כל ישראל אינו דומה שורשו שלמעלה לנשמתו המלובש בגוף שהרי אפי' באברהם אמרו אברהם אברהם פסיק טעמא<sup data-n=\"767\">43</sup> כו', אמנם ע\"י הביטול הרצון מכל וכל לאוא\"ס ב\"ה בעהר\"צ עי\"ז הגיעו כולם למדריגת משה שלא יהי' פסיק טעמא כו' ולכן חשוב מלאכתן כאילו עשאן משה כו'.",[["767","43","<b>משה משה לא פסיק טעמא. . אברהם אברהם פסיק טעמא</b>: ראה לעיל ד\"ה וכל העם. וש\"נ."]]],[2000510266,"<h3>שמח תשמח</h3>\n<b>בס\"ד.</b>\n<b>שמח</b> תשמח<sup data-n=\"768\">1</sup> ריעים כו' כשמחך יצירך בג\"ע. ולכאורה יפלא הלא הבריאה יש מאין הנה היא ירידה צורך עלי', ומה\"ע כשמחך יצירך בג\"ע<sup data-n=\"769\">2</sup>. [וגם צ\"ל מה\"ע שמח תשמח ריעים האהובים<sup data-n=\"770\">3</sup>, דהנה נודע ממ\"ש במ\"א בענין אכלו ריעים לעילא<sup data-n=\"771\">4</sup> שקאי על חכ' ובינה, ונודע כי השמחה היא בבינה כמ\"ש אם הבנים שמחה<sup data-n=\"772\">5</sup>, אבל אבא הוא למעלה מן השמחה, ולכן רק מועדים לשמחה, אבל שבת מוחין דאבא הוא מנוחה ועונג<sup data-n=\"773\">6</sup> כמ\"ש וקראת לשבת עונג, וא\"כ צ\"ל ענין אומרו שמח תשמח דמשמע שמח בעצמו, ותשמח שתפעול השמחה גם בריעים הוא חכ' ובינה, שנמצא מצד עוצם הגילוי גם החכ' תהי' שמחה כו' וצ\"ל מהו].\n<b>אך</b> הענין יובן ע\"פ מה שנת' בד\"ה אז ישיר דאגוסטוס<sup data-n=\"774\">7</sup>, וד\"ה ועשו ארון<sup data-n=\"775\">8</sup>, שפעם נק' כנס\"י חתן אל תקרי מורשה אלא מאורסה, ופעם אמרו ישראל מתקשראין באורייתא, [ביום חתונתו זו מתן תורה, נמצא כי כנס\"י נק' כלה. והענין הוא דשניהם אמת, דהנה איתא בזהר תלת קשרין מתקשראן דא בדא<sup data-n=\"776\">9</sup> ישראל ואורייתא",[["768","1","<b>שמח תשמח</b>: חלק מהמאמר (פיסקא: אך הענין יובן, ופיסקא שלאחרי') נמצא בארוכה לעיל בד\"ה ועשו ארון [וראה בהנסמן שם בתחילת המאמר]. ולעיל ד\"ה אז ישיר [ובהנסמן שם].\nמאמר זה נמצא ג\"כ בבוך כת\"י דרושי חתונה מכ\"ק אדמו\"ר מהר\"ש, ונוספו עליו כמה הגהות בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש [ולשלימות הענין נדפסו כאן בין חצאי ריבוע], ונדפס (עם ההגהות) בס' תורת שמואל דרושי חתונה (קה\"ת תשס\"ג) ע' סז ואילך. ובסה\"מ תרל\"ה ח\"ב ע' תכד ואילך (בעת חתונת בנו כ\"ק אדמו\"ר מהורש\"ב נ\"ע). הנחת השומעים מהמאמר דתרל\"ה נדפס שם ע' תקמב ואילך. ובד\"ה זה תרל\"ז (הנחה בגוכי\"ק כ\"ק אדמו\"ר מהורש\"ב נדפסה בס' תורת שמואל דרושי חתונה שם ע' קפ ואילך).\nכמה מעניני המאמר ראה ד\"ה משמח חתן וכלה בס' מאמרי אדה\"ז על מארז\"ל ותפלה ע' תצד ואילך. ובארוכה בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תצט ואילך. וע' תקיג ואילך."],["769","2","<b>הלא. . ירידה צורך עלי' ומה\"ע כשמחך יצירך בג\"ע</b>: בהנחה מד\"ה זה תרל\"ה שם מבואר הקושיא: משמע מזה הלשון שעיקר הנושא הוא שיהי' עלי' כמו שהיתה הנשמה בתחילה בג\"ע, וצ\"ל הלא ידוע שהירידה היא ירידה עצומה כו' לצורך עלי' כו' וא\"כ לפי\"ז שתתעלה כמו שהיתה בג\"ע למה ירדה."],["770","3","<b>מה\"ע שמח תשמח ריעים האהובים</b>: בהבא לקמן עד סוף הפיסקא ראה בארוכה בד\"ה זה תרנ\"ז (סה\"מ תרנ\"ז ע' קעג-ה). וראה גם סה\"מ מלוקט ח\"ב ע' עז."],["771","4","<b>נודע ממ\"ש במ\"א בענין אכלו ריעים לעילא</b>: ראה תו\"א משפטים עח, סע\"ג. לקו\"ת צו טו, ג. מאמרי אדה\"ז כתובים ח\"ב ע' קמו-ז. סה\"מ תרל\"ג ח\"א ע' קיא."],["772","5","<b>ונודע כי השמחה היא בבינה. . אם הבנים שמחה</b>: ראה תו\"א וארא נז, ב ואילך. לקו\"ת דרושים לשמע\"צ פח, ד."],["773","6","<b>רק מועדים לשמחה אבל שבת. . מנוחה ועונג</b>: ראה לקו\"ת צו יא, ד. סה\"מ תר\"ל ע' רסב. תרל\"ב ח\"א ע' סז. וש\"נ. סה\"מ תש\"ט ס\"ע 130 ובהערת כ\"ק אדמו\"ר זי\"ע שם."],["774","7","<b>בד\"ה אז ישיר דאגוסטוס</b>: תרל\"א (לעיל ע' קנג ואילך), בו נת' הענין דאגוסטוס יושב. וראה גם ד\"ה זה תרכ\"ט ע' קמה ואילך."],["775","8","<b>וד\"ה ועשו ארון</b>: תרל\"א (לעיל ע' קפא ואילך)."],["776","9","<b>תלת קשרין מתקשראן דא בדא</b>: ראה לעיל ד\"ה אז ישיר. וש\"נ."]]],[2000510267,"וקוב\"ה וכולהו דרגין על דרגין סתים וגליא, דהגם שהנשמה היא חלק אלוק' ממעל<sup data-n=\"777\">10</sup>, מ\"מ מצד]<sup data-n=\"778\">11</sup> הנשמה כמו שמלובשת בגוף מתקשראין באורייתא סתים וגליא. אמנם ענין התורה שיומשך בה המשכת התורה ברוחניות, כמו מה שלומדין בג\"ע<sup data-n=\"779\">12</sup> וכדומה, זהו ע\"י ישראל. וגם ע\"ד דוד הי' מחבר תורה שלמעלה<sup data-n=\"780\">13</sup> בהקב\"ה, שזהו בחי' המשכת אוא\"ס ע\"י שורש ומקור נש\"י שלא כל הנשמה מלובש בגוף כמ\"ש בלק\"ת בשה\"ש בד\"ה יונתי בחגוי כו'. ואי לזאת עדיין צ\"ל דא\"כ שורש הנשמה<sup data-n=\"781\">14</sup> יכולה להמשיך יותר המשכת אלקות עד שע\"י נק' נש\"י חתן לגבי התורה, וא\"כ למה ירדה הנשמה בגוף ומהו העלי', הלא גם כמו שנתלבשה יש יתרון להנשמה שאינה מלובשת.\n<b>אך</b> הענין דבכדי שתמשיך שורש הנשמה המשכת אוא\"ס בתורה<sup data-n=\"782\">15</sup> זהו ע\"י הנשמה המלובשת בגוף, וזה\"ע התפלה שנק' סולם מוצב ארצה, שכמו הסולם מחבר הגג עם הארץ כן סולם דתפילה מחברת נשמה המלובש בגוף עם שורש ומקור הנשמה, ולכן מתחלת התפילה מדברים תחתונים שלא עשני עבד עד שעולה בשליבות הסולם פסוד\"ז וברכת ק\"ש עד ק\"ש למסור נפשו באחד ושמו\"ע המשכת אוא\"ס מפני כי מגיע לשורש נפשו, ואז תוכל הנשמה מצד שורש נפשה להמשיך המשכת אוא\"ס ב\"ה בתורה, וזהו\"ע על שלא ברכו בתורה הוא בחי' המשכת אוא\"ס בתורה.\n<b>ועפ\"ז</b> יובן ענין כשמחך יצירך שאין הכוונה היצירה לבדה כמו שהיא, רק המכוון מה שיוצא ע\"י היצירה שע\"י ירידה זו נעשה עלי', כי שורש הנשמה מפנימיות הכלים<sup data-n=\"783\">16</sup> וע\"י ירידתה והתקשרות נשמה שבגוף לשורש הנשמה ע\"ד העבודה מלמטלמ\"ע אז ע\"י התורה מלמעלמ\"ט ממשיכים אוא\"ס בתורה כו', ועי\"ז מתעלי' הנשמות לבחי' האור, ונמצא שהעלי' הוא מכלים לאורות<sup data-n=\"784\">17</sup>. וע\"ז היתה השמחה שבשעת היצירה, להיות כי הוא צופה ומביט ומגיד מראשית אחרית, לכן אמר כשמחך יצירך בג\"ע מקדם היינו מקדם עד שלא נעשה עדיין<sup data-n=\"785\">18</sup>, ומ\"מ השמחה הוא ע\"י העלי' שע\"י הירידה.",[["777","10","<b>שהנשמה היא חלק אלוק' ממעל</b>: ראה תניא רפ\"ב (ע\"פ איוב לא, ב) ושם מוסיף תיבת: ממש."],["778","11","<b>[ביום חתונתו. . מ\"מ מצד]</b>: בגוכי\"ק נרשם כאן בתחילה: דשניהם אמת, דמצד. [ואח\"כ נוסף ע\"ז הגה\"ה כבפנים]."],["779","12","<b>התורה ברוחניות. . שלומדין בג\"ע</b>: ראה לקו\"ת תזריע כב, ד. סה\"מ תרל\"ה ח\"ב ע' תנא ואילך. תרל\"ח ע' קסא ואילך. וש\"נ. תרע\"ח (הוצאת תשד\"מ) ע' תטז. המשך תער\"ב ח\"א ע' שסח-ט. תרפ\"ז ס\"ע קפז-ח. תרפ\"ט ע' 157 ואילך. תש\"א ע' 38. תש\"ו ע' 112."],["780","13","<b>ע\"ד דוד הי' מחבר תורה שלמעלה</b>: ראה גם תו\"א תולדות יח, ג. לקו\"ת שלח מז, ג. נא, א. ובכ\"מ."],["781","14","<b>דא\"כ שורש הנשמה</b>: בד\"ה זה בסה\"מ תרל\"ה: דא\"כ שע\"י הנשמה."],["782","15","<b>וז\"ע על שלא ברכו בתורה. . המשכת אוא\"ס בתורה</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ט ע' ריא. אוה\"ת פנחס ע' א'קל. א'קמב. ואתחנן ע' תב-ג. סה\"מ תרכ\"ט ס\"ע רפט ואילך. [ובהנסמן שם]."],["783","16","<b>שורש הנשמה מפנימיות הכלים</b>: ראה לקו\"ת ראה כו, רע\"ד. דרושים ליוהכ\"פ ע, ג. ובכ\"מ."],["784","17","<b>ונמצא שהעלי' היא מכלים לאורות</b>: ראה תו\"א יתרו עא, א. סה\"מ תר\"ם ח\"ב ע' תקב ואילך. תשכג ואילך. לעיל ע' קפב."],["785","18","<b>ומגיד מראשית אחרית. . מקדם עד שלא נעשה עדיין</b>: ראה בארוכה סה\"מ תרל\"ב ח\"א ע' קיב ואילך. [ובהנסמן שם בתחילת המאמר]."]]],[2000510268,"<b>ואמר</b> עוד שגם ריעים האהובים חו\"ב הגם שהם אורות המלובשים בכלים, וחכמה ראשית ההשתלשלות, הנה גם בהם תהי' השמחה, פי' הגילוי, כמו ששמח הוא ית' על יצירת האדם בג\"ע בבחי' קדם, שגם בסדרי ההשתלשלות יומשך גילוי אור כ\"כ כמו בבחי' קדם<sup data-n=\"786\">19</sup> שלפני ההשתלשלות כו'. וזהו שמח תשמח ריעים האהובים כשמחך יצירך בג\"ע בחי' קדם כו'. [והענין הוא דהנה בנין התהו הי' בנין ע\"מ לסתור וסתירת התהו הוא ע\"מ לבנות<sup data-n=\"787\">20</sup>, וא\"כ הרי שניהם מחודשים, אבל קדם הוא מה שהוא בחי' קדמון שאינו מחודש. וענין כשמחך יצירך בג\"ע מקדם היינו שע\"י לעשות לתקן עי\"ז יומשך מבחי' קדם בחי' קדמון, וא\"כ כשנמשך בחי' זו בחכ' ובינה פועל בהם השמחה, וזהו שמח מצד עצמו, תשמח ריעים ג\"כ הם בחי' חכ' ובינה כו'].",[["786","19","<b>כשמחך יצירך בג\"ע מקדם. . שגם בסדרי ההשתלשלות יומשך. . כמו בבחי' קדם</b>: ראה לקו\"ת צו ט, א. מאמרי אדה\"ז תקע\"א ע' סז. מארז\"ל ע' תצג. מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תכז ואילך. וע' תצב ואילך. אוה\"ת ויקרא (כרך ד) ע' תתקסט. [וראה עוד בפי' כשמחך יצירך: סידור עם דא\"ח קלו, ב. מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' רלב ואילך]."],["787","20","<b>בנין התהו. . ע\"מ לסתור וסתירת התהו. . ע\"מ לבנות</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. מאמרי אדהאמ\"צ דברים ח\"ב ע' תקפב ואילך. סה\"מ תרל\"ב ח\"ב ע' תכט. תלה. תקנט. המשך תרס\"ו ע' שנה. ובכ\"מ."]]],[2000510269,"<h3>זכור, שכן קרוב</h3>\n<b>בס\"ד.</b>\nזכור, שכן קרוב<sup data-n=\"788\">1</sup> זה יתרו<sup data-n=\"789\">2</sup> מאח רחוק ע' ע\"פ מ\"ש הרמ\"ז ר\"פ ויקהל כהן מדין יסוד אבא דקליפה, וכשנתקרב הכניע הקליפה אל הקדושה ונעשה יתרון ע\"ד יתרון האור מתוך כו', וההיפך עמלק קלי' שכנגד הדעת הנמשך מיסו\"א ד\"ע דז\"א, ועמלק מנגד ומלק כו'.\n<b>וביאור</b> הענין ראשית גוים<sup data-n=\"790\">3</sup>, כל התאוות מכסים, ועמלק יודע רבונו, ג' עליות המל', תחלה נה\"י שאין ביכולתה לקבל יותר, עד\"מ בחסד האהבה מוחין",[["788","1","<b>זכור שכן קרוב</b>: רשימה זו הוא רישומי דברים בקצרה. וב' פיסקאות הראשונות נתבארו בארוכה בהמאמר שלאח\"ז ד\"ה זכור גו' עמלק [וראה בהנסמן שם]. ומיוסד על ד\"ה זכור גו' עמלק באוה\"ת תצא ע' תתריח. וע' תתרכ. ועל מאמרי אדה\"ז תקס\"ה ח\"א ע' תיד ואילך."],["789","2","<b>שכן קרוב זה יתרו</b>: בצידי הגליון נרשם בגוכי\"ק: שוב\"ד פ' כי תצא. — והכוונה לד\"ה זכור גו' עמלק שבבוך ”שמות ויקרא במדבר דברים\" להצ\"צ פ' כי תצא, נדפס באוה\"ת תצא שם ע' תתריח ואילך. וראה שם בהבא לקמן עד סוף הפיסקא."],["790","3","<b>וביאור הענין ראשית גוים</b>: בהבא לקמן בפיסקא זו ראה בארוכה מאמרי אדה\"ז תקס\"ה שם ע' תיד ואילך. אוה\"ת נ\"ך (כרך ב) ע' תשנ ואילך. דרמ\"צ יב, ב ואילך."]]],[2000510270,"חב\"ד, חג\"ת עצם השפע, נה\"י נצח ההשפעה, וע\"ד הירכין חיצוניות, מ\"מ כליות מבשלי הזרע לגבי המל' זהו פנימיות, ולכן אשר קרך בדרך דעת לכתך אחרי בחי' האמונה, ועד\"מ הקם משנתו, כן בצאת בנ\"י ממצרים, ולכן אשר שם לו בדרך קודם מ\"ת, ולכן מלחמה זו לה' כי נש\"י לא יכלו אז ללחום כי היו רק בבחי' אמונה, ועמלק מונע ההסכם הוא בחי' נה\"י נצוח, ולכן פקידת עמלק ע\"י שמואל, להיות כי נגע בכף יריכו, ולכן עד שמואל לא הי' נבואה כי נו\"ה היו פגומים, משה ואהרן נו\"ה ושמואל בקוראי בחי' חיצוניות דנו\"ה, ומ\"מ חשוב כשניהם כי זהו הכלי להאור, ולכן תיקן הנצח וגם נצח במלחמת עמלק, וזהו שהפקידה על ידו דוקא, וההוד נשאר פגום עד מ'<sup data-n=\"791\">4</sup> שאז יתוקן ויוגמר מלחמת עמלק, ועד זמן הנ\"ל מלחמה כו' מדור דור, ל' דרא דרא היינו בכל שורה, הן בחב\"ד והן בחג\"ת והן בנה\"י, בבחי' נה\"י שבהם. וזהו שעמלק היפך יתרו, שעמלק הרחיק ויתרו קירב, ולכן טוב שכן מאח, וזהו הציווי זכור היפך הקרירות שמזה בא השכחה.\n<b>וזהו</b> שאמרו ברבות<sup data-n=\"792\">5</sup> ס\"פ אמור ס\"פ ל\"ב, מדכרין ומניחין<sup data-n=\"793\">6</sup>, פי' תנוח דעתו בצלאל, מדכרין ומשחקין ימ\"ש עמלק, איש צר ואויב. והיות כי יש זכירה לטב וזכירה לביש בזח\"א ויצא דק\"ס ע\"א, ולכן פי' בבחיי ס\"פ תצא בש' מדרש ע\"פ זכרוניכם<sup data-n=\"794\">7</sup> משלי אפר לגבי חומר גביכם איוב י\"ג י\"ב אמר הקב\"ה אותם שתי זכירות זכור כו' כי מחה אמחה כו' אם עשיתם כך תהיו בניו של אברהם שנאמר בו עפר ואפר, והיינו כי עמלק הגדלת היש בת\"א ד\"ה ועשית ציץ<sup data-n=\"795\">8</sup>, ואברהם ביטול משים עצמו כשיריים, ולכן כשזוכר ורע בעיניו הרע ויש דעמלק אף בהיותו בבחי' לכתך אחרי בחי' אתכפי' יבוא לבחי' פב\"פ אבר מ\"ה דאברהם, פי' שמביטול היש יבוא לביטול אמיתי כו'.",[["791","4","<b>מ'</b>: משיח."],["792","5","<b>וזהו שאמרו ברבות</b>: בהבא לקמן ראה אוה\"ת תצא שם ע' תתריח (סעי' ב)."],["793","6","<b>ברבות ס\"פ אמור. . מדכרין ומניחין</b>: ז\"ל המדרש שם: אמר ר\"ל מדכרין ומניחין (יש כשמזכירין אותו הוא טובה ונחת רוח לכל ואומרין עליו תנוח דעתו ינוח על משכבו, מ\"כ) מדכרין ומשחקין (ויש כשמזכירין אותו אומרין עליו ימח שמו וישחקו עצמותיו כד\"א שחיק טמיא, מ\"כ), מדכרין ומניחין בצלאל בן אורי בן חור, מדכרין ומשחקין עכן בן כרמי בן זרחי (בצלאל בן אורי למטה יהודה וכן עכן בן כרמי למטה יהודה, שניהם למטה יהודה, זה לשבח וזה לגנאי, פי' מהרז\"ו). מדכרין ומניחין פקוד את בני לוי, מדכרין ומשחקין זכור את אשר עשה לך עמלק (פקוד וזכור שניהם שווים זה לטובה וזה לרעה, פי' מהרז\"ו). מדכרין ומניחין איש יהודי היה, מדכרין ומשחקין איש צר ואויב (איש יהודי ואיש צר בשניהם כתוב איש כו' זה לטובה וזה לרעה, פי' מהרז\"ו)."],["794","7","<b>ולכן פי' בבחיי. . ע\"פ זכרוניכם</b>: בהבא לקמן עד סוף הפיסקא ראה אוה\"ת תצא שם ע' תתרכ (סעי' ז). לקמן ד\"ה זכרוניכם משלי אפר. וש\"נ."],["795","8","<b>בת\"א ד\"ה ועשית ציץ</b>: פ' תצוה פג, סע\"א-ב."]]],[2000510271,"<h3>זכור כו' עמלק כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תצוה פ' זכור, ל\"א).</b>\nיתרו ועמלק ה\"פ\nתצוה, פ' זכור\n<b>זכור</b> את אשר עשה<sup data-n=\"796\">1</sup> לך עמלק בדרך בצאתכם ממצרים, אשר קרך בדרך כו' וארז\"ל ברבות ר\"פ יתרו ע\"פ טוב שכן קרוב מאח רחוק (משלי ך\"ז), טוב שכן קרוב זה יתרו שהוא רחוק לישראל מן [עשו] אחיו של יעקב, ביתרו מה כתיב ויאמר שאול אל הקיני סורו רדו מתוך העמלקי, ובעמלק כתיב<sup data-n=\"797\">2</sup> זכור את אשר עשה לך עמלק, יעו\"ש באריכות בהרבה דברים ההפרש בין זה לזה.\n<b>ויובן</b> ענין ההפרש ביניהם להיות יתרו הי' כהן מדין שהוא בחי' יסוד אבא דקליפה, וע\"י הקירוב שנתקרב ונדבק אל הקדושה עי\"ז הכניע הקלי'<sup data-n=\"798\">3</sup> אל הקדושה ונעשה מזה תוס' וריבוי אור, עד גם שהוסיף פרשה בתורה ואתה תחזה, להורות על היתרון שהוסיף בקדושה עד שיתר פרשה בתורה וכמשנ\"ת בד\"ה ועשו ארון<sup data-n=\"799\">4</sup> עצי שטים שישראל ממשיכים המשכת אוא\"ס בתורה, ולהיות כי יתרו הי' שכן רחוק ובא להתקרב עי\"ז הוסיף תוס' אור כ\"כ ע\"י הכנעת הקלי', עד שהוסיף פרשה שלימה גם בגלי' שבתורה, שזהו להורות על היתרון שלו, שהרי כל ישראל מוסיפים המשכת אוא\"ס<sup data-n=\"800\">5</sup> בבחי' סתים שבתורה שהוא בחי' הפנימיות כו', אבל הוא להיות שכן רחוק הוא ובא להתקרב שעי\"ז הכניע הקלי' אל הקדושה עי\"ז המשיך תוס' אור כ\"כ עד שיתר פרשה בתורה גם בבחי' גליא שבתורה. ויובן זה ממה שכל ענין ירידת הנשמה בגוף הוא לצורך עלי<sup data-n=\"801\">6</sup>', דאל\"כ מהו ירידתה מבחי' גבוה כזו",[["796","1","<b>זכור את אשר עשה</b>: מאמר זה (מפ\"ב ואילך) מיוסד על ד\"ה ויאמר שמואל גו' פקדתי את אשר עשה עמלק במאמרי אדה\"ז תקס\"ה ח\"א ע' תיד ואילך. ובשינויים באוה\"ת נ\"ך (כרך ב) ע' תשנ ואילך. ובדרמ\"צ מצות גיד הנשה יב, ב ואילך. וראה גם אוה\"ת וישלח רמה, ב. [מאמר אדה\"ז הנ\"ל הוא ביאור שני לד\"ה זכור גו' עמלק וביאורו בתו\"א תצוה פד, ב. פה, ב. ונו\"א במאמרי אדה\"ז תקס\"ה שם ע' שפא ואילך. שפז ואילך]. לעניני המאמר ראה גם דרמ\"צ מצות זכירת ומחיית עמלק צד, א ואילך.\nפרק א' מהמאמר וסיומו מיוסד על ד\"ה זה באוה\"ת תצא ע' תתריח. — וראה לעיל ד\"ה זכור שכן קרוב שהוא רישומי דברים ממאמר זה.\nמאמר זה (מפ\"ב ואילך) נמצא גם לקמן ח\"ב בד\"ה וירא את עמלק גו' ראשית גוים עמלק. עניני המאמר נמצאים בשינויים והוספות בד\"ה זה בסה\"מ עטר\"ת ע' רפט ואילך. תרפ\"א ע' קסב. וע' קסט ואילך. חלק מהמאמר (פרקים א-ב) נמצא בשינויים והוספות בד\"ה זה בסה\"מ תרמ\"ז ס\"ע פ ואילך [ראה שם בסוף המאמר ע' פט: דרוש זה לוקח מד\"ה זכור כו' בס' ל\"א כו']. וראה גם: סה\"מ תרנ\"ח ע' רכ ואילך [ד\"ה ויאמר שמואל גו' פקדתי]. ד\"ה זכור גו' בסה\"מ תרפ\"ה ע' קצ-צא. ד\"ה ויאמר גו' בחר לנו אנשים תרפ\"ה שם ע' קצג ואילך. וע' רה ואילך. תש\"ט ע' 52 וע' 57 ואילך."],["797","2","<b>ובעמלק כתי'</b>: במד\"ר דפוס וילנא הנפוץ: ובעשו כתיב."],["798","3","<b>יתרו. . וע\"י הקירוב שנתקרב. . הכניע הקלי'</b>: בהבא לקמן ראה בארוכה אוה\"ת יתרו ע' תשיט ואילך. תשל ואילך. סה\"מ תרמ\"ז ס\"ע עח ואילך. עטר\"ת שם ע רפט ואילך. סה\"מ מלוקט ח\"ג ע' נח ואילך. וראה גם לקו\"ש חי\"א ע' 74 ואילך."],["799","4","<b>וכמשנ\"ת בד\"ה ועשו ארון</b>: תרל\"א (לעיל ע' קפא ואילך)."],["800","5","<b>שהרי כל ישראל מוסיפים המשכת אוא\"ס בבחי' סתי' שבתורה</b>: בד\"ה זה עטר\"ת מוסיף: והיינו רק בפנימיות התורה כו' אבל בגליא דתורה אינו מתחדש דבר [ובד\"ה זה תרמ\"ז: בעצם התורה הנגלית אינו מיתוסף מאומה כו'] וכמ\"ש לא תוסיפו ולא תגרעו שאסור לחדש דבר, וע\"י יתרו נתחדש פרשה בגליא דתורה כו'."],["801","6","<b>ירידת הנשמה. . לצורך עלי</b>: ראה לעיל ד\"ה וכל העם. וש\"נ."]]],[2000510272,"שהיתה עומדת ברום עולם באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו כו' למקום נמוך הוא הגוף ונה\"ב המעלימים ומסתירים לגמרי על אור ה' וקדושתו כו', אלא שהיא צורך עלי', ונודע כי העלי' שבנפש הוא בחי' העלאת נה\"ב להעלותה לשרשה<sup data-n=\"802\">7</sup> ומקורה קודם נפילתה בשבה\"כ, אי לזאת יובן שע\"י הכנעת הקלי' אל הקדושה ה\"ז עוד יתרון גדול על העלאת הנה\"ב שלא נפל כ\"כ למטה כמו הקלי'<sup data-n=\"803\">8</sup> ואינה מנגד כ\"כ כו', ומה ע\"י עליית הנה\"ב מתעלה הנפש כ\"כ, כ\"ש ע\"י הכנעת הקלי' שהיתרון הוא ביתר שאת ויתר עז כו' כיתרון אור מתוך החושך, וכל שהחושך הוא כפול ומכופל ביותר יותר נעשה היתרון להאור מתוך החושך, ונודע כי חשך הקלי' הוא יתר הרבה על חשכת הנה\"ב כן היתרון אור המגיע מחמת הכנעת הקלי' הוא ביתר שאת ויתר עז על הכנעת הנה\"ב כו', ולכן טוב שכן קרוב שנתקרב אל הקדושה כו'. אבל האח רחוק לא די שלא נתקרב אלא הוא מונע ומעכב בנ\"י ללחום עמהם למנוע הטוב מהם כענין מלחמת עמלק שהוא לקרר כמ\"ש אשר קרך בדרך והוא הקליפה שכנגד הדעת כמ\"ש הרמ\"ז ר\"פ ויקהל שהוא הקלי' הנמשך מיסו\"א, שיסו\"א הוא ד\"ע דז\"א, ועמלק מנגד לזה ע\"ד ומלק את ראשו, ולכן טוב שכן קרוב מאח רחוק כו'.\nב) <b>וביאור</b> ענין עמלק ופעולתו בעבודה שבנפש<sup data-n=\"804\">9</sup> יובן בהקדם פי' הפסוק ראשית גוים עמלק ואחריתו עדי אובד, שלכאורה יפלא מאחר שהוא הראשית גוים למה תהי' אחריתו עדי אובד, ולמה יגרע מכל האומות דכתיב בהם אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד. אך הענין הוא דשורש ההפרש בין קלי' עמלק לכל האומות אפי' נגד ז' אומות הכנעני כו', דבהיות ידוע ענין העובר על איזה דבר אשר ציוהו ה' זהו מחמת הרוח שטות המכסה וכמארז\"ל אין אדם עובר עבירה אלא א\"כ נכנס בו רוח שטות<sup data-n=\"805\">10</sup> המכסה על ניצוץ אלקי אשר בו, משא\"כ אם הי' מאיר בו בגילוי הארת אלקותו אשר בו לא הי' עובר ח\"ו על רצה\"ע כו' וכמו שאנו רואים שהעובר עבירה יעשה שטותי' נוראים שאם הי' מאיר בו השכל לא הי' עושה שטותי' כאלו, והיינו כי מפני רוב תאוותו",[["802","7","<b>העלי' שבנפש. . העלאת נה\"ב. . לשרשה</b>: ראה גם תו\"א וישב כט, סע\"ב. ל, ב. לקו\"ת שה\"ש לה, סע\"א-ב. ובכ\"מ."],["803","8","<b>הנה\"ב שלא נפל כ\"כ למטה כמו הקלי'</b>: בד\"ה זה תרמ\"ז מוסיף־ שהוא בחי' קליפת נוגה כמ\"ש בסש\"ב (פ\"א)."],["804","9","<b>וביאור ענין עמלק ופעולתו בעבודה שבנפש</b>: בהבא לקמן בפרק זה ראה [נוסף לדרושים שנסמנו לעיל בתחילת המאמר] תו\"א תצוה שם פג, א-ב. סידור עם דא\"ח רפא, א ואילך. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע קע ואילך. תקס\"ג ח\"א ע' קצח ואילך. תקס\"ה ח\"א שם ע' שפה ואילך. שצג ואילך. מאמרי אדהאמ\"צ שמות ח\"ב ע' תלט ואילך. תצה ואילך. תקה ואילך. תקכב ואילך. ס\"ע תקנז ואילך. אוה\"ת תצוה ע' א'תרצד ואילך. דרושים לפ' זכור ס\"ע א'תשעב ואילך. ס\"ע א'תשצא ואילך. דרמ\"צ צה, א ואילך. סה\"מ תרל\"ב ח\"א ס\"ע קיד ואילך. רמט ואילך. תרמ\"ד ע' שה ואילך. תרנ\"ו ע' שלד-ה. ד\"ה זכור גו' תרצ\"ד בסה\"מ קונטרסים ח\"ב רפה, ב ואילך (מיוסד על ד\"ה זה עטר\"ת הנ\"ל). תשל\"ג ע' 352 ואילך."],["805","10","<b>אין אדם עובר עבירה. . נכנס בו רוח שטות</b>: ראה בכ\"ז תניא פכ\"ד (ל, א). לקמן ד\"ה וסמך את ידו ע' רלא. וש\"נ. המשך וככה תרל\"ז פל\"ט ואילך. קונטרס ומעין מ\"ב ואילך."]]],[2000510273,"מאבד שכלו לגמרי עד שינהוג כאחד הפתיים וקלי הדעת, ומזה יובן שמאחר ששכלו אשר בו מאבד כ\"ש הארת אלקותו<sup data-n=\"806\">11</sup> אשר יש בניצוץ נפשו שאם היתה אצלו בשלימות לא הי' עובר עבירה, מ\"מ ענין הקלי' המנגד לו זהו כשבא לכלל מדה שבלב אם בחסד או בדין, או בפנימיות עד\"מ האהבה לאלקות מתקלקל ע\"י אהבה זרה, או היראה ממנו ית' עבור היותו פרוע בפריקת עול מחמת אשר השליך נפשו מנגד להניח א\"ע בתאוות הגסות והחומריות עד שמאבד שכלו שעושה שטותים כאחד הפתיים וקלי הדעת כו'. אמנם קלי' עמלק הוא בחי' קלי' שכנגד הדעת שאינו מניח שכלו כלל לבוא לידי מדה שבלב שבבחי' העורף מושבו לבלי יניח לו כלל לבוא לידי אהוי\"ר וכדומה, שלכן הוא הנק' ראשית גוים<sup data-n=\"807\">12</sup>, והיינו כי כל הגוים הם מגנדים לבחי' המדות כמו למדת האהבה או למדת היראה או הנצח וההוד וכדומה, אבל עמלק אינו מניח כלל לבוא לידי מדה, והיינו כי דעת נחלק לחו\"ג, והוא קלי' שכנגד הדעת, וזהו שאמרו יודע את רבונו ומתכוון למרוד בו<sup data-n=\"808\">13</sup> פי' הגם שיודע את רבונו ומ\"מ מתכוון למרוד כו' והיינו כי שאר האומות עד\"מ חסד דקלי' הוא לעומת חסד דקדושה פי' שמעלמת ומסתרת, עד\"מ הקליפה החופפת ומסתרת הפרי, אבל עמלק אין בו ההסתר וההעלם על אור אלקי כמו בז' אומות שהרי הוא יודע את רבונו, שפי' יודע הוא בבחי' דעת ממש אך שהוא דעת דקלי', כמו שבבלעם נאמר ויודע דעת עליון<sup data-n=\"809\">14</sup> שהענין הוא שמשיג ורואה בראי' שכלית גילוי אור האלקי ממש ואינו בדרך הסתר כלל וכלל, ואינו כדוגמת הקליפה של הפרי המסתרת את הפרי כו', וא\"כ לכאורה יפלא למה הוא נק' בשם קלי' כו'. אך הענין הוא דשרשו מבחי' אחוריים דדעת דקדושה והוא בחי' עורף העליון שלעומת הצואר כו'. וביאור הדבר הוא עד\"מ הצואר הוא הממוצע והמחבר את המוחין שבראש שיבואו ללב ע\"י הקנה ושט וורידין<sup data-n=\"810\">15</sup> כו', והעורף יש בו קושי וחוזק שיוכל",[["806","11","<b>שמאחר ששכלו אשר בו מאבד כ\"ש הארת אלקותו</b>: ראה ד\"ה זה תרמ\"ז: ואם שכלו מאבד כ\"ש בחי' הניצוץ האלקי שבו שהוא בבחי' הסתר והעלם. ובד\"ה זה עטר\"ת: ואם שכלו הטבעי מאבד כ\"ש שמאבד שכלו האלקי."],["807","12","<b>קלי' עמלק. . קלי' שכנגד הדעת. . שלכן הוא הנק' ראשית גוים</b>: ראה אוה\"ת תצוה ע' א'תרצד וע' א'תשמא: רש\"י והרמב\"ן בפ' בלק נדחקו איך עמלק הוא ראשית גוים, אך עפמש\"כ אתי שפיר כי שבעה גוים נמשכים כו' מז\"ת, אך עמלק כו' מהדעת הוא ראש ומקור להמדות."],["808","13","<b>וזהו שאמרו יודע את רבונו ומתכוון למרוד בו</b>: ראה עד\"ז לקמן: עמלק. . הוא יודע את רבונו. ועד\"ז בתו\"א תצוה פג, סע\"ד: עמלק הוא יודע רבונו ומכוון למרוד בו. ועד\"ז שם פה, ד. ובכ\"מ. ובלקו\"ש חי\"ט ע' 224 (וחכ\"א ע' 193) מציין ע\"ז: לשון זה מצאתיו לע\"ע בתו\"כ בחוקותי כו, יד (הובא ברש\"י בחוקותי שם. נח י, ט. לך יג, יג). — בהנ\"ל לא נאמר זה על עמלק, אבל בכ\"מ בדא\"ח מבואר זה על עמלק. ובדרמ\"צ (יג, ב. צה, א) ארז\"ל עליו יודע כו'. ועד\"ז בד\"ה זכור תרס\"ה רפ\"ג. ע\"כ. ובד\"ה זכור בסה\"מ תרס\"ה שם מעיר ע\"ז כ\"ק אדמו\"ר זי\"ע: ראה תו\"כ בחוקותי כו, יד. זח\"ב סה, א. ועצ\"ע."],["809","14","<b>עמלק. . דעת דקלי' כמו שבבלעם נא' ויודע דעת עליון</b>: ראה פלח הרמון שמות ע' שנח: ושמעתי בשם אדמו\"ר [הצ\"צ] שליט\"א שההפרש בין בלעם לבין קליפת עמלק, שהוא דעת עליון דלעו\"ז, ועמלק הוא דעת תחתון דלעו\"ז. — וראה אוה\"ת דרושים לפ' זכור ס\"ע א'תשצד."],["810","15","<b>הממוצע והמחבר את המוחין. . ללב ע\"י הקנה ושט וורידין</b>: ראה בארוכה תו\"א וארא נז, ג-ד. נח, ב ואילך. וראה גם הוספות לתו\"א ויחי קב, ג. קד, ב ואילך. סה\"מ תרל\"ב ח\"א ע' נד."]]],[2000510274,"לעכב ולא יניח כלל את המוחין שיומשכו ללב ולא מפני רוח שטות כלל שהרי יודע את רבונו כנ\"ל אלא הוא בדרך עקשות ונצחון בבחי' חוצפא בעלמא בלא טעם כלל כמ\"ש במ\"א בביאור דפ' זכור שבת\"א<sup data-n=\"811\">16</sup>, ונק' מלכותא בלא תגא, והוא שורש ענין קלי' עמלק שאע\"פ שיודע את רבונו בדעת שלימה מ\"מ הוא מתכוון למרוד בו בלא טעם בבחי' חוצפא לבד<sup data-n=\"812\">17</sup>, והיינו שאינו מניח גילוי המשכת המוחין לירד ולימשך בלב, וזהו דכתיב בי' אשר שם לו בדרך היינו מיד בצאת המוחין ממיצר הגרון הנק' מצרים כו' ואע\"פ שראה וידע כל הניסים כו'.\nג) <b>והנה</b> בצאת ישראל ממצרים נאמר בשבחם לכתך אחרי במדבר, פי' כי ביציאתם ממצרים היו ישראל עדיין בבחי' הקטנות וקבלתם הי' מבחי' נה\"י שהם אחוריים, ובעבודה היא בחי' האמונה בלבד<sup data-n=\"813\">18</sup>, ונודע כי האמונה היא בלי טעם ודעת ובלא אהבה ואיזה ענין טבעי שבלב רק בבחי' העשי' בלבד, ונק' מצד זה האמונה בחי' רגל<sup data-n=\"814\">19</sup>, והיינו כמו שברגל לא יש טעם ושכל ולא מדה שבלב כי הרי הירכין הם לבר מגופא רק שהרגל מעמיד כל הגוף על עמדו בלבד, כן בנ\"י בצאתם ממצרים לא קיבלו עדיין אור א\"ס בראשית התקרבותם אליו אלא בבחי' אחוריים שהוא בחי' נה\"י שבהם גופא היינו בחי' נה\"י שבנה\"י, והוא האמונה בלבד כמ\"ש ויאמינו בה' כו' כי לא היו יכולים לקבל עדיין בבחי' הפנימיות חב\"ד וחג\"ת, אפי' חב\"ד וחג\"ת דנה\"י וכ\"ש חב\"ד וחג\"ת עצמן כו' מחמת קוטנם כו', ולכן שבחם הוא לכתך אחרי מה שהלכו אחר בחי' הארה אלקי' שמבחי' אחורי' בלבד שגם זה הוא שבח גדול, ואדרבה י\"ל שזהו שבח יותר שהרי לא השיגו רק בחי' אחורי' מנה\"י היינו בחי' נה\"י שבנה\"י מ\"מ הלכו אחריו כו'.\n<b>ומפני</b> מה עשה להם ה' ככה ולא נתן להם לב לדעת השגות עליונות יותר נעלים וגבוהי', שלכאורה הלא אנחנו בנ\"י הוא עמו ונחלתו אשר בחר לו ולמה ימנע הטוב בהארת אלקי' מעמו ישראל אשר בחר לו. אך הענין הוא שאנו רואים בענין הארת אלקות בשורש ומקור כנס\"י היא בחי' המל' דכתיב ותקם בעוד לילה ותתן טרף לביתה שבחי' המל' יורדת בכל לילה ליתן טרף לבי\"ע<sup data-n=\"815\">20</sup>, ובבוקר היא עולה מירידתה למעלה באצי', ותחילת עלייתה היא בבחי' אחוריים דז\"א בלבד דהיינו להלביש בחי' נה\"י דז\"א בלבד ואח\"כ חוזרת פב\"פ כו'. ולהבין מהו בחי' אחורי' דז\"א שהוא בחי' נה\"י שבו, הנה ידוע שכל מדה ומדה נחלקה לג' מדריגות<sup data-n=\"816\">21</sup>",[["811","16","<b>כמ\"ש במ\"א בביאור דפ' זכור שבת\"א</b>: בד\"ה ויאמר גו' פקדתי בס' מאמרי אדה\"ז תקס\"ה שם: כמ\"ש למעלה בביאור דפ' זכור באריכות. וראה תו\"א תצוה שם פה, ד."],["812","17","<b>ונק' מלכותא בלא תגא. . בבחי' חוצפא לבד</b>: ראה סנהדרין קה, סע\"א: חוצפא, מלכותא בלא תאגא (כתר מלכות). וראה מאמרי אדה\"ז הקצרים ע' מא. ובכ\"מ."],["813","18","<b>לכתך אחרי במדבר. . ובעבודה היא בחי' האמונה בלבד</b>: ראה בארוכה שער האמונה לאדהאמ\"צ ב, ב ואילך. ובכ\"מ."],["814","19","<b>ונק'. . האמונה בחי' רגל</b>: ראה גם לקו\"ת דרושים לר\"ה סג, ד. ובכ\"מ. נת' בסה\"מ תרפ\"א שם ע' קעג (בשולי הגליון)."],["815","20","<b>ותקם בעוד לילה. . המל'. . ליתן טרף לבי\"ע</b>: ראה הוספות לתו\"א קי, א. לקו\"ת אמור לו, רע\"ב. אוה\"ת מסעי ע' א'ת ואילך. ובכ\"מ."],["816","21","<b>ידוע שבכל מדה. . נחלקה לג' מדריגות</b>: בהבא לקמן ראה [נוסף להנסמן לעיל בתחילת המאמר] תו\"א וארא נח, ג. דרמ\"צ עח, א. צז, סע\"א ואילך. אוה\"ת קדושים ע' קכג. ועוד."]]],[2000510275,"חב\"ד חג\"ת נה\"י שהם ראש תוך סוף, וכן כל נקודה נחלקה לג' בחי' הנ\"ל רת\"ס נק' סת\"ר שהוא פנימי אמצעי חיצון, והם ג\"כ בחי' עבור יניקה מוחין<sup data-n=\"817\">22</sup>, וא\"כ גם המדות שבלב נחלקו לג' מדריגות הנ\"ל שהם רת\"ס חב\"ד חג\"ת נה\"י, דהיינו ע\"ד דוגמא הנה כמו אור מדת החסד שהוא ימצא מצד ב' מדריגות, הא' מצד האהבה שאוהב לזולתו והרי האהבה זאת היא בחי' הפנימיות של אותו החסד ששופע לזולתו, וא\"כ האהבה הוא בחי' המוחין של החסד ההוא, כלומר כמו בחי' השכל והטעם לאותו החסד והוא אור האהבה שמפני איזהו טעם ושכל בודאי כידוע, ונק' האהבה בחי' חכמה שבחסד מפני היותו בחי' המוחין של החסד. והחסד עצמו הוא בחי' הוויתור של ההשפעה הוא בחי' חסד שבחסד שהוא מהות החסד, והוא שפע החסד שימצא גם שלא מצד האהבה ג\"כ, כי גם למי שאינו אוהבו כלל ואינו מכירו כלל ישפיע לו רב טוב מצד מהות טבעיות חסדו היינו מפני שהוא וותרן בטבעו, וכמו אאע\"ה שנק' איש החסד מפני שהי' וותרן בטבעו גם שלא מצד האהבה כמו שנתן מזון ורב טוב גם לערביים אורחים ועוברי דרך יהי' מי שיהי' הגם שאינו מכירם כלל ולא הי' לו אהבה אליהם כלל, שהרי הערביי' בודאי לא אהב אותם כלל מפני רוע מעשיהם כו', אך מפני שהי' איש החסד בטבעו דהיינו בבחי' חסד שבחסד שהוא מהות החסד עצמו כו' וכמו שבקש לו ישמעאל יחי' לפניך הגם שהי' מכיר את ישמעאל מ\"מ בקש רחמים עליו מפני עצם טבע חסדו<sup data-n=\"818\">23</sup> שמטבע הטוב להטיב, וזהו מדריגה השנית שבחסד. ומדריגה השלישית הוא בחי' נצח שבחסד שהוא ענף החסד, והענין הוא דהנה בחסד שבחסד הנ\"ל הגם שיוכל להיות בלא אהבה כלל עכ\"ז יהי' אור שפעו בותרנות שהוא מפני התענוג שיש לו מן הנתינה וההשפעה לזולתו יהי' איך שיהי', וכמו אברהם שבודאי הי' נהנה הנאה גמורה כשהאכיל והשקה את הערביי' וכדומה, אבל יש בחי' חסד שלא יש לו שום תענוג בנתינה והשפעה זו ואינו מוותר מפני שרצונו הוא לוותר כ\"א מפני הניצוח<sup data-n=\"819\">24</sup> בלבד, דהיינו שכך עלה ברצונו להיטיב חסדו עם זולתו הגם שאינו לפי טבעו אלא רק בבחי' נצחון שמנצח א\"ע ועומד על נפשו להיות מוותר, ולא מפני הוויתור שיש לו בטבע רק שבאה ההשפעה בבחי' נצוח בלבד בלא טעם ודעת ובלא אהבה או וותרנות בטבע כלל, וא\"כ אין כאן אלא ההשפעה עצמה דהיינו רק בבחי' העשי' בלבד שהרי לא נשאר רק ההשפעה עצמה בבחי' עשי' בפו\"מ בלבד בלי ימצא בה איזהו פנימיות, וזהו הנק' בחי' נה\"י שבחסד בחי' האחוריי' שהוא בבחי' העשי' בלבד כי נסתלק ממנה כל בחי' הפנימיות דחב\"ד חג\"ת, וזהו הטעם שנק' נו\"ה בשם ערבי נחל<sup data-n=\"820\">25</sup>, והיינו שכמו הערבות שבלולב שאין בהם לא טעם ולא ריח והיינו",[["817","22","<b>בחי' עבור יניקה מוחין</b>: ראה בארוכה אוה\"ת ואתחנן ע' שכח ואילך. שלה ואילך. סה\"מ תרכ\"ז ע' קה ואילך."],["818","23","<b>שבקש לו ישמעאל יחי' לפניך. . מפני עצם טבע חסדו</b>: ראה [נוסף לדרושים שנסמנו לעיל בתחילת המאמר] אוה\"ת לך לך (כרך ד) תרצג, ב."],["819","24","<b>נצח שבחסד. . ענף החסד. . מפני הניצוח</b>: בהבא לקמן ראה בארוכה לקו\"ת מסעי צ, ג ואילך."],["820","25","<b>וזהו הטעם שנק' נו\"ה בשם ערבי נחל</b>: ראה לקו\"ת מסעי שם [ושם: בדי ערבות]."]]],[2000510276,"מפני כי הם בחי' נה\"י בלבד שהם מסולקים מכל בחי' המוחין וחג\"ת, ולכן הם נק' אחוריי' שאין בהם טעם וריח רק בחי' הניצוח בלבד כו', וזהו משל להבין בחי' המדות דאצי' למעלה שיש בהם ג' מדריגות הנ\"ל, היינו המוחין שבהם שהוא בחי' חב\"ד שבמדות, ובחי' המדות עצמם שהם בחי' חג\"ת שבמדות ובחי' נה\"י שהם בחי' האחוריי' של המדות, ועד\"ז יש בכל פרצוף ופרצוף ובכל נקודה ונקודה, וגם בפרצוף אבא שורש כל האצי' יש בחי' סת\"ר, וחב\"ד חג\"ת הם בחי' הפנימיות דאבא, ונה\"י הוא בחי' החיצוניות שע\"ז נאמר וראית את אחורי, אבל פני הוא בחי' הפנימיות דאבא לא יראו עד לע\"ל כי עין בעין כו'.\nד) <b>ועפ\"ז</b> יובן ג\"כ ענין עליית המל' בכל בוקר שהיא מלבשת רק בחי' נה\"י דז\"א בלבד שהוא בחי' האחוריי' בלבד, דהנה באמת הלא ידוע דאין ערוך בחי' הנברא לבורא מאחר שהנברא הוא בע\"ג יש מאין כו' וא\"כ גם בחי' המל' מאחר שיורדת בבי\"ע עולמות הנפרדים בבחי' יש מאין כו' הנה בעת ירידתה אין לה ערוך כלל לכמו שהיא עולה באצי' שהאצי' הוא בחי' אלקות ממש, וא\"כ בראשית העליי' של המל' בבחי' האצי' א\"א לה לקבל מאוא\"ס שבאצי' מבחי' הפנימיות מאחר שאין ערוך כלל ביניהם, ולכן היא מקבלת רק מבחי' האחוריי' והחיצוניות והוא הוא בחי' נה\"י דז\"א בלבד שנק' אחוריי', אבל במדות עצמן אין ביכולתה לקבל אפי' בחי' חסד שבחסד כ\"א מה שקולטת ואוספת לתוכה בחי' נה\"י דז\"א להיות לה למוחין, וכנודע שמנה\"י דז\"א נעשה מוחין לנוק', וה\"ז כמשל הירכין שהם לבר מגופא ובהם הכליות<sup data-n=\"821\">26</sup> מבשלי הזרע המשפיעים למל' שהן בחי' נצח והוד, וא\"כ הגם שבחי' נה\"י דז\"א הם בחי' אחוריי' לגבי המדות עצמן מ\"מ לגבי המל' הם בחי' פנימיות כו'.\n<b>ועפ\"י</b> כל הנ\"ל יובן מה שבצאת בנ\"י מבחי' המיצר דמצרים לא יכלו לקבל רק בחי' נה\"י שהוא בחי' החיצוניות, דאין זה מצדו ית' שמנע הטוב מהם כ\"א מצד קטנותם שלא הי' ביכולתם לקבל, שהרי גם שורש ומקור כנס\"י דלעילא היא בחי' המל' בעלותה מבי\"ע שאינה בבחי' המיצר כמו מצרים שהיא ערות הארץ אינה יכולה ג\"כ כ\"א להלביש רק בחי' חיצוני' דז\"א, והרי באמת יש הפרש הן מצד מעלתם שהמל' הוא שורש נש\"י, וגם אינה יורדת כ\"כ כו', ומ\"מ א\"א לה לקבל, כ\"ש ישראל, וע\"י ירידתם למצרים ערות הארץ הנה בעלותם לא יכלו לקבל רק מבחי' האחוריי' לבד שהיא היא בחי' האמונה בלבד כו'.\nה) <b>ומעתה</b> יובן ענין קלי' עמלק שע\"ז אמר הכתוב ראשית גוים עמלק כו' פי' מיד אחר יציאת ישראל ממצרים שהי' בהתלבשות בחי' האחוריי' כנ\"ל בא עמלק שהוא בבחי' העורף לעמוד לנגד. וביאור הענין הוא ע\"פ מה שנת\"ל שבכ\"ד יש ג' מדריגות חב\"ד חג\"ת נה\"י, וידוע שבבחי' ההשתלשלות",[["821","26","<b>נה\"י. . כמשל הירכין. . ובהם הכליות</b>: ראה בכ\"ז אגה\"ק סי' טו (קכב, ב). לקו\"ת שה\"ש כז, ג-ד. ובכ\"מ."]]],[2000510277,"מעילה לעלול הנה רק בחי' נה\"י שבעליון יורד ומתלבש למטה בעלול להיות לו למוחין<sup data-n=\"822\">27</sup>, וכמו שבחי' נה\"י שבמוחין יורדין להיות מוחין למידות שבלב כו', ועמלק שעומד בעורף למעלה והוא כנגד הצואר הממוצע בין המוח ללב הנה הוא המונע ומעכב מלצאת השפע מבחי' אחוריי' שבשכל שהוא בחי' נה\"י שבו אל המדות שבלב להיות להן למוחין היפך הדעת דבין כתפין דקדושה שהוא המביא ומחבר חו\"ב במדות, כ\"א הוא עומד באחורי דעת שבין כתפין לנגד שלא יומשך מבחי' המוחין למידות, ואם ישראל לא היו אז בקטנות כ\"כ היו יכולים בעצמם להלחם, אך מפני שהיו בבחי' הקטנות מאד מבחי' המיצר דמצרים כו' שזהו עד\"מ הקם משנתו<sup data-n=\"823\">28</sup> שמפני שהוא אחוז וקשור עדיין בחשכת חומרית גופו הבהמי', שבשעת השינה הי' הסתלקות הפנימיות מכל וכל, אז תיכף בקומו לא יוכל לקבל בנפשו שפע הפנימי מאוא\"ס רק בבחי' אמונה בלבד, וזהו שתקנו לומר תיכף בקומו משנתו מודה אני לפניך להיותו עדיין רק בבחי' האמונה בלבד, ואח\"כ ע\"י פסוד\"ז<sup data-n=\"824\">29</sup> וברכת ק\"ש אזי יכול לבוא בק\"ש באמרו ואהבת בכל לבבך לבחי' אהוי\"ר ברשפי אש ע\"י ההתבוננות כו'. כן בצאת בנ\"י ממצרים לא היו יכולים לקבל פנימיות הארת אלקותו ית' מחמת קטנותם כנ\"ל כ\"א בבחי' האמונה שהיא מבחי' נה\"י בכ\"מ לפי ערכו, ועמלק עומד בעורף כל בחי' לבלי יניח את בחי' הנה\"י הוא בחי' האחורי' מבחי' הגבוה להיות נמשך בעלול כו', ולכן אחריתו עדי אובד יתר על כל הגוים, והיינו מטעם הנ\"ל כי כל האומות המה מנגדים לבחי' המדות כשיוצאים לכלל מדה שבלב, אבל עמלק אינו מניח כלל לבוא לגילוי מהמוח ללב להיות איזהו מדה כו'. ב' שבשארי המנגדים יכולים ישראל עצמן להלחם עמהם כי זהו זלעו\"ז משא\"כ עמלק להיות כי שם לו בדרך בהיות ישראל בבחי' הקטנות לא יכלו להלחם עמו כלל, ולכן כתי' מלחמה לה' בעמלק שה' ילחם עמו אבל לא לאדם המלחמה עמו<sup data-n=\"825\">30</sup>, ולכן כאשר ירים משה ידו<sup data-n=\"826\">31</sup> אז וגבר ישראל וכמארז\"ל וכי ידיו של משה כו' אלא בזמן שישראל מסתכלים כלפי מעלה והיינו שאז ה' ילחם עמו שזהו פי' מלחמה לה' בעמלק. ופי' מדור דר ל' דרא דרא שבדרז\"ל דקיימא דרא דרא היינו בכל שורה ושורה, וכנ\"ל שבכל נקודה יש חב\"ד חג\"ת נה\"י ועמלק עומד בעורף לבלי יניח את נה\"י לבוא בגילוי במדות שבלב כו'.",[["822","27","<b>וידוע שבבחי' ההשתלשלות מעילה לעלול. . נה\"י שבעליון יורד. . להיות לו למוחין</b>: ראה לקו\"ת בשלח ב, ד. קרח נג, א. שה\"ש לט, א. ועוד."],["823","28","<b>עד\"מ הקם משנתו. . אחוז וקשור. . בחשכת חומריות גופו הבהמי'</b>: בהבא לקמן ראה בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכד. תורת חיים שמות (כת\"י הר\"ש סופר) קח, א ואילך. [ובהוצאת תשס\"ד ח\"א עד, ב ואילך]. המשך תער\"ב ח\"ב ע' תשלז ואילך. [ובהנסמן בהע' שלאח\"ז]."],["824","29","<b>וזהו שתקנו. . מודה אני. . ואח\"כ ע\"י פסוד\"ז</b>: בכ\"ז ראה בארוכה המשך תער\"ב ח\"א עי' תריט. שם ח\"ב ע' תשלח. סה\"מ תשי\"ב ע' 271 ואילך. תשט\"ו ע' 337 ואילך. סה\"מ מלוקט ח\"א ע' שנו. ובכ\"מ. [וראה גם בהנסמן בהערה שלפנ\"ז]."],["825","30","<b>מלחמה לה' בעמלק. . אבל לא לאדם המלחמה עמו</b>: ראה עד\"ז תו\"א תצוה פה, א. מאמרי אדה\"ז תקס\"ה ח\"א שם ע' שפו."],["826","31","<b>כאשר ירים משה ידו. . מסתכלי' כלפי מעלה</b>: ראה סה\"מ פר\"ת ע' רפז. רצו. תרפ\"ה שם ע' קצג. רט. תש\"ט שם ע' 51. וע' 66."]]],[2000510278,"<b>ולכן</b> הי' פקודת עמלק ע\"י שמואל דוקא, כי נודע מארז\"ל ע\"פ משה ואהרן בכוהניו ושמואל בקוראי שמו<sup data-n=\"827\">32</sup> ששמואל הי' שקול כמשה ואהרן, שלכאורה יפלא זה. אך הענין הוא דשורש משה ואהרן הוא מנו\"ה דאבא<sup data-n=\"828\">33</sup>, ושמואל הי' מבחי' הכלים דנו\"ה שלכן מן משה ויהושע עד שמואל פסקה הנבואה<sup data-n=\"829\">34</sup>, להיות כי נגע בכף יריכו כו' ונשאר נו\"ה פגומים עד שמואל שתיקן הנצח במ\"ש וגם נצח ישראל לא ישקר כו' והתחיל הנבואה בישראל. ומה שמשה ואהרן ויהושע היו נביאים שגם הם היו אחר שנפגם הירך דיעקב זהו מפני כי היו בבחי' הפנימיות כי פני משה כפני חמה ויהושע כפני לבנה שזהו בחי' שפע הפנימי שנמשך משמשא לסיהרא ובבחי' הפנימי' לא הי' שום פגם אבל חיצוני' נו\"ה היו פגומי' עד שמואל שהגם כי שרשו מבחי' הכלים דנו\"ה שזהו בחי' החיצוני' רק ע\"י שתיקן הנצח התחיל הנבואה ולכן פקידת עמלק הי' על ידו דוקא כו'.\n<b>וזהו</b> טוב שכן קרוב זה יתרו שיתר פרשה בתורה ע\"י הכנעת הקלי' נעשה יתרון אור מתוך החושך כנ\"ל, מאח רחוק אחיו של יעקב שיצא עמלק שאע\"פ שיודע את רבונו בדעת שלימה מ\"מ הוא מתכוון למרוד בו ולמנוע המוחין לצאת לגילוי לידי מדה שבלב, לכן הציווי זכור את אשר עשה לך עמלק, זכרון הוא היפך השכחה<sup data-n=\"830\">35</sup> להיות כי זכרון נמשך מאבא שורש האצי', ולכן בפ' ראשונה שבתפילין קדש שהיא בחכמה נאמר ולזכרון בין עיניך, וע\"י זכור בחי' זכרון המשכות בחי' אבא עי\"ז נמשך מחיית עמלק כי אור אבא מסמא עיני החיצונים כו'.",[["827","32","<b>ושמואל בקוראי שמו. . הי' שקול כמשה ואהרן שלכאו' יפלא זה</b>: בהבא לקמן ראה בארוכה מאמרי אדה\"ז תקס\"ה שם ע' תכ."],["828","33","<b>דשורש משה ואהרן הוא מנו\"ה דאבא</b>: ראה גם סידור עם דא\"ח קז, ב. וראה לקו\"ש ח\"ו ע' 244 ואילך."],["829","34","<b>מן משה ויהושע עד שמואל פסקה הנבואה</b>: במאמרי אדה\"ז תקס\"ה שם ס\"ע תכ מוסיף: וכמ\"ש ודבר ה' הי' יקר בימים ההם אין חזון נפרץ כו', ולכאורה יפלא מאד דהלא היו בימות הזקנים והשופטים עד שמואל כמה צדיקים מופלגים מאד כמו עתניאל בן קנז וגדעון וכיוצא."],["830","35","<b>לכן הציווי זכור. . היפך השכחה</b>: בהבא לקמן ראה תו\"א תצוה שם פה, א. מאמרי אדה\"ז תקס\"ה שם ע' שפז. וע' שצז."]]],[2000510279,"<h3>אר\"ע מה זכתה אסתר למלוך על קכ\"ז מדינה</h3>\n<b>בס\"ד.</b>\n<b>אמר</b> ר' עקיבא מה זכתה אסתר<sup data-n=\"831\">1</sup> למלוך על קך\"ז מדינה, אלא תבוא אסתר בת בתה של שרה שחייתה קך\"ז שנים ותמלוך על קך\"ז מדינה.\n<b>ויובן</b> בהקדם ענין ההפרש בין ברכה להודאה<sup data-n=\"832\">2</sup>, שלכאורה לפי מ\"ש מודים אנחנו לך משמע שההודאה היא לך, והברכה רק לשמך כדכתיב ויברכו את שם כבודך כו'. והענין דבנוסח הברכה יש ל' נוכח ול' נסתר<sup data-n=\"833\">3</sup>, ברוך אתה נוכח, אשר קדשנו במצותיו וציונו נסתר, סוכ\"ע וממכ\"ע, והיינו כי אתה אותיות מאל\"ף ועד תי\"ו, ה' מוצאות, ויש באותיות ב' בחי', דבור ומח', דבור מקור עלמא דאתגלי', ומח' הוא מקור עלמין סתימין דלא כו' וכ\"ז ממכ\"ע, ויש כח המח', ע\"ד שיש ב' לבושים, לבוש דשכל ומדות הוא לבוש עצמי ע\"ד גופין, ומחדומ\"ע לבושים, וכמו שבשכל יש שכל וכח השכל, כן בלבושים דמחדומ\"ע יש מח' וכח המחשבה<sup data-n=\"834\">4</sup>, והנה גילוי המחשבה לגבי כח המחשבה הוא בטל בתכלית, במחשבה אחת כו' וז\"ע הברכה להמשיך מכח המח', וסדר ההמשכה תחלה בנש\"י ה' אלקינו ואח\"כ ה' אחד ז' רקיעים וארץ וד' רוחות, וזהו מלך העולם בחי' מלוכה, ולא ממשלה שבע\"כ כ\"א מלכותו ברצון<sup data-n=\"835\">5</sup> כו', אך צ\"ל כסדר המדריגות תחלה ממכ\"ע ואח\"כ סוכ\"ע וז\"ע נוכח ממכ\"ע, ונסתר בחי' סוכ\"ע שבברכה.\n<b>ועתה</b> יובן מה שהברכה היא רק לשמך והודאה לעצמותו, דהנה ידוע שחכמה היא ראשית ההשתל'<sup data-n=\"836\">6</sup>, פי' השתלשלות שיש להם ערך כמו שלשלת האחוזי' זב\"ז, ונמצא כי בי\"ע יש להם ערך לאצי', כי באצי' יש ג\"כ אבי\"ע<sup data-n=\"837\">7</sup> חו\"ב זו\"נ וכמו שהבינה יש לה ערך לחכמה כן בריאה יש לה ערך לאצי', וגם הדבור יש לו ערך לשכל שהרי מדברים השכל באותיות הדבור, אבל התהוות החכמה הוא בדרך",[["831","1","<b>אמר ר' עקיבא מה זכתה אסתר</b>: מאמר זה הוא קיצור מד\"ה ויהיו חיי שרה תרל\"א (לעיל ע' נז ואילך ובהנסמן שם בתחילת המאמר. וראה גם שם ע' נג ואילך). חלק מהמאמר נמצא (בשינויים) לקמן בד\"ה כי הנה יוצר הרים ע' רה ואילך. וש\"נ.\nלחלקו הראשון של המאמר (עד הפיסקא: אך עדיין צ\"ל הלא כתיב בכל יום) ראה אוה\"ת חנוכה (כרך ה) תתקלה, א ואילך. וראה גם מאמרי אדה\"ז תקס\"ח ח\"ב ע' תשז ואילך. וראה לכללות המאמר בביאוה\"ז להצ\"צ ח\"א ע' תקעא-ב. תקעט."],["832","2","<b>ויובן בהקדם ענין ההפרש בין ברכה להודאה</b>: בהבא לקמן ראה אוה\"ת חנוכה שם תתקלה, א. תתקלז, א."],["833","3","<b>דבנוסח הברכה יש ל' נוכח ול' נסתר</b>: ראה בכ\"ז לקו\"ת מסעי צא, ב ואילך. וראה גם לקו\"ת דרושים לשמע\"צ פח, א. ובכ\"מ."],["834","4","<b>בלבושים דמחדומ\"ע יש מח' וכח המחשבה</b>: ראה בארוכה אוה\"ת בשלח ע' שצ ואילך. וראה גם שם ע' תטז. ועוד."],["835","5","<b>ממשלה שבע\"כ. . מלכותו ברצון</b>: ראה (אודות ההפרש בין מלוכה וממשלה) תו\"א בראשית ג, ד. יתרו עד, ד. לקו\"ת דברים א, רע\"ב. דרושים לר\"ה נה, סע\"ב. נו, סע\"ב. שה\"ש מד, סע\"ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תצ. ובכ\"מ."],["836","6","<b>שחכ' הוא ראשית ההשתל'</b>: ראה סה\"מ תרל\"ג ח\"א ע' קנב. וע' קנו. וש\"נ."],["837","7","<b>באצי' יש ג\"כ אבי\"ע חו\"ב וזו\"נ</b>: ראה מאמרי אדה\"ז על מארז\"ל וזהר ס\"ע קצ ואילך. וע' קצט ואילך. ובתוס' הגהות בביאוה\"ז להצ\"צ ח\"א ע' סב ואילך."]]],[2000510280,"מציאה, חד ולא בחושבן. וזהו ההפרש בין ברכה להודאה<sup data-n=\"838\">8</sup>, ברכה ברוך כו' מן העולם כו' היינו מעלמא דאתכסיא לעלמא דאתגליא<sup data-n=\"839\">9</sup>, ולכן אינה שייך כ\"א מח' ראשית הגילוי ולכן תקנו הברכות חכמים עיני העדה, ראי' חכמה<sup data-n=\"840\">10</sup>, ובעבודה יש אמונה וברכה<sup data-n=\"841\">11</sup>, אמונה מקיף גנבא אפום מחתרתא<sup data-n=\"842\">12</sup> כו', ולכן הגם שקורא רחמנא יכול לעשות היפך רצונו להיותו בבחי' מקיף, אבל הברכה להמשיך בגילוי וצדיק באמונתו יחי', צדי\"ק אמנים, ד' קדושות, יו\"ד קדישים, מאה ברכות, אבל בעצמותו אינו שייך כ\"א הודאה כו' ולכן מודים אנחנו לך.\n<b>אך</b> עדיין צ\"ל הלא כתיב בכל יום אברכך, משמע לעצמותו כו', צ\"ל מה שבריאת העולם הי' בבי\"ת<sup data-n=\"843\">13</sup> הלא האל\"ף גבוה, וך\"ו דור קרא תגר ופי' בזהר לפי שאל\"ף הוא ר\"ת ארור ובי\"ת ברכה, ולכאורה הלא א' אני ראשון ואני אחרון כו' ומפני כי ר\"ת ארור לא נבה\"ע בו. והענין שכל תומ\"צ הם צמצום כל מצותיך צדק ע\"ד הנותן צדקה לעני שמצמצם א\"ע בכדי ליתן להעני, כן כל המצות מצד אוא\"ס אם חטאת כו' אם צדקת כו', ולכן אנכי ולא יהי' מפי הגבורה גבורות וצמצום להיות אנכי מקור מ\"ע לא יהי' מקור מל\"ת<sup data-n=\"844\">14</sup>. וזהו שמצד עצמותו אח עשו ליעקב ושיהי' ואוהב זהו ע\"י צמצום, ולכן לא נבה\"ע באל\"ף כי אז היו הכל שוין, וזהו שגם ארור כנען יכול לקבל מאל\"ף, ולכן נבה\"ע בבי\"ת סימן ברכה. אך איך הי' מ\"ת ע\"י אל\"ף, זהו מפני שכאשר כבר נברא בבי\"ת אז גם מהאל\"ף אין יכולים לקבל, כי ע\"י צמצום דחכמה נמשך רק לנש\"י, ולכן נמשך ך\"ו דור נגד ש' הוי' משם אורידך כו'.\n<b>ובכ\"ז</b> יובן מה שלמדו מאה ברכות מפסוק ועתה כו' מה ה' אלקיך שואל אל תקרי מ\"ה אלא מאה, כי ההפרש בין מה למאה הוא באות אל\"ף, אמנם ע\"י ביטול מ\"ה דחכמה ממשיכים האל\"ף, ואעפ\"כ לא יומשך כ\"א למקום הראוי כו'. וזהו ג\"כ בכל יום אברכך, כי סתם ברכה בחכמה ברוך יסו\"א איהו ברוך ואיהי",[["838","8","<b>וזהו ההפרש בין ברכה להודאה</b>: בהבא לקמן עד סוף הפיסקא ראה אוה\"ת חנוכה שם תתקלז, א."],["839","9","<b>ברכה. . מן העולם. . מעלמא דאתכסיא לעלמא דאתגליא</b>: ראה בכ\"ז אוה\"ת בראשית (כרך ג) תקצה, א. יהל אור להצ\"צ ע' ריח-ט. סה\"מ תרל\"ג ח\"א ע' צה ואילך. תרל\"ח ע' צד. ובכ\"מ."],["840","10","<b>חכמים עיני העדה ראי' חכמה</b>: ראה גם אגה\"ק סי\"ד (קכ, ב). לקו\"ת ואתחנן ב, ד. ג, ג. מאמרי אדה\"ז תקס\"ד ע' יז. וע' נה. וע' רב. ועוד."],["841","11","<b>ובעבודה יש אמונה וברכה</b>: להעיר מלקו\"ת עקב יז, רע\"א: וזהו\"ע אמת ואמונה שהוא ג\"כ ענין ברכה והודאה, כי אמת מקרוב שנראה בעין השכל, ואמונה ברחוק שמאמין שכך הוא האמת. וראה גם אוה\"ת בראשית (כרך ג) תקנח, א. סה\"מ תרל\"ח ע' קכ: האמונה ענין א' הוא עם הודאה."],["842","12","<b>אמונה מקיף גנבא אפום מחתרתא</b>: ראה בכ\"ז בארוכה סה\"מ תר\"ל ע' קיא. וע' רמא. תרל\"ב ח\"א ע' צ-צא. ועוד."],["843","13","<b>אך עדיין צ\"ל. . מה שבריאת העולם הי' בבי\"ת</b>: בהבא לקמן ראה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסו ואילך. מאמרי אדהאמ\"צ קונטרסים ע' ריב ואילך. ביאוה\"ז להצ\"צ ח\"א שם ע' תקעא. תקעט. ח\"ב ע' תשיח ואילך. תשכא. אוה\"ת בשלח (כרך ז) ע' ב'תרנד. ויקרא (כרך ג) ע'תתנז ואילך. וראה גם לקו\"ת ראה יט, ב. סה\"מ תרל\"ח ע' קכז. תש\"ג ע' 75. לקו\"ש חט\"ו ע' 1. חי\"ט ע' 383."],["844","14","<b>אנכי מקור מ\"ע לא יהי' מקור מל\"ת</b>: ראה גם תניא פ\"כ (כה, ב)."]]],[2000510281,"ברכה<sup data-n=\"845\">15</sup>, אמנם ע\"י מאה ברכות ממשיכים האל\"ף ג\"כ בבחי' ברכה. וזהו חיי שרה ל' שררה מל', מאה שנה כתר<sup data-n=\"846\">16</sup> בחי' אל\"ף, אמנם זהו ע\"י ועשרים שנה חו\"ב, יו\"ד במילואו ו\"ד, תרדל\"מ, ושבע שנים בכדי שיומשך למל' ז' מדות מקור לבי\"ע.\n<b>ועפ\"ז</b> יובן ענין קך\"ז מדינות באסתר<sup data-n=\"847\">17</sup>, המולך מהודו ועד כוש, הודו ל' הוד והדר<sup data-n=\"848\">18</sup>, הגם שנברא בבי\"ת מ\"מ לבש גם לבוש הוד, וע\"י חטא עה\"ד נחסר יו\"ד, ומ\"מ יכולים גם עתה להמשיך, ובכדי שיומשך בעולם זהו ע\"י עשרים ושבע, ולכן כמו חיי שרה מקור חיות העולמות שנמשך ממאה כתר זהו ע\"י עשרים ושבע, כן מל' אסתר כדי שיומשך בעולמות זהו ההמשכה מבחי' מאה ע\"י עשרים ושבע וזהו קך\"ז מדינות כו'.",[["845","15","<b>איהו ברוך ואיהי ברכה</b>: ראה בכ\"ז סידור עם דא\"ח קסה, סע\"ב ואילך. שה, ד. אוה\"ת נ\"ך (כרך ב) ע' תתקנט ואילך."],["846","16","<b>וזהו חיי שרה. . מאה שנה כתר</b>: בהבא לקמן ראה מאמרי אדה\"ז תקס\"ו ע' נ ואילך. על פרשיות התורה ח\"א ע' קלג ואילך. תו\"ח חיי שרה קכו, ב ואילך. אוה\"ת חיי שרה קי, ב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' עח ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' לה-ו. סה\"מ תר\"ל ס\"ע כג-ד. פר\"ת ע' קמז-ח."],["847","17","<b>ועפ\"ז יובן ענין קך\"ז מדינות דאסתר</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת חיי שרה קיד, א-ב."],["848","18","<b>המולך מהודו ועד כוש. . ל' הוד והדר</b>: בכ\"ז ראה בארוכה לקו\"ת שה\"ש ו, ב. אוה\"ת מגילת אסתר ע' ג-ד."]]],[2000510282,"<h3>זכרוניכם משלי עפר</h3><h3>זכרוניכם משלי עפר</h3>\nאיוב י\"ג י\"ב.\n<b>זכרוניכם</b> משלי אפר<sup data-n=\"849\">1</sup> לגבי חומר גביכם<sup data-n=\"850\">2</sup>, הבחיי בס\"פ תצא הביא בשם מדרש<sup data-n=\"851\">3</sup>, אם אתם זוכרים שני זכירות שכתבתי לכם, זכור את אשר עשה לך עמלק, וכתי' כי מחה אמחה הרי אתם בנים של אברהם שא' ואנכי עפר ואפר, ובא\"ל לגבי חומר גביכם הרי אתם יורדים למצרים. ולכאורה הלא מלחמת עמלק הי' אחר יצ\"מ, ולא מצינו שנשתעבדו עוד במצרים הגם כי שאול לא מחה את זכר עמלק. וגם משמע שהעיקר תלוי בענין הזכירה לזכור מה שעשה לך, ולא המחי' עצמה.",[["849","1","<b>זכרוניכם משלי אפר</b>: התחלת המאמר וחלקו הב' (פיסקא: וא\"כ צ\"ל, ופיסקא: וזהו זכרוניכם) מיוסד על ד\"ה זכור גו' עמלק באוה\"ת תצא ע' תתרכ. וחלקו הא' (פיסקא: וביאור הענין צ\"ל מארז\"ל, ופיסקא: אמנם הנה נודע) הוא חלק מד\"ה וכל העם רואים דלעיל [וראה בהנסמן שם בתחילת המאמר].\nמאמר זה הוא בהמשך להמאמר ד\"ה זכור גו' עמלק דלעיל. ונמצא בשינויים ובתוס' ביאור וכו' בד\"ה זכור גו' עמלק: בסה\"מ תרל\"ב ח\"א ע' קיד ואילך. [ובהנסמן שם]. וע' רמט ואילך. תרנ\"ד ע' קצו ואילך. וע' שמא ואילך. תרס\"ה ע' רי ואילך."],["850","2","<b>זכרוניכם משלי אפר לגבי חומר גביכם</b>: ראה פירש\"י עה\"פ: זכרוניכם משלי אפר, זכרוניכם נמשל לאפר, אתם סבורים להתמשל לאברהם שאמר ואנכי עפר ואפר, לגבי חומר גביכם, שוה לחומר (לעפר) יהי' גביכם אצלו, גביכם גובה שלכם."],["851","3","<b>הבחיי בס\"פ תצא הביא בשם מדרש</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בד\"ה זכור גו' עמלק תרס\"ה שם: גירסאות שונות בתנחומא (פסיקתא וילקוט), והמובא כאן הוא ע\"פ מש\"כ בבחיי. ע\"כ. וראה ע\"ז באוה\"ת תצא שם ע' תתרכ. וראה גם אוה\"ת דרושים לפ' זכור ע' א'תשפה."]]],[2000510283,"<b>והענין</b> דהנה נת' בד\"ה זכור דעמלק (ל\"א<sup data-n=\"852\">4</sup>) שענין עמלק הוא שאע\"פ שיודע רבונו מ\"מ מתכוין למרוד בו<sup data-n=\"853\">5</sup>, ולכן הוא ראשית גוים, כי כל הגוים הם לעומ\"ז דמדות שזהו ע\"פ רוח שטות המכסה כמשנ\"ת שם באריכות שהתאוה מכסה על הארת ניצוץ אלקי אשר בקרבו. אבל [עמלק] יודע את רבונו ואינו מכסה אצלו שום דבר ואדרבה ה\"ה מכוין למרוד בו, זה\"ע החוצפא והגסות שלהיותו בבחי' יש ודבר בבחי' חוצפא שגם כלפי שמיא כו'<sup data-n=\"854\">6</sup>, ולכן ע\"י הזכירה שזוכר את עמלק ורע בעיניו היש דעמלק<sup data-n=\"855\">7</sup> ה\"ה בבחי' הביטול, ולכן הרי אתם בנים של אברהם שנמשל לאפר.\n<b>וביאור</b> הענין צ\"ל מארז\"ל קיים אברהם כל התורה<sup data-n=\"856\">8</sup> כולה עד שלא ניתנה, וא\"כ צ\"ל מה\"ע מ\"ת, מאחר שגם קודם מ\"ת קיים אברהם כו'. אך הענין הוא דהנה מה שקיים אברהם זהו הכל ברוחניות, שהרי איך קיים מצות תפילין עד\"מ שכ' בפ' קדש בענין יציאת מצרים שעדיין לא הי' גם שעבוד מצרים אלא שקיים ברוחניות<sup data-n=\"857\">9</sup>, ועד\"ז קיים כל המצות ע\"י הכנסת אורחים וגמ\"ח, וכן יצחק ע\"י מדת הפחד ויעקב ע\"י קו האמצעי, ולכן כאו\"א מהאבות הי' צריך לקיים כפי מדריגתו דוקא, משא\"כ אחר שניתנה תורה הרי ב\"ש וב\"ה הם חו\"ג ואעפ\"כ קיום התורה שלהם שוין והיינו מפני כי מה שקיימו האבות זהו ע\"י עבודתם עצמן במס\"נ ולכן הי' צריך להיות כאו\"א לפי מדריגתו, אבל לאחר שניתנה תורה הרי ניתן הכח שכאשר יעשו מצוה זו ימשיכו על ידה המשכת אלקות ולכן בזה יד כולם שוה כו'.\n<b>אמנם</b> הנה נודע כי הנברא ע\"י עבודתו אינו יכול להגיע כ\"א לשורש מדריגתו לבד, והראי' לזה הוא ממארז\"ל ש\"מ מעיין עין עיטם<sup data-n=\"858\">10</sup> הי' גבוה מקרקע",[["852","4","<b>נת' בד\"ה זכור דעמלק (ל\"א)</b>: לעיל ע' קצג."],["853","5","<b>עמלק. . שיודע רבונו מ\"מ מתכוין למרוד בו</b>: ראה בהנסמן ע\"ז לעיל ד\"ה זכור גו' עמלק שם."],["854","6","<b>חוצפא שגם כלפי שמיא כו'</b>: ראה סנהדרין קה, א: חוצפא אפילו כלפי שמיא מהני."],["855","7","<b>שזוכר את עמלק ורע בעיניו היש דעמלק</b>: בד\"ה זכור גו' עמלק תרל\"ב מוסיף כאן: פי' מלבד מה שהוא רחוק ממנו להיותו רע בעיניו, הנה הוא דואג על ענין מציאת אופן וענין רע כזה."],["856","8","<b>וביאור הענין צ\"ל מארז\"ל קיים אברהם כל התורה</b>: בהבא לקמן בפיסקא זו ושלאחרי' ראה בארוכה לעיל ד\"ה וכל העם. וראה בכ\"ז תו\"א יתרו סו, סע\"ד ואילך. סז, ד ואילך. עג, סע\"ג ואילך. מג\"א צו, ג ואילך. [וראה אוה\"ת יתרו ע' א'ט-י ג' שיטות בזה בדרושי אדה\"ז. עיי\"ש]. וראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' יא ואילך. מארז\"ל ע' קז ואילך. מאמרי אדהאמ\"צ שמות ח\"א ע' רנז ואילך. אוה\"ת תשא ע' א'תתקסו ואילך. פ' ראה ע' תשנד ואילך. סה\"מ תרכ\"ז ע' קס ואילך."],["857","9","<b>איך קיים מצות תפילין. . אלא שקיים ברוחניות</b>: בד\"ה זכור גו' תרל\"ב מוסיף (מהו הפי' שקיים ברוחניות): זה הי' ע\"י הכנה שעשו בעצמם איזהו עובדא בהכנת איזה דבר שע\"פ כוונתו רומז למצות תפילין, ועד\"ז בכל המצות כולם. — וראה בכ\"ז תו\"א לך לך יא, ד. יתרו סח, א ואילך. לקו\"ת שה\"ש ט, סע\"ב."],["858","10","<b>והראי' לזה הוא ממארז\"ל. . עין עיטם</b>: בהבא לקמן ראה [נוסף להדרושים שנסמנו לעיל בתחילת המאמר] מאמרי אדה\"ז הקצרים ע' ב. מארז\"ל ע' רד [בשם הע\"ח]. מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'לג. סה\"מ תרכ\"ט ע' ריא. תרס\"ב ע' רסה. תרס\"ה ע' ז. וע' רכא. תש\"ג ע' 23. לעיל ד\"ה וכל העם [ובדרושים שנסמנו שם בתחילת המאמר]."]]],[2000510284,"העזרה ך\"ג אמה ושליש, והיינו מפני כי המקוה של כה\"ג הי' ע\"ג הפתח שהי' גבוה ך' אמה, וג' אמות גובה המקוה, ואם יכולים להגביה המים בגובה יותר ממקום מוצאם מהו הראי' שמעיין עין עיטם הי' גבוה מקרקע העזרה ך\"ג אמה, אלא עכצ\"ל שא\"א להגביה המים גבוה ממוצא המים, כן כל דבר נברא א\"א להיות פעולתו גבוה משרשו. ולכן אברהם הגם שקיים כל התורה כולה מ\"מ לא הגיע כ\"א עד שרשו בלבד, ולכן וארא כו' באל שדי כו'. אבל על מ\"ת נאמר שמן תורק שמך וארז\"ל במד\"ר כל המצות שקיימו לפניך האבות ריחות היו פי' ריח אינו עצם הדבר שהרי כשמריחין ממנו כל היום לא יחסר מאומה, שזהו הוראה שאינו עצם הדבר, אבל אנו שמן תורק שמך דבר שמריקין מכלי אל כלי<sup data-n=\"859\">11</sup> היינו עצם הדבר כו'.\n<b>וא\"כ</b> צ\"ל מהו המעלה כשנזכור שתי זכירות<sup data-n=\"860\">12</sup> הרי אתם בנים של אברהם שנמשל לאפר הלא ע\"י מ\"ת זכו ישראל לבחי' היותר גבוה כו'. אך הענין הוא דהן אמת שע\"י מ\"ת זכו ישראל לבחי' היותר גבוה, מ\"מ יכול להיות שיעשה המצוה בקרירות ובדרך מצות אנשים מלומדה, אבל ע\"י הזכירות הנ\"ל הרי אתם בנים של אברהם שנמשל לאפר שהי' בבחי' ביטול, שע\"ז מורה שם אברהם הוא בחי' אבר מ\"ה<sup data-n=\"861\">13</sup>, פי' ע\"ד כמו האבר הוא כלי לחיות הנפש כו' כן הי' אברהם כלי לבחי' הביטול, ועד\"ז יהי' בקיום המצות שיהיו ב' המעלות, היינו הדבר עצמי, ושיהי' כלי לזה כמו אברהם כו'.\n<b>וזהו</b> זכרוניכם משלי אפר שע\"י הזכרון שרע בעיניו היש דעמלק עי\"ז משלי אפר הוא בחי' עפר ואפר דאברהם כו', ובא\"ל הרי אתם יורדין למצרים, פי' הגם שלא נשתעבדו במצרים עוד, אבל ארז\"ל כל הגליות נק' ע\"ש מצרים ואמרו כל האומות נק' מצרים ע\"ש שמצירים לישראל, והיינו הגם כי לא נשתעבדו בחומר ובלבנים, אמנם הנה אמרו בחמר דא ק\"ו ובלבנים דא לבון הלכתא והיינו ענין בירור ההלכות שבא לאדם ד\"ת בעבודה וביגיעה רבה ועצומה וארז\"ל הכן בחוץ מלאכתך זה מקרא ועתדה בשדה זה משנה<sup data-n=\"862\">14</sup> אחר ובנית ביתך זה גמרא, שקודם שנתרבו תלמידי שמאי והלל שלא שמשו כל צרכם לא הי' מחלוקת כלל, כ\"א מעט הנזכר בימי הזוגות, וה\"ז ברוחניות ענין השעבוד בחומר ובלבנים שזהו התיקון על הרע דעמלק וכמארז\"ל אם פגע בך מנוול זה משכהו לבהמ\"ד אם אבן הוא נימוח, ופי' בלק\"ת<sup data-n=\"863\">15</sup> שאפי' אם נעשו לבו כלב האבן יש בכח התורה למחותו, והיינו שכמו",[["859","11","<b>שמן תורק. . שמריקין מכלי אל כלי</b>: ראה גם לקו\"ת שה\"ש ג, א-ב. אוה\"ת שה\"ש (כרך א) ע' ל."],["860","12","<b>וא\"כ צ\"ל. . כשנזכור שתי זכירות</b>: בהבא לקמן בפיסקא זו ושלאחרי' ראה ד\"ה זכור גו' עמלק באוה\"ת תצא שם."],["861","13","<b>אברהם. . בחי' אבר מ\"ה</b>: ראה תו\"א מג\"א צ, א. לקו\"ת דרושים לר\"ה נו, ב. מאמרי אדה\"ז אתהלך לאזניא ע' נא. תקס\"ב ח\"א ע' צז. ועוד."],["862","14","<b>הכן בחוץ מלאכתך זה מקרא ועתדה בשדה זה משנה</b>: ראה בכ\"ז לעיל ד\"ה ויקח ה\"א."],["863","15","<b>ופי' בלק\"ת</b>: פ' האזינו עה, ד."]]],[2000510285,"המים כשנופלים טיף טיף על האבן ממחי' אותו כן ד\"ת שנמשלו למים כמ\"ש הוי כל צמא לכו למים יכולים להמחות היש דעמלק הוא שורש היצה\"ר כו'. ולכן בהעדר הזכירה נשתעבדו ישראל ברוחניות בחומר ובלבנים.\n<b>אמנם</b> הנה כתיב כימי צאתך מאמ\"צ אראנו נפלאות<sup data-n=\"864\">16</sup> שכמו ע\"י שעבוד מצרים זכו לגילוי שם הוי' כמ\"ש ושמי הוי' כו' לכן אמור לבנ\"י אני הוי' שזכו לקבלת התורה<sup data-n=\"865\">17</sup>, וע\"י מ\"ת נעשה בכאו\"א שם הוי'<sup data-n=\"866\">18</sup> שזהו מ\"ש אנכי ה' אלקיך שנעשה ה' בבחי' אלקיך ע\"י מה שפב\"פ דבר ה' עמכם ודבורו של הקב\"ה חשיב מעשה, כן ע\"י החומר ולבנים שברוחניות בחומר דא ק\"ו ובלבנים דא ליבון הלכתא<sup data-n=\"867\">19</sup> יבואו לע\"ל לגילוי פנימיות התורה. ולכן לע\"ל כתי' והניף ידו על הנהר והכהו לז' נחלים והיינו כי קרי\"ס הי' לי\"ב גזרים<sup data-n=\"868\">20</sup> שכל שבט יעלה במסלתו מן י\"ב בקר אל י\"ב גבולי אלכסוני' דז\"א דאצי', והי' הקריעה בים סוף מלכות סופא דכל דרגין, אבל לע\"ל אראנו נפלאות נו\"ן פלאות<sup data-n=\"869\">21</sup> שיניף ידו על הנהר הוא בינה והכהו לשבעה נחלים שז\"א יעלה לשרשו הוא בחי' ז\"ת דע\"י, שלכן ז\"א בעתיקא אחיד ותליא<sup data-n=\"870\">22</sup>, רק שיוצא דרך הבינה שנק' אם הבנים, וע\"י השעבוד דחומר ולבנים ברוחניות יהי' היציאה מן המיצר דבינה הוא בחי' ההשגה והבנה לבא לבחי' יחידה שבנפש בחי' שלמעלה מן השכל ויתעלו מז\"א לע\"ק ולכן והכהו לז' נחלים לבוא לשורש הז\"א כמו שהם בע\"ק כו'.",[["864","16","<b>אמנם הנה כתי' כימי צאתך מאמ\"צ אראנו נפלאות</b>: בהבא לקמן ראה גם תו\"א שמות שם מט, א. סה\"מ תרכ\"ז שם ע' פה. [ובהנסמן שם בתחילת המאמר]."],["865","17","<b>ע\"י שעבוד מצרים. . שזכו לקבלת התורה</b>: ראה בכ\"ז [נוסף להנסמן בהערה שלפנ\"ז] תו\"א שמות נד, סע\"א. וארא נו, ד. וראה גם תו\"א לך לך יא, ד. ועוד."],["866","18","<b>וע\"י מ\"ת נעשה בכאו\"א שם הוי'</b>: ראה אוה\"ת יתרו ע' תתקא. וע' תתקד-ה. יהל אור לתהלים ע' רלח ואילך. סה\"מ תרכ\"ט ע' ריב ואילך. לעיל ד\"ה וכל העם. וש\"נ."],["867","19","<b>בחמר דא ק\"ו ובלבנים דא ליבון הלכתא. . וה\"ז ברוחניות ענין השעבוד</b>: ראה תו\"א שמות מט, א. סה\"מ תרכ\"ז ע' פח ואילך. [ובהנסמן שם]."],["868","20","<b>לע\"ל כתי'. . והכהו לז' נחלים. . קרי\"ס הי' לי\"ב גזרים</b>: בהבא לקמן ראה בארוכה לקו\"ת צו יז, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנד. וע' רסו. שער האמונה לאדהאמ\"צ פג, סע\"א. סה\"מ תרל\"ה ח\"א ע' רנו ואילך. לקמן המשך והחרים סד\"ה וביום הביכורים."],["869","21","<b>אראנו נפלאות נו\"ן פלאות</b>: ראה אוה\"ת נ\"ך (כרך א) ע' תפו-ז. סה\"מ תרל\"ה ח\"ב ע' תקמא. ועוד."],["870","22","<b>שלכן ז\"א בעתיקא אחיד ותליא</b>: ראה תו\"א יתרו עב, סע\"ב-ג. עג, א. לקו\"ת שמיני יט, ב. במדבר יט, ב. חוקת נח, ב. סה\"מ תרכ\"ז ע' קז. וש\"נ."]]],[2000510286,"<h3>כי הנה יוצר הרים</h3>\n<b>בס\"ד.</b>\n<b>כי</b> הנה יוצר הרים<sup data-n=\"871\">1</sup> ובורא רוח ומגיד לאדם מה שיחו, צ\"ל ענין ברכת יוצר האדם שנודע שאדם גימ' מ\"ה, ומהו שייך ענין יצירה בשם מ\"ה.\n<b>והענין</b> יובן בהקדם מארז\"ל חייב אדם לברך מאה ברכות ולמדו זה ממ\"ש מה [ה\"א] שואל מעמך אל תקרי מ\"ה אלא מאה. ולכאורה גם זה יפלא הלא כתיב מה, ואיך אמרו אל תקרי מ\"ה אלא מאה. הנה ההפרש בין מ\"ה למאה הוא באות אל\"ף, דהנה נודע ההפרש שבין ברכה לתפילה<sup data-n=\"872\">2</sup> שברכה הוא להמשיך מה שכבר ישנו במקורו שיומשך ויתגלה למטה, אבל מה שלא יש עדיין במקורו הנעלם אינו שייך לומר שיומשך ע\"י ברכה, ולכן כתיב איש אשר כברכתו ברך אותם שלכאורה מהו אשר כברכתו, אלא שזה בא להורות שברכם איש אשר כברכתו שנמצא בשורשו ומקורו הנעלם, ברכם שיבוא מהעלם אל הגילוי ולא יתעכב כלל, ויבוא ויומשך למטה, אבל ענין התפילה הוא להמציא דבר חדש כענין רופא חולים או מברך השנים שפי' הגם אם ח\"ו נגזר עליו שימות או שנה לא טובה, הנה ע\"י התפילה ממשיכים יהי רצון שיומשך רצון חדש לרפאות החולה ולברך השנה שזהו שיומשך דבר חדש מה שלא יש בשרשו ומקורו ג\"כ כו'.\n<b>וביאור</b> הענין הנה כתיב ברוך ה' אלקי ישראל<sup data-n=\"873\">3</sup> מן העולם ועד העולם, שענין הברכה שיומשך מעלמא דאתכסיא לעלמא דאתגליא כו', שהגם שיש עולמות עד אין שיעור כמאמר ועלמות אין מספר, ועולמות אין מספר, כמש\"נ במ\"א בד\"ה ועמדו רגליו<sup data-n=\"874\">4</sup> על הר הזיתים, ובד\"ה ויצוום אל בנ\"י<sup data-n=\"875\">5</sup>, אמנם בכלל נחלקו",[["871","1","<b>כי הנה יוצר הרים</b>: מאמר זה מלבד ההתחלה וסיום (ע\"פ כי הנה יוצר הרים) הוא קיצור וחלק מד\"ה ויהיו חיי שרה תרל\"א (לעיל ע' נז ואילך. וראה גם שם ע' נג ואילך). ונמצא בשינוי ההתחלה בד\"ה לה\"ע לשון ברכת יוצר האדם בס' תורת שמואל דרושי חתונה ע' סד ואילך. ונמצא תוכנו בשינויים: בד\"ה אר\"ע מה זכתה אסתר (לעיל ע' קצט ואילך). ד\"ה כי הנה יוצר הרים בסה\"מ תרל\"ב ח\"ב ע' תקנד ואילך. תרל\"ד ע' לו ואילך. וד\"ה זה בס' תורת שמואל דרושי חתונה ע' קמב ואילך. קמו ואילך. ד\"ה להבין כו' הברכה דיוצר האדם תרמ\"ב (נדפס בס' תורת שמואל דרושי חתונה שם ע' קסב ואילך).\nלהתחלת וסיום המאמר ראה ד\"ה זה בסידור עם דא\"ח קלג, סע\"ד ואילך. קלה, ג ואילך. וראה לכללות המאמר בביאוה\"ז להצ\"צ ח\"א ע' תקעא-ב. תקעט."],["872","2","<b>נודע ההפרש שבין ברכה לתפלה</b>: בהבא לקמן (בפיסקא זו ושלאחרי') ראה בארוכה סה\"מ תרכ\"ז ע' שצד ואילך. וש\"נ. תרכ\"ט ע' ב ואילך. תרל\"ב ח\"ב ע' תמה ואילך [ובהנסמן שם בתחילת המאמר]. תרל\"ה ח\"א ע' ר ואילך. וע' רו ואילך. וראה עוד בענין ההפרש בין ברכה לתפלה: לקו\"ת ראה יט, רע\"א. אוה\"ת ויחי (כרך ו) תתשכה, א ואילך. נשא ע' ערה. שם (כרך ד) ע' א'תלח. וע' א'תמח. עקב (כרך ה) ע' ב'כו. סה\"מ תרל\"ד ע' לו ואילך. לקו\"ש ח\"ה ע' 423. וע' 427. ח\"י ס\"ע 37 ואילך. ועוד."],["873","3","<b>וביאור הענין. . ברוך ה' אלקי ישראל</b>: בכ\"ז ראה גם אוה\"ת בראשית (כרך ג) תקצה, א. יהל אור להצ\"צ ע' ריח-ט. סה\"מ תרל\"ג ח\"א ע' צה ואילך. תרל\"ח ע' צד. ובכ\"מ."],["874","4","<b>בד\"ה ועמדו רגליו</b>: סה\"מ תר\"ל ע' שכא-ב. וראה גם מאמרי אדה\"ז תקע\"א ע' נז ואילך. וש\"נ. נביאים ע' רנח ואילך."],["875","5","<b>ובד\"ה ויצוום אל בנ\"י</b>: סה\"מ תרכ\"ז ע' ק ואילך. וראה גם סה\"מ תרל\"ב ח\"ב ע' שמח ואילך. תרל\"ח ע' ב ואילך."]]],[2000510287,"על ב' בחי', עלמא דאתכסיא, ועלמא דאתגליא. וביאור ענין עלמא דאתכסיא ועלמא דאתגליא, יובן מענין מחשבה ודבור הנמצא באדם שענין פעולת הדבור הוא לגלות ההעלם, והיינו שמה שאצלו במחשבה ושכלו ועיונו נעלם לזולתו, ובכדי שיתגלה ההעלם לזולתו זהו ע\"י הדבור, שנמצא פעולת הדבור שיתגלה ההעלם, היינו מה שהי' עד כה נעלם מזולתו הנה ע\"י הדבור מתגלה לזולתו שיבין ג\"כ מה שהי' נעלם ממנו עד כה. אמנם פעולת המחשבה הוא לגלות העלם העצמי לגבי עצמו, והיינו כי בריקת וסקירת השכל הוא עדיין בהעלם עד שאינו יכול לאמר עליו כי הוא זה, להיותו נעלם ממנו עצמו עדיין מה הוא, רק ששכלו מבריק לו שנמצא בכאן איזהו דבר חדש, וכשבא לידי השגה והבנה הנה מתלבש השכל באותיות המחשבה, ונמצא כי פעולת המחשבה לגלות העלם העצמי לגבי עצמו. והנה האותיות המביאים השכל לידי גילוי בהכרח לומר שבשרשן הם קדום<sup data-n=\"876\">6</sup>, דאל\"כ מאין ימצא להם הכח והיכולת לגלות את השכל, והיינו כי שורש האותיות הם מקדמות השכל, וכ\"ש אותיות הדבור שמובילים ומגלים לזולתו שרשן עוד יותר גבוה מאותיות המחשבה אלא שקבען בפה כמש\"נ באגה\"ק בד\"ה ויעש דוד שם<sup data-n=\"877\">7</sup>. והנה אנו רואים שאותיות המחשבה הם כמו מקור לגילוי אותיות הדבור, והיינו כי בעת דברו בהכרח שיחשוב ג\"כ במחשבה, וה\"ז מחשבה השייך לדבור, וגם קודם הדבור צריך לסדר דבר מה במחשבה מה שידבר, ונמצא כי המחשבה הוא מקור המלביש את השכל קודם שיתגלה בדיבור. ועד\"ז יובן ענין עלמא דאתכסיא ועלמא דאתגליא, שבחי' עלמא דאתכסיא עם היותה עדיין בבחי' העלם, מ\"מ ה\"ז מקור שישתלשל מזה מסיום וסוף המדריגות בחי' עלמא דאתגלי', וכמ\"ש בלאה עלמא דאתכסיא ואחר ילדה בת היא בחי' מל', ולכן ותקרא שמה דינה הוא בחי' דינא דמלכותא דינא<sup data-n=\"878\">8</sup>. ועפ\"ז יובן ענין ברוך ה' אלקי ישראל מן העולם ועד העולם שהוא מעלמא דאתכסיא לעלמא דאתגליא, היינו מה שכבר ישנו במקורו הנעלם, וכענין איש אשר כברכתו ברך אותם כו'. [אבל מה שלא יש גם במקורו הנעלם אינו שייך שיומשך ע\"י בחי' ברכה. אמנם ענין התפלה הוא להיות יהי רצון שיומשך גם שינוי כנ\"ל].\n<b>אמנם</b> הנה נודע שבריאת העולם הי' באות בי\"ת<sup data-n=\"879\">9</sup> כמ\"ש בראשית ברא, ולכאורה יפלא מדוע לא נברה\"ע באות אל\"ף שהוא ראשון לכל האותיות, וך\"ו דור קרא תגר כו', ותירץ בזהר כי אל\"ף ר\"ת ארור, וא\"כ למה מ\"ת התחיל באל\"ף, וממ\"נ כו'. אך הענין דכל מצותיך צדק, כמו צדקה שצריך לצמצם א\"ע, כן כל",[["876","6","<b>האותיות המביאים השכל. . שבשרשן הם קדום</b>: ראה בכ\"ז סה\"מ תרל\"ג ח\"ב ע' שנו ואילך. וש\"נ."],["877","7","<b>כמש\"נ באגה\"ק בד\"ה ויעש דוד שם</b>: סימן ה (קו, ב)."],["878","8","<b>דינה הוא בחי' דינא דמלכותא דינא</b>: ראה גם אוה\"ת וישלח רנ, א."],["879","9","<b>אמנם הנה נודע שבריאת העולם הי' באות בי\"ת</b>: בהבא לקמן ראה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסו ואילך. מאמרי אדהאמ\"צ קונטרסים ע' ריב ואילך. ביאוה\"ז להצ\"צ ח\"א שם ע' תקעא. וע' תקעט. ח\"ב ע' תשיח ואילך. תשכא. אוה\"ת בשלח (כרך ז) ע' ב'תרנד. ויקרא (כרך ג) ע' תתנז ואילך. וראה גם לקו\"ת ראה יט, ב. סה\"מ תרל\"ח ע' קכז. תש\"ג ע' 95. לקו\"ש חט\"ו ע' 1. חי\"ט ע' 383. ועוד."]]],[2000510288,"התומ\"צ הם צמצום דמצ\"ע אם חטאת כו' אם צדקת כו', ובכדי להיות הרצון על תומ\"צ זהו ע\"י צמצום, אמנם מצד בחי' אוא\"ס המצמצם אינו תופס מקום כלל. וזהו אנכי ולא יהי' לך מפי הגבורה, אנכי מקור רמ\"ח מ\"ע, ולא יהי' מקור שס\"ה ל\"ת<sup data-n=\"880\">10</sup>, מפי הגבורה שמענו בחי' צמצום. ולכן אם הי' בריאת העולם ע\"י אל\"ף הי' נמשך יניק' לחיצוני' יותר מדאי, לזה הי' ע\"י בי\"ת סי' ברכה וע\"פ צמצום החכמה אם בחקותי תלכו כו' ונתתי גשמיכם כו', ואז אח\"כ הגם שבמ\"ת התחיל באל\"ף מ\"מ נמשך ע\"י צמצום החכמה כו'. ונמצא כי ענין הברכה שיומשך ממקור ושורש, היינו מבחי' החכמה דאיהו ברוך ואיהי ברכה<sup data-n=\"881\">11</sup>, איהי ברכה בחי' מל' מקבל הברכה, ואיהו יסו\"א ברוך משפיע הברכה כו'. אמנם ע\"י מאה ברכות עי\"ז ממשיכים גם בחי' אל\"ף שיומשך ג\"כ בבחי' ברכה כו', וזהו ע\"י בחי' ביטול דמ\"ה הוא בחי' מ\"ה שבכח מ\"ה דחכמה כמ\"ש בפרד\"ס שכח הוא בחי' יחודה עם הבינה, ומ\"ה הוא בחי' ביטול החכמה לגבי הכתר<sup data-n=\"882\">12</sup> כו', ולכן ע\"י מ\"ה שבחכמה יכולים להמשיך מבחי' אל\"ף דכתר.\n<b>ועפ\"ז</b> יובן ענין יוצר האדם<sup data-n=\"883\">13</sup>, דהנה כדי להיות ולהגיד לאדם מ\"ה שיחו פי' שיהי' שיחו בבחי' מ\"ה, כי הגם כי אדם גימט' מ\"ה הנה ענין הגימ' הוא הסתר, והיינו כי האדם בא בבחי' לבושי' רבים המעלימים ומסתירים על אור הנפש, והוא בחי' הגוף ונה\"ב, שהגוף הוא גשמי וניזון מאכילה ושתי' ושינה הגשמיות, ועכ\"ז יבוא לבחי' הביטול דמ\"ה, לזה צריך תחילה שיוצר הרים ובורא רוח, פי' להיות יצירת ההרים בכדי שיוכל לקבל בחי' חומר הרוח וכמארז\"ל שמשברו בהרים כו'. ובעבודה הרים הוא בחי' אבות, שמעשה אבות סימן לבנים, ונק' בשם יוצר להיות כי ע\"י האבות נתגלה אלקותו ית' בעולם שזהו ל' גילוי בחי' יצירה, ורוח הוא בחי' פנימיות שבהרים כנודע שגובה ההר הוא מפני שהרוח מגביה ומנפח יסוד העפר<sup data-n=\"884\">14</sup>. ועי\"ז מגיד לאדם מה שיחו, פי' מגיד ל' המשכה שאדם דעשי' יהי' ג\"כ שיחו בבחי' מ\"ה. וכמו\"כ יתפרש באצי' גופא הרים הם המדות, והרוח יוצא מבין ההרים חו\"ג מבחי' ת\"ת, וע' בד\"ה לך לך<sup data-n=\"885\">15</sup> ג' מדריגות בבחי' רוח רוה\"ק, יעו\"ש, ויצירת ההרים",[["880","10","<b>אנכי מקור רמ\"ח מ\"ע ולא יהי'. . שס\"ה ל\"ת</b>: ראה גם תניא פ\"כ (כה, ב)."],["881","11","<b>דאיהו ברוך ואיהי ברכה</b>: ראה בכ\"ז בארוכה סידור עם דא\"ח קסה, סע\"ב ואילך. שה, ד. אוה\"ת נ\"ך (כרך ב) ע' תתקנט ואילך."],["882","12","<b>מ\"ה דחכ'. . שכח. . יחודה עם הבינה ומ\"ה. . ביטול החכ' לגבי הכתר</b>: ראה בארוכה המשך וככה תרל\"ז פכ\"ה (ע' כט). ופל\"ב (ע' מג). לעיל ד\"ה ועשו ארון. לקמן המשך והחרים ד\"ה משכיל לאיתן האזרחי. ועוד."],["883","13","<b>ועפ\"ז יובן ענין יוצר האדם</b>: בהבא לקמן בפיסקא זו ראה סידור עם דא\"ח שם קלד, א. קלה, סע\"ג ואילך. מאמרי אדה\"ז על מארז\"ל ס\"ע תפט ואילך. מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' רי ואילך. וש\"נ. וע' דש ואילך."],["884","14","<b>כנודע שגובה ההר. . שהרוח מגביה ומנפח יסוד העפר</b>: ראה סידור עם דא\"ח שם קלד, רע\"א. מאמרי אדהאמ\"צ דרושי חתונה שם. וראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' קסג. תו\"ח בראשית כ, א. סא, ב. ויגש צא, ב. תו\"ח שמות (כת\"י הר\"ש סופר) קיב, ב. [ובהוצאת תשס\"ד בח\"א עז, ג]. שער האמונה לאדהאמ\"צ פס\"ח (קד, ב). אמרי בינה צז, ד. שיחת ש\"פ בהו\"ב תשמ\"ז (התוועדויות תשמ\"ז ח\"ג ע' 324 ואילך). ועוד."],["885","15","<b>וע' בד\"ה לך לך</b>: תרל\"א (לעיל ע' ל. וע' מג)."]]],[2000510289,"הוא מבחי' טורי חשוכא מדות שלמעלה מאצי'<sup data-n=\"886\">16</sup>, ועי\"ז מגיד לאדם שיהי' שיחו בבחי' מ\"ה.\n<b>וכמו\"כ</b> יובן שענין יחוד חתן וכלה הוא להוליד בדומה לו אדם גימ' מ\"ה, אמנם הנה הוא בבחי' העלמות והסתרים מהגוף ונה\"ב, כי שלש שותפים באדם ומצד חלק האב ואם הנה הוא גשמי ואיך יבוא לבחי' מ\"ה, לזה מברכין ברכת יוצר האדם שכמו כדי שיהי' מגיד לאדם מ\"ה שיחו זהו ע\"י יוצר הרים ובורא רוח, כן ע\"י ברכת יוצר האדם יוכל לבוא לבחי' מ\"ה שיהי' שיחו בבחי' מ\"ה כו'.",[["886","16","<b>טורי חשוכא מדות שלמעלה מאצי'</b>: ראה לקו\"ת דרושים לשמע\"צ פו, סע\"ד. סה\"מ תרל\"ח ע' קצז. [ובהנסמן שם]."]]],[2000510290,"<h3>וידבר כו' זאת חקת כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תשא פ' פרה, ל\"א).</b>\nפרה אדומה ופסח\nתשא, פ\"פ\n<b>וידבר</b> ה' כו' זאת חקת<sup data-n=\"887\">1</sup> התורה אשר צוה הוי' כו' ויקחו אליך פרה אדומה כו', וצ\"ל מ\"ש ב\"פ הוי' הלא נא' תחלה שהוי' דיבר אל משה והי' צריך לאמר זאת חקת התורה אשר אני מצוה, או סתם זאת חקת כו' ויקחו, ולמה נא' פעם שני אשר ציוה הוי'. וגם צ\"ל לשון חוקה הנאמר במצות פרה אדומה. הנה כתיב (תלים קי\"ט) יהי לבי תמים בחוקיך וארז\"ל במד\"ר פ' בא פי\"ט זה חוקת הפסח וחוקת פרה אדומה<sup data-n=\"888\">2</sup> למה ששניהם דומי' זל\"ז, בזה נא' זאת חקת הפסח ובזה נא' זאת חקת התורה, ואי אתה יודע איזה חוקה גדולה מזו, משל לשתי מטרונות דומות שהיו מהלכות שתיהם כאחת נראות שוות, מי גדולה מזו אותה שחברתה מלוה אותה עד ביתה והולכת אחריה, כך בפסח<sup data-n=\"889\">3</sup> נא' בו חקה, ובפרה נא' בה חקה ומי גדולה הפרה",[["887","1","<b>וידבר ה' כו' זאת חוקת</b>: חלקו הא' (מפיסקא: והענין הוא דשורש ענין גלות מצרים, עד פיסקא: ועפ\"ז יובן ענין חוקת הפסח) מיוסד על ד\"ה וידבר גו' ויצוום תקס\"ח נדפס בתוס' הגהות מהצ\"צ באוה\"ת וארא ע' קצו ואילך. ועוד הגהות ע\"ז שם ע' ריז ואילך. והביאור ע\"ז שם ע' קמו ואילך. וע' רי ואילך. ותוכנו נמצא בשינויים וכו' בד\"ה: וידבר גו' ויצוום בסה\"מ תרכ\"ז ע' צה ואילך. ובד\"ה והר סיני (והי' מספר) בסה\"מ תרכ\"ח ע' קמד ואילך. ובאריכות הביאור בד\"ה ויצוום בסה\"מ תרל\"ח ע' ב ואילך.\nחלקו הב' של המאמר (מפיסקא: ועפ\"ז יובן ענין חוקת הפסח, ואילך) מיוסד על ד\"ה ויקחו אליך באוה\"ת חוקת ס\"ע תשעז ואילך.\nהמאמר נמצא גם בד\"ה זה בסה\"מ תרכ\"ט ע' צג ואילך. ובשינויים והוספות בד\"ה זה בסה\"מ עטר\"ת ע' שיג ואילך. תרפ\"א ע' קצט ואילך. תשכ\"א ע' 296. וע' 303-302. ד\"ה וידבר גו' זאת חוקת (דש\"פ פרה) והמשכו בד\"ה החודש הזה (דפ' החודש) — תשכ\"ד (נדפסו בקונ' בפ\"ע קה\"ת תשנ\"ט, תשס\"א). סה\"מ תשכ\"ט ע' קמז ואילך. תשמ\"ח (הוצאת תשס\"ב) ע' 349 ואילך.\nלכמה מעניני המאמר ראה (בקיצור) אוה\"ת חוקת ע' תשעג-ד. וראה גם שם ע' תשצ ואילך. תתיב ואילך. שם בהוספות (הוצאת תשנ\"ח) ע' 40 ואילך."],["888","2","<b>יהי לבי תמים בחוקיך וארז\"ל. . זה חוקת הפסח וחוקת פרה אדומה</b>: בהבא לקמן ראה אוה\"ת חוקת שם ע' תשעג."],["889","3","<b>משל לשתי מטרונות. . כך בפסח</b>: ראה אוה\"ת נ\"ך ס\"ע תרנח-ט: אינו מובן איך ידומה זה להמשל. עיי\"ש."]]],[2000510291,"שאוכלי פסח צריכין לה שנא' ולקחו לטמא מעפר שריפת החטאת. ולכאורה צ\"ל מאחר שאמר תחלה למה ששניהם דומות זל\"ז, ומהו שאמר אח\"כ ואי אתה יודע איזהו חוקה גדולה מזו, הלא הם דומות. אך הענין שהכוונה שהם דומות ששניהם הם חוקות, כי יש במצות שהם ציוויים ויש שהם חוקות, ובזה הם שניהם שוים ששניהם הם חוקות, אך איזהו חוקה גדולה מחברתה, אותה שחברתה מלוה אותה, כך אוכלי פסח צריכים לפרה כו'. אך עדיין צ\"ל הלא ארז\"ל במד\"ר ר\"פ תצא ע\"פ אורח חיים פן תפלס נעו מעגלותיה לא תדע (במשלי ה') אר\"א בר כהנא אמר הקב\"ה לא תהא יושב ושוקל מצוותי' של תורה כענין שנא' ושקל בפלס הרים לא תהא אומר הואיל ומצוה זו גדולה אני עושה אותה ששכרה מרובה, והואיל וזו מצוה קלה איני עושה אותה, מה עשה הקב\"ה לא גילה לבריות מתן שכרן של מצות מנין שנא' נעו מעגלותי' לא תדע כו', חוץ משתי מצות החמורה שבחמורות והקלה שבקלות, חמורה שבחמורות כיבוד או\"א, ומתן שכרה אריכות ימים, והקלה שילוח הקן ומתן שכרה אריכות ימים, ונמצא כי לא יאות לחשוב איזהו מהן גדולה, ומפני מה אמרו איזהו גדולה מזו.\n<b>ולהבין</b> כ\"ז צ\"ל שורש ענין מצות חוקת הפסח שהי' על ענין יצ\"מ אשר נצטוינו לזכור יצ\"מ בכ\"י כמ\"ש למען תזכור את יום צאתך מאמ\"צ כל ימי חייך, ודרש בן זומא ימי חייך הימים כל ימי חייך להביא הלילות, והיינו שגם בלילות צריך לזכור ענין יצ\"מ וכ\"ש בימים כו'.\n<b>והענין</b> הוא דשרש ענין גלות מצרים<sup data-n=\"890\">4</sup> הי' בכדי שיהי' גילוי שם הוי' וכמ\"ש בתחלת סיפור גאולת מצרים וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם, רק ע\"י שעבוד מצרים זכו לגילוי שם הוי' כמ\"ש לכן אמור לבנ\"י אני הוי' והוצאתי אתכם כו' שהגאולה הי' מבחי' שם הוי' כו'. והענין הוא דהנה כתיב בראשית ברא אלקים שברה\"ע הי' ע\"י שם אלקי' וכנודע ממארז\"ל שהרקיעים היו מתפשטים עד שגער בהם הקב\"ה ואמר להם די, וז\"ע שם שדי שאמר לעולמו די, ומבחי' שם שדי הוא שורש כל ההעלמות והסתרים, שכל בחי' לגבי הגבוה ממנה הוא רק משל לבד. וכנודע בכל עולם שנה נפש שכל בחי' שלמטה הוא משל לגבי שלמעלה הימנו<sup data-n=\"891\">5</sup>, עד\"מ הארי' שלמטה הוא רק משל לבחי' הארי' שבמרכבה<sup data-n=\"892\">6</sup> שאומר קדוש וברוך, וכן הארי' דבריאה הוא רק משל לגבי בחי' החסד דאצי' שנק'",[["890","4","<b>והענין הוא דשורש ענין גלות מצרים. . שיהי' גילוי שם הוי'</b>: ראה גם תו\"א וארא נו, ד. אוה\"ת וארא ע' רמ. ובכ\"מ. — בהבא לקמן ראה דרושים ע\"פ ויצוום שנסמנו לעיל בתחילת המאמר."],["891","5","<b>שכל בחי' שלמטה הוא משל לגבי שלמעלה הימנו</b>: בהבא להלן (עד פיסקא: ”אך עדיין צ\"ל\") ראה ד\"ה ויצוום שבסה\"מ תרכ\"ז שם ע' צח ואילך. וד\"ה והר סיני שבסה\"מ תרכ\"ח שם ע' קמז ואילך. וראה גם הגהות לד\"ה ויצוום שבאוה\"ת וארא שם ע' ריז ואילך. אוה\"ת משפטים (כרך ח) ע' ג'לו ואילך. ובארוכה סה\"מ תרכ\"ט ע' קנז ואילך. וש\"נ."],["892","6","<b>עד\"מ הארי' שלמטה הוא רק משל לבחי' הארי' שבמרכבה</b>: ראה בכ\"ז אוה\"ת וארא שם ע' קצז. סה\"מ תרכ\"ט שם ע' קס. [ובהנסמן שם]. לקמן ד\"ה לא תבערו. וש\"נ."]]]]});
